CET.data.listeningByYear[2022] = [{"id":"L4","level":"CET4","type":"短文","source":"2022年6月 · 四级 · 短文","year":2022,"session":"6月","title":"免费的公开课","intro":"短文介绍面向成人的免费公开课，以及它的优势与坚持难点。","audio":"assets/audio/2022/cet4-2022-06-set1.mp3","lines":[{"sp":"Q1","en":"A new study finds that beverages containing added sugar might be harmful.","cn":"一项新研究发现，含添加糖的饮料可能有害健康。"},{"sp":"Q1","en":"In the study, researchers analyzed information from over 80,000 women and 37,000 men.","cn":"在该研究中，研究人员分析了超过8万名女性和3.7万名男性的信息。"},{"sp":"Q1","en":"Participants worked in the health profession.","cn":"参与者从事健康专业工作。"},{"sp":"Q1","en":"They were followed for approximately three decades.","cn":"他们被跟踪随访了约三十年。"},{"sp":"Q1","en":"They completed surveys about their diet every four years.","cn":"他们每四年完成一次关于饮食的调查。"},{"sp":"Q1","en":"They also answered questions about sleep and exercise and health every two years.","cn":"他们还每两年回答关于睡眠、运动和健康的问题。"},{"sp":"Q1","en":"The more beverages containing added sugar that people drank, the greater their risk of death was during the study period.","cn":"人们饮用的含添加糖饮料越多，他们在研究期间的死亡风险就越大。"},{"sp":"Q1","en":"These beverages included soda, energy drinks and sports drinks.","cn":"这些饮料包括苏打水、能量饮料和运动饮料。"},{"sp":"Q1","en":"Beverages like pure fruit juice which are sweet but do not contain added sugar were not part of the study.","cn":"像纯果汁这样味甜但不含添加糖的饮料不在本研究范围内。"},{"sp":"Q1","en":"The findings held even after the researchers considered other factors that could affect people's health.","cn":"即使在研究人员考虑了其他可能影响人们健康的因素后，这些发现仍然成立。"},{"sp":"Q1","en":"These factors included lack of exercise and not eating enough vegetables.","cn":"这些因素包括缺乏运动和蔬菜摄入不足。"},{"sp":"Q1","en":"They also included consuming too much meat.","cn":"它们还包括肉类摄入过多。"},{"sp":"Q1","en":"The scientists say that their results support limiting beverages with added sugar.","cn":"科学家们表示，他们的研究结果支持限制含添加糖的饮料。"},{"sp":"Q1","en":"They argue we should replace them with other drinks, with water being the best choice.","cn":"他们主张我们应该用其他饮料代替它们，其中水是最佳选择。"},{"sp":"Q1","en":"However, the researchers admit this is simply their recommendation.","cn":"然而，研究人员承认这只是他们的建议。"},{"sp":"Q1","en":"The study found only an association: It did not prove that drinks with added sugar cause early death.","cn":"该研究仅发现了一种关联：它并未证明含添加糖的饮料会导致过早死亡。"},{"sp":"Q3","en":"German police appealed Friday for information about the possible owners of two 17th-century oil paintings.","cn":"德国警方周五呼吁民众提供有关两幅17世纪油画可能所有者的信息。"},{"sp":"Q3","en":"Police said a 64-year-old man found the paintings in a garbage pile at a highway rest stop last month.","cn":"警方表示,一名64岁男子上个月在高速公路休息站的垃圾堆中发现了这些画作。"},{"sp":"Q3","en":"He later handed them in to the Cologne police.","cn":"他后来将它们交给了科隆警方。"},{"sp":"Q3","en":"An initial assessment by an art expert concluded the two framed paintings were originals, police said.","cn":"警方称,一位艺术专家的初步评估认定这两幅带框画作是原作。"},{"sp":"Q3","en":"One is a landscape painted by the Italian artist Pietro Bellotti dating to 1665.","cn":"其中一幅是意大利艺术家Pietro Bellotti于1665年创作的风景画。"},{"sp":"Q3","en":"The other is a painting of a boy by the 17th-century Dutch artist Samuel van Hoogstraten, date unknown.","cn":"另一幅是17世纪荷兰艺术家Samuel van Hoogstraten创作的男孩肖像画,创作日期不详。"},{"sp":"Q3","en":"Their combined worth is estimated to be around one million euros.","cn":"两幅画的总价值估计约为一百万欧元。"},{"sp":"Q3","en":"Authorities have not yet confirmed what will happen if the rightful owner is not found.","cn":"当局尚未确认如果找不到合法所有者将如何处理。"},{"sp":"Q3","en":"Nevertheless, it is speculated that they could either be handed over to the National Art Museum of Cologne or sold to the public by the local government.","cn":"不过,有人推测这些画作可能会被移交给科隆国家美术馆,或由地方政府向公众出售。"},{"sp":"Q5","en":"A four-year-old girl has walked eight kilometers through a snowy forest to seek help for her sick grandmother who later died of a heart attack.","cn":"一名四岁女孩在雪地森林中步行八公里为生病的祖母寻求帮助，祖母后来死于心脏病发作。"},{"sp":"Q5","en":"The young girl braved the threat of bears, wolves and temperatures far below freezing.","cn":"这名年幼的女孩冒着熊、狼和远低于冰点的气温威胁，在醒来发现祖母一动不动后，穿越西伯利亚偏远地区完成了这段旅程。"},{"sp":"Q5","en":"She made the journey through a remote region in Siberia after waking up to find her grandmother motionless.","cn":""},{"sp":"Q5","en":"Named locally as Karla, she lives alone with her elderly grandmother and her blind grandfather.","cn":"当地称她为Karla，她独自与年迈的祖母和失明的祖父生活在一起。"},{"sp":"Q5","en":"As a result, the girl's mother is facing a criminal case.","cn":"因此，女孩的母亲面临刑事诉讼。"},{"sp":"Q5","en":"She stands accused of leaving a minor in danger in the care of the elderly.","cn":"她被指控将未成年人置于危险之中，交由老年人照顾。"},{"sp":"Q5","en":"She also faces investigation from childcare services, who will also be asking why Karla was left alone with her vulnerable relatives.","cn":"她还面临儿童保育服务部门的调查，该部门也将询问为何让Karla独自与她脆弱的亲属待在一起。"},{"sp":"Q5","en":"The journey took place in February when temperatures average negative 26 degrees Celsius.","cn":"这段旅程发生在二月，当时平均气温为零下26摄氏度。"},{"sp":"Q5","en":"Russian reports on social media suggest the forest may have been as cold as negative 34 degrees Celsius.","cn":"俄罗斯社交媒体报道称，森林中的温度可能低至零下34摄氏度。"},{"sp":"Q5","en":"The journey was only recently confirmed by authorities.","cn":"这段旅程直到最近才得到当局确认。"},{"sp":"Q5","en":"But though she was suffering from the effects of extreme cold, the child reportedly suffered no life-threatening effects.","cn":"尽管她遭受了极寒的影响,但据报道这名儿童没有出现危及生命的症状。"},{"sp":"Q5","en":"Last year, a three-year-old boy survived alone for three days in a remote forest in the same region.","cn":"去年，一名三岁男孩在同一地区的偏远森林中独自生存了三天。"},{"sp":"Q8","en":"W: I've made a new friend recently.","cn":"W: 我最近交了个新朋友。"},{"sp":"Q8","en":"Her name is Susan and she's from South Africa.","cn":"她叫Susan，来自南非。"},{"sp":"Q8","en":"M: How did you meet her?","cn":"M: 你们怎么认识的？"},{"sp":"Q8","en":"W: We met over WeChat.","cn":"W: 我们在微信上认识的。"},{"sp":"Q8","en":"She has very cool photos on her social media.","cn":"她社交媒体上的照片很酷。"},{"sp":"Q8","en":"The photos of her hometown look amazing.","cn":"她家乡的照片看起来棒极了。"},{"sp":"Q8","en":"M: What's her hometown called?","cn":"M: 她家乡叫什么？"},{"sp":"Q8","en":"W: It's called Cape Town.","cn":"W: 叫开普敦。"},{"sp":"Q8","en":"It's in the southwest of South Africa.","cn":"在南非西南部。"},{"sp":"Q8","en":"She says it's very green and windy.","cn":"她说那里很绿，风很大。"},{"sp":"Q8","en":"The city was built by European settlers.","cn":"这座城市是欧洲殖民者建的。"},{"sp":"Q8","en":"And there's a big mountain that overlooks the city.","cn":"还有一座大山俯瞰着这座城市。"},{"sp":"Q8","en":"The mountain is called Table Mountain because it's flat at the top.","cn":"这座山叫桌山，因为它顶部是平的。"},{"sp":"Q8","en":"M: That sounds interesting.","cn":"M: 听起来很有意思。"},{"sp":"Q8","en":"What are the people there like?","cn":"那里的人怎么样？"},{"sp":"Q8","en":"W: Well, Susan says South Africa is very mixed.","cn":"W: 嗯，Susan说南非种族很多元。"},{"sp":"Q8","en":"There are black people and white people and Indian people.","cn":"有黑人、白人和印度人。"},{"sp":"Q8","en":"Susan is white.","cn":"Susan是白人。"},{"sp":"Q8","en":"She says her ancestors were from Britain.","cn":"她说她的祖先来自英国。"},{"sp":"Q8","en":"Many languages are spoken in South Africa, but she only speaks English.","cn":"南非说很多种语言，但她只说英语。"},{"sp":"Q8","en":"M: Didn't South Africa host the Football World Cup a few years ago?","cn":"M: 南非不是几年前举办过足球世界杯吗？"},{"sp":"Q8","en":"They must play football a lot then, right?","cn":"那他们一定很常踢足球吧？"},{"sp":"Q8","en":"W: I think they play football, but it's not as popular as rugby.","cn":"W: 我想他们踢足球，但没有橄榄球那么流行。"},{"sp":"Q8","en":"M: Rugby?","cn":"M: 橄榄球？"},{"sp":"Q8","en":"What's rugby?","cn":"橄榄球是什么？"},{"sp":"Q8","en":"W: Rugby is a sport with two teams and the players carry the ball in their arms and throw it at each other.","cn":"W: 橄榄球是一项两队对抗的运动，球员用手臂抱着球互相传递。"},{"sp":"Q8","en":"The ball is not round and the players push each other.","cn":"球不是圆的，球员之间会互相推搡。"},{"sp":"Q8","en":"I don't really understand the rules.","cn":"我不太懂规则。"},{"sp":"Q8","en":"I think it's very complicated.","cn":"我觉得挺复杂的。"},{"sp":"Q8","en":"M: That sounds like a very strange sport indeed.","cn":"M: 听起来确实是项很奇怪的运动。"},{"sp":"Q8","en":"Is it only South Africa that plays it?","cn":"只有南非玩这个吗？"},{"sp":"Q8","en":"W: No, it's also popular in Britain and in other former British colonies like Australia and New Zealand.","cn":"W: 不是，在英国和其他前英国殖民地像澳大利亚、新西兰也很流行。"},{"sp":"Q12","en":"M: Hi, Jennifer.","cn":"M: 嗨，Jennifer。"},{"sp":"Q12","en":"I'm really struggling with this semester's workload.","cn":"我这学期的课业负担真的让我很吃力。"},{"sp":"Q12","en":"Do you have any advice?","cn":"你有什么建议吗？"},{"sp":"Q12","en":"W: Have you considered making a study guide?","cn":"W: 你考虑过做一个学习指南吗？"},{"sp":"Q12","en":"It's a tool you can make yourself to take the stress out of studying.","cn":"这是一个你可以自己制作的工具，能减轻学习压力。"},{"sp":"Q12","en":"I've been using one since the start of last semester, and it has really helped relieve a lot of study pressure.","cn":"从上学期开始我就一直在用，真的帮我缓解了很多学习压力。"},{"sp":"Q12","en":"M: Sounds like just what I need.","cn":"M: 听起来正是我需要的。"},{"sp":"Q12","en":"My main problem is that my study folder is full of notes and worksheets, and is badly disorganized.","cn":"我的主要问题是我的学习文件夹里塞满了笔记和作业纸，而且乱七八糟的。"},{"sp":"Q12","en":"I don't know where to start.","cn":"我都不知道从哪儿开始。"},{"sp":"Q12","en":"W: Okay.","cn":"W: 好的。"},{"sp":"Q12","en":"Well, the main thing is to have everything in the right place.","cn":"嗯，最重要的是把所有东西都放对地方。"},{"sp":"Q12","en":"Whatever you're reviewing, it's important that it's arranged for your particular needs of that subject, and in the most user-friendly way you can.","cn":"不管你在复习什么，重要的是要按照你对那门科目的特定需求来安排，而且要用你能做到的最方便使用的方式。"},{"sp":"Q12","en":"What kind of learner are you?","cn":"你是哪种类型的学习者？"},{"sp":"Q12","en":"M: Um, I'm not sure.","cn":"M: 嗯，我不太确定。"},{"sp":"Q12","en":"W: Well, visual learners prefer using images, pictures, colors, and maps to organize information.","cn":"W: 嗯，视觉型学习者更喜欢用图像、图片、颜色和地图来组织信息。"},{"sp":"Q12","en":"Logical learners have a linear mind and would rather use logic, reasoning and systems.","cn":"逻辑型学习者有线性思维，更喜欢用逻辑、推理和系统。"},{"sp":"Q12","en":"I'm an emotional learner, which means I need to connect to information emotionally to understand it.","cn":"我是情感型学习者，这意味着我需要在情感上与信息建立联系才能理解它。"},{"sp":"Q12","en":"M: Oh!","cn":"M: 哦！"},{"sp":"Q12","en":"I'm very much dependent on vision as a way of taking in information.","cn":"我非常依赖视觉作为接收信息的方式。"},{"sp":"Q12","en":"W: Well, I suggest reorganizing your notes using color-coded sections in your study guides, or using idea mapping to lay out the information and make it more quickly accessible.","cn":"W: 嗯，我建议你在学习指南里用颜色编码的分区来重新组织你的笔记，或者用思维导图来布局信息，让它更快速可查。"},{"sp":"Q12","en":"M: So you think I should arrange my notes using color and pictures in place of text.","cn":"M: 所以你认为我应该用颜色和图片代替文字来安排我的笔记。"},{"sp":"Q12","en":"W: Yes, you'll probably start to grasp information a lot quicker that way.","cn":"W: 对，这样你可能会更快地掌握信息。"},{"sp":"Q12","en":"As an emotional learner, I organize my notes into a story that I can connect to and recite to myself.","cn":"作为情感型学习者，我会把笔记组织成一个我能产生共鸣并能向自己复述的故事。"},{"sp":"Q12","en":"M: That's amazing.","cn":"M: 太棒了。"},{"sp":"Q12","en":"I didn't know there were so many different ways to learn.","cn":"我都不知道原来有这么多不同的学习方式。"},{"sp":"Q16","en":"The golden rule is a moral principle which states that you should treat others the way you want to be treated yourself.","cn":"黄金法则是一条道德原则,它指出你应该以你希望被对待的方式对待他人。"},{"sp":"Q16","en":"For example, if you want people to treat you with respect, you should treat them with respect.","cn":"例如,如果你希望人们尊重你,你就应该尊重他们。"},{"sp":"Q16","en":"Different people tend to be exposed to different forms of the golden rule, based on factors such as the religion in their society.","cn":"不同的人往往会接触到不同形式的黄金法则,这取决于诸如其社会中的宗教等因素。"},{"sp":"Q16","en":"However, all forms of the golden rule revolve around the same concept.","cn":"然而,黄金法则的所有形式都围绕着同一个概念。"},{"sp":"Q16","en":"Namely, they help you treat others better, by using the way you yourself would want to be treated as a guide of how to behave.","cn":"也就是说,它们通过使用你自己希望被对待的方式作为行为指南,帮助你更好地对待他人。"},{"sp":"Q16","en":"A notable criticism of the golden rule is that its application can lead to undesirable outcomes, when it conflicts with laws and ethical principles.","cn":"对黄金法则的一个显著批评是,当它与法律和伦理原则相冲突时,其应用可能导致不良后果。"},{"sp":"Q16","en":"For example, if someone breaks the law, the golden rule would suggest that we should let them go, because we would not want to be punished ourselves.","cn":"例如,如果有人违法,黄金法则会建议我们应该放过他们,因为我们自己也不想受到惩罚。"},{"sp":"Q16","en":"However, this issue with the golden rule can be dealt with in a general manner, by viewing this principle as one of several principles that we use to guide our behavior as individuals and as a society.","cn":"然而,黄金法则的这一问题可以通过一般性方式来处理,即把这一原则视为我们用来指导个人和社会行为的若干原则之一。"},{"sp":"Q16","en":"Specifically, in the example described above, most individuals and societies choose to place laws and ethical principles above the golden rule.","cn":"具体而言,在上述例子中,大多数个人和社会选择将法律和伦理原则置于黄金法则之上。"},{"sp":"Q16","en":"This means that they strive to implement the golden rule whenever possible, as long as it doesn't clash with a more important concept.","cn":"这意味着只要不与更重要的概念发生冲突,他们就努力在任何可能的情况下实施黄金法则。"},{"sp":"Q19","en":"Today, many large corporations stress the importance of diversity on their websites, but current statistics show that the typical manager in America still tends to be white and male.","cn":"如今,许多大型企业在其网站上强调多元化的重要性,但目前的统计数据显示,美国的典型管理者仍然倾向于是白人和男性。"},{"sp":"Q19","en":"Obviously, the desire to bring about diversity has not translated into corporate reality.","cn":"显然,实现多元化的愿望尚未转化为企业现实。"},{"sp":"Q19","en":"Why useless?","cn":"为什么没有用?巴塞尔大学的一组研究人员发表了他们关于人们对工作场所多元化态度的新研究。"},{"sp":"Q19","en":"A team of researchers from the University of Basel published their new study about people's attitudes towards diversity at work.","cn":"他们发现,人们对多元化持有广泛的意见。"},{"sp":"Q19","en":"They found that people have a wide range of opinions concerning diversity.","cn":"一方面,许多人看到了多元化的价值,它可以贡献各种不同的观点,鼓励新想法,并产生创新的解决方案。"},{"sp":"Q19","en":"On the one hand, many see value in diversity, which can contribute a variety of perspectives, encourage new ideas, and generate innovative solutions.","cn":"另一方面,他们认为与观点完全不同、说不同语言或工作风格不同的人共事可能会很困难。"},{"sp":"Q19","en":"On the other hand, they assume that it might be difficult to work with someone who has completely different views, speaks a different language, or has a different style of work.","cn":""},{"sp":"Q19","en":"The actual value they attribute to diversity depends on the decision-making perspective.","cn":"他们赋予多元化的实际价值取决于决策视角。"},{"sp":"Q19","en":"Doubts about the practicability of diversity have a greater weight if a person is directly affected.","cn":"如果一个人受到直接影响,对多元化实用性的怀疑会具有更大的权重。"},{"sp":"Q19","en":"In other words, when a person's own work group is involved, they tend to prefer team members who are similar to themselves.","cn":"换句话说,当涉及一个人自己的工作团队时,他们倾向于选择与自己相似的团队成员。"},{"sp":"Q19","en":"But when people make decisions for others, they typically put together a more diverse team.","cn":"但当人们为他人做决定时,他们通常会组建一个更多元化的团队。"},{"sp":"Q19","en":"These findings could help organizations become more diverse.","cn":"这些发现可以帮助组织变得更加多元化。"},{"sp":"Q19","en":"Companies need to pay attention to who makes hiring and team decisions.","cn":"企业需要关注由谁来做出招聘和团队决策。"},{"sp":"Q19","en":"These decisions should not only be made by those directly affected.","cn":"这些决策不应仅由直接受影响的人做出。"},{"sp":"Q19","en":"People who are not directly involved in the group's daily work should also take part.","cn":"不直接参与团队日常工作的人也应该参与其中。"},{"sp":"Q22","en":"Communication can essentially be divided into two categories: the written and the spoken.","cn":"沟通本质上可以分为两类：书面沟通和口头沟通。"},{"sp":"Q22","en":"How the balance is struck between these two forms of communication—the point at which one needs to be exchanged for another—really depends on individual cultures.","cn":"如何在这两种沟通形式之间取得平衡——即在何时需要将一种形式转换为另一种形式——实际上取决于各个文化。"},{"sp":"Q22","en":"Understanding when it's appropriate to exchange one form for another can be a major key to success in international business.","cn":"理解何时适合将一种形式转换为另一种形式，可能是国际商务成功的关键因素。"},{"sp":"Q22","en":"Many cultures place a much greater value on the spoken word than the American working culture does.","cn":"许多文化对口头语言的重视程度远高于美国职场文化。"},{"sp":"Q22","en":"In parts of the Middle East, you'll find spoken word agreements are seen as seriously binding.","cn":"在中东部分地区,你会发现口头协议被视为具有严肃的约束力。"},{"sp":"Q22","en":"A person's word is linked to their honor, so verbal agreements are seen as important, whereas written contracts are taken as memos of understanding.","cn":"一个人的话语与其荣誉相关联，因此口头协议被视为重要的，而书面合同则被视为理解备忘录。"},{"sp":"Q22","en":"Western working culture tends to place a high value on the written word, and this reaches its highest level of intensity when it comes to contracts.","cn":"西方职场文化倾向于高度重视书面文字，而这在涉及合同时达到最高强度。"},{"sp":"Q22","en":"In the US, France and Germany, written contracts tend to be seen as something that must be strictly carried out.","cn":"在美国、法国和德国，书面合同往往被视为必须严格执行的东西。"},{"sp":"Q22","en":"By contrast, other cultures may not see written contracts as quite so binding.","cn":"相比之下，其他文化可能不认为书面合同具有如此强的约束力。"},{"sp":"Q22","en":"It can prove a challenge to Western businesses if your business partner wants to renegotiate terms that you thought were already agreed on.","cn":"如果你的商业伙伴想要重新协商你认为已经达成一致的条款，这可能会给西方企业带来挑战。"},{"sp":"Q22","en":"For example, a Japanese firm may have signed a contract, but they may not feel bound by every detail of it—particularly if circumstances later change.","cn":"例如，一家日本公司可能已经签署了合同，但他们可能不觉得受其每个细节的约束——特别是如果情况后来发生变化。"},{"sp":"Q22","en":"Such differences in value that different working cultures place on the written word tend to cause many problems when it comes to business relationships.","cn":"不同职场文化对书面文字所赋予的价值差异，往往会在商业关系中造成许多问题。"}],"questions":[{"q":"Who can join the open courses?","options":["Only university students","Anyone with an internet connection","Only people who pay a fee","Only employees of certain companies"],"answer":1,"explain":"原文说 anyone with an internet connection can join，只要能上网的人都可以参加。"},{"q":"What do learners receive after finishing all the assignments?","options":["A formal degree","A certificate","A job offer","A textbook"],"answer":1,"explain":"原文说 they do provide a certificate when you finish all the assignments。"},{"q":"What is the biggest challenge for these learners?","options":["The high price","The lack of teachers","Keeping disciplined","The difficult exams"],"answer":2,"explain":"原文说 The biggest challenge is not the price but the discipline，最大的挑战是自律。"}],"cloze":[{"text":"Today, however, millions of adults ______ up for free online courses every year.","answers":["sign"],"hint":"报名（sign up）"},{"text":"The biggest ______ is not the price but the discipline.","answers":["challenge"],"hint":"挑战"},{"text":"Experts suggest studying for twenty minutes a day rather than ______ everything for the weekend.","answers":["saving"],"hint":"留到、攒到"}]},{"id":"L9","level":"CET6","type":"新闻","source":"2022年6月 · 六级 · 新闻","year":2022,"session":"6月","title":"远程办公的新常态","intro":"新闻报道远程办公成为常态后企业的调整，以及潜在的隐忧。","audio":"assets/audio/2022/cet6-2022-06-set1.mp3","lines":[{"sp":"Q1","en":"W: Mr. David Jackson, a staff writer at the New Yorker, is known for his non-fiction books of adventure.","cn":"W: 大卫·杰克逊先生是《纽约客》的一名专职撰稿人，以创作冒险类非虚构作品而闻名。"},{"sp":"Q1","en":"Today, we go on a different kind of adventure: Jackson's life of parenting his offspring.","cn":"今天，我们要进行一次不同类型的冒险：杰克逊养育子女的生活。"},{"sp":"Q1","en":"David, as a parent of an 11- and a 14-year-old, what is the most interesting issue you are dealing with right now?","cn":"大卫，作为一个有一名11岁和一名14岁孩子的家长，你目前正在面对的最有趣的问题是什么？"},{"sp":"Q1","en":"M: It's easy to focus on the challenges, but so far, I find these ages to be kind of wonderful.","cn":"M: 人们很容易把注意力集中在挑战上，但到目前为止，我觉得这个年龄段还是相当美好的。"},{"sp":"Q1","en":"They are independent, and they have their own curiosities and obsessions.","cn":"他们很独立，也有自己的好奇心和痴迷点。"},{"sp":"Q1","en":"You can talk to them about fairly sophisticated subject matter such as politics.","cn":"你可以和他们谈论政治之类相当复杂的话题。"},{"sp":"Q1","en":"W: Yes, that does sound refreshing compared with talking to younger children.","cn":"W: 是的，和年幼的孩子交谈相比，这听起来确实令人耳目一新。"},{"sp":"Q1","en":"Do they ask you to proofread their essays?","cn":"他们会让你帮忙校对作文吗？"},{"sp":"Q1","en":"M: Certainly, with writing they do.","cn":"M: 会的，写作方面他们确实会。"},{"sp":"Q1","en":"I really just try to be encouraging.","cn":"我真的只是尽量给予鼓励。"},{"sp":"Q1","en":"I think at this age, editorial guidance is less important than encouragement.","cn":"我认为，在这个年龄段，编辑方面的指导不如鼓励重要。"},{"sp":"Q1","en":"W: Are there books that you think are important that your children read, and that all children read?","cn":"W: 有没有一些你认为很重要、应该让你的孩子读，也应该让所有孩子读的书？"},{"sp":"Q1","en":"M: My general thought is to read widely and to incorporate a love for reading.","cn":"M: 我的总体想法是广泛阅读，并培养对阅读的热爱。"},{"sp":"Q1","en":"Learning to love to read, I think, is the optimal thing, because it gives you a skill you can take anywhere.","cn":"我认为，学会热爱阅读是最理想的事情，因为这会赋予你一种可以带到任何地方的技能。"},{"sp":"Q1","en":"W: So you're not too concerned like some parents with the content they're reading?","cn":"W: 所以，你不像一些家长那样太在意他们阅读的内容？"},{"sp":"Q1","en":"I know I have some worries about that.","cn":"我知道自己对此有些担忧。"},{"sp":"Q1","en":"M: Yeah, read what you like.","cn":"M: 是的，喜欢读什么就读什么。"},{"sp":"Q1","en":"If a child loves graphic novels or comic books, whatever it is, that is turning them on to read and turning on their imagination.","cn":"如果孩子喜欢图像小说或漫画书，不管是什么，只要能让他们喜欢上阅读，激发他们的想象力就好。"},{"sp":"Q1","en":"W: I feel that children's tastes in books change as they reach adolescence.","cn":"W: 我觉得，随着孩子步入青春期，他们对书籍的品味会发生变化。"},{"sp":"Q1","en":"I know that mine certainly did when I was a teenager.","cn":"我知道自己十几岁时确实发生过这种变化。"},{"sp":"Q1","en":"What do you think?","cn":"你怎么看？"},{"sp":"Q1","en":"M: I think it's especially important as they get older to read subject matter that'll open their eyes to the world and people.","cn":"M: 我认为，随着他们年龄增长，阅读一些能让他们开阔眼界、了解世界和他人的内容尤其重要。"},{"sp":"Q1","en":"So I think both fiction and non-fiction are really important because they give you the power to begin to perceive the world through the lives of others.","cn":"所以我觉得，小说和非虚构作品都非常重要，因为它们赋予你一种力量，让你开始通过他人的人生来感知这个世界。"},{"sp":"Q5","en":"M: In this episode of Money Talks, our guest is Molly Sanders, a university student and a successful young entrepreneur.","cn":"M：在本期《金钱访谈》中，我们的嘉宾是莫莉·桑德斯，一名大学生，也是一位成功的年轻企业家。"},{"sp":"Q5","en":"Molly, tell us about your business.","cn":"莫莉，给我们介绍一下你的生意吧。"},{"sp":"Q5","en":"W: Well, I sell specialty clothes through a website, mainly for women who have trouble finding suitable clothes in main street shops because of their height or weight.","cn":"W：嗯，我通过一个网站销售特色服装，主要面向那些因为身高或体重而难以在商业街服装店找到合适衣服的女性。"},{"sp":"Q5","en":"But I do some men's clothes too.","cn":"不过，我也做一些男装。"},{"sp":"Q5","en":"M: How did you get started in this business at such a young age?","cn":"M：你这么年轻，是怎么开始做这门生意的？"},{"sp":"Q5","en":"Are you studying fashion design?","cn":"你在学习服装设计吗？"},{"sp":"Q5","en":"W: Actually, I'm majoring in finance, but I've always loved clothes.","cn":"W：其实，我的专业是金融，但我一直很喜欢服装。"},{"sp":"Q5","en":"And I started making my own at 14.","cn":"而且我从14岁起就开始自己做衣服了。"},{"sp":"Q5","en":"M: Did you have any sort of training in design or sewing?","cn":"M：你接受过设计或缝纫方面的培训吗？"},{"sp":"Q5","en":"Or was it a natural ability?","cn":"还是说这是你的天赋？"},{"sp":"Q5","en":"W: I'd have to say no to both.","cn":"W：这两方面都不是。"},{"sp":"Q5","en":"No one taught me to make clothes and most of the things I made at first were disasters.","cn":"没人教过我做衣服，而且我刚开始做的大多数衣服都糟糕透了。"},{"sp":"Q5","en":"M: Why did you persevere?","cn":"M：你为什么坚持下来了？"},{"sp":"Q5","en":"I think most people would give up if they kept failing, especially at that age.","cn":"我想大多数人如果一直失败，都会放弃，尤其是在那个年纪。"},{"sp":"Q5","en":"W: I kept on out of necessity.","cn":"W：我是出于需要才坚持下来的。"},{"sp":"Q5","en":"As you can see, I'm very tall and I couldn't find clothes that fit me in ordinary shops.","cn":"你也看得出来，我个子很高，在普通商店里找不到合身的衣服。"},{"sp":"Q5","en":"So I kept trying and developed my skills over time.","cn":"所以我不断尝试，随着时间的推移逐渐提高了自己的技能。"},{"sp":"Q5","en":"M: Well, my notes say you earned $50,000 in profits last year, an extraordinary amount for a 20-year-old student.","cn":"M：嗯，我的资料上说，你去年赚了5万美元的利润。对于一名20岁的学生来说，这是一笔惊人的数目。"},{"sp":"Q5","en":"How did that happen?","cn":"这是怎么做到的？"},{"sp":"Q5","en":"Did you see a gap in the market and decide to fill it?","cn":"你发现了市场空缺，然后决定填补它吗？"},{"sp":"Q5","en":"W: No. When I started university, some classmates complimented my clothes.","cn":"W：不是。我上大学时，一些同学夸我的衣服好看。"},{"sp":"Q5","en":"And when I said I made them myself, other tall women started asking if I would make theirs.","cn":"当我说衣服是我自己做的之后，其他高个子女性开始问我能不能帮她们做衣服。"},{"sp":"Q5","en":"And I did.","cn":"我答应了。"},{"sp":"Q5","en":"And before I knew it, I was an entrepreneur.","cn":"没过多久，我就成了一名企业家。"},{"sp":"Q5","en":"M: So what are your plans for the future?","cn":"M：那么，你对未来有什么计划？"},{"sp":"Q5","en":"Do you intend to open a physical store?","cn":"你打算开一家实体店吗？"},{"sp":"Q5","en":"W: No. I'll keep things online to keep costs down.","cn":"W：不打算。我会继续在线经营，以降低成本。"},{"sp":"Q5","en":"But I will add more clothes for children, both girls and boys, and possibly even for infants.","cn":"不过，我会增加更多儿童服装，包括女孩和男孩的服装，甚至可能还会做婴儿服装。"},{"sp":"Q5","en":"And I hope to add to my range of designs for men.","cn":"我也希望增加男装的设计种类。"},{"sp":"Q9","en":"Researchers have identified a potent new antibiotic compound using artificial intelligence.","cn":"研究人员利用人工智能发现了一种强效的新型抗生素化合物。"},{"sp":"Q9","en":"The antibiotic can kill very dangerous bacteria.","cn":"这种抗生素能够杀死极其危险的细菌。"},{"sp":"Q9","en":"According to a study published in the journal Cell, the compound successfully removed deadly strains of bacteria in mice which are resistant to all known antibiotics.","cn":"根据发表在《细胞》杂志上的一项研究，该化合物成功清除了小鼠体内对所有已知抗生素都具有耐药性的致命细菌菌株。"},{"sp":"Q9","en":"The researchers say this is the first time that artificial intelligence has been used to find a powerful new antibiotic molecule.","cn":"研究人员表示，这是人工智能首次被用于寻找一种强效的新型抗生素分子。"},{"sp":"Q9","en":"Why does this matter?","cn":"这为什么很重要？"},{"sp":"Q9","en":"The answer is antibiotic resistance.","cn":"答案是抗生素耐药性。"},{"sp":"Q9","en":"This happens when bacteria develop the ability to survive the medications designed to kill them.","cn":"当细菌产生在为杀死它们而设计的药物作用下存活的能力时，就会出现这种情况。"},{"sp":"Q9","en":"Antibiotic resistance is a serious threat to health and the problem is growing.","cn":"抗生素耐药性对健康构成严重威胁，而且这一问题正在加剧。"},{"sp":"Q9","en":"This makes finding new antibiotics very important.","cn":"因此，寻找新的抗生素至关重要。"},{"sp":"Q9","en":"However, in recent decades, very few have been developed, and those that have tend to be very similar to drugs already available.","cn":"然而，近几十年来，开发出的新抗生素寥寥无几，而且那些已经开发出的通常与现有药物非常相似。"},{"sp":"Q9","en":"The searches also tend to only focus on a narrow spectrum of chemical compounds, but this is where artificial intelligence comes in.","cn":"这些搜索也往往只关注范围狭窄的化合物，但这正是人工智能发挥作用的地方。"},{"sp":"Q9","en":"Why?","cn":"为什么？"},{"sp":"Q9","en":"To find new drugs, scientists screen molecules to predict how effective they might be.","cn":"为了寻找新药，科学家会筛选分子，预测它们可能具有多大疗效。"},{"sp":"Q9","en":"Typically, such screening is done by humans in the lab, which is both costly and slow.","cn":"通常，这种筛选由实验室中的人类完成，既成本高昂又耗时缓慢。"},{"sp":"Q9","en":"Artificial intelligence is different.","cn":"人工智能则不同。"},{"sp":"Q9","en":"It's fast, and it can process a high volume.","cn":"它速度快，而且能够处理海量数据。"},{"sp":"Q9","en":"It can screen hundreds of millions of compounds to identify a few interesting candidates that require experimental testing.","cn":"它可以筛选数亿种化合物，找出少数值得关注、需要进行实验测试的候选物。"},{"sp":"Q9","en":"Artificial intelligence is also able to predict if compounds are likely to be toxic.","cn":"人工智能还能够预测化合物是否可能具有毒性。"},{"sp":"Q9","en":"Some experts assert that this work signifies a paradigm shift in antibiotic discovery.","cn":"一些专家认为，这项工作标志着抗生素发现领域的范式转变。"},{"sp":"Q9","en":"It could change drug discovery more generally.","cn":"它也可能从总体上改变药物研发。"},{"sp":"Q12","en":"A recent study overturned what we think we know about lying.","cn":"一项最新研究推翻了我们对说谎的固有认识。"},{"sp":"Q12","en":"Most of us have a theory about how to tell if someone is telling a lie.","cn":"我们大多数人都有一套判断某人是否在说谎的理论。"},{"sp":"Q12","en":"We may develop that theory from observations of those people we know well and see regularly, but we tend to generalize what we gather from that unscientific daily research and make it a universal theory.","cn":"这套理论可能源于我们对熟悉且经常见面的人的观察，但我们往往会把从这种不科学的日常观察中得出的结论加以概括，并将其视为普遍适用的理论。"},{"sp":"Q12","en":"So we might imagine that liars have evasive eyes, or the opposite—they simply stare at you.","cn":"因此，我们可能会认为说谎者目光闪躲，或者恰恰相反，他们只是盯着你看。"},{"sp":"Q12","en":"Or perhaps it is more generally nervous behavior we associate with lies.","cn":"又或者，我们通常会把某种更普遍的紧张行为与谎言联系起来。"},{"sp":"Q12","en":"Whatever the particular theory, it's usually based on close observation of people we know.","cn":"无论具体是哪一种理论，它通常都建立在对我们熟悉的人的细致观察之上。"},{"sp":"Q12","en":"And we get lots of practice.","cn":"而且，我们有大量的实践机会。"},{"sp":"Q12","en":"On average, we're lied to some 200 times per day.","cn":"平均而言，我们每天大约会被欺骗200次。"},{"sp":"Q12","en":"These are mostly harmless lies, but lies nonetheless.","cn":"这些大多是无害的谎言，但归根结底仍然是谎言。"},{"sp":"Q12","en":"But there's a problem with our theories, even though they're based on all these observations.","cn":"然而，尽管我们的理论建立在所有这些观察之上，它们仍然存在一个问题。"},{"sp":"Q12","en":"The average person—you and me—tested rigorously on how well we detect lies fails to do better than chance.","cn":"普通人，也就是你我，在接受严格测试以评估识别谎言的能力时，表现并不比凭猜测好。"},{"sp":"Q12","en":"That's well established over many studies and lots of attempts by researchers to work out reliable ways to detect lies.","cn":"这一点已经被众多研究以及研究人员为找出可靠的测谎方法所进行的大量尝试充分证实。"},{"sp":"Q12","en":"It's even relatively easy to fool lie detectors, the gold standard of lie detection, by training yourself in breathing techniques and symptom suppression.","cn":"即使是测谎的金标准测谎仪，也相对容易被欺骗，只要通过训练掌握呼吸技巧并抑制相关生理反应即可。"},{"sp":"Q12","en":"Is there any way to get better at detecting lies?","cn":"有没有办法提高识别谎言的能力？这项新研究给出了令人意外的建议：不要再看，而是改为倾听。"},{"sp":"Q12","en":"The new research offers some surprising advice.","cn":"事实证明，如果我们看不到对方的脸，而是专注于相关人士的声音，我们的准确率会显著提高。"},{"sp":"Q12","en":"Stop looking and listen instead.","cn":""},{"sp":"Q12","en":"It turns out that if we're unable to see the face, but rather focus on the voice of the person in question, our accuracy rate improves considerably.","cn":""},{"sp":"Q16","en":"Appear to be submissive, humble, grateful and undemanding; show great pleasure when a doctor comes into your room, even if the visit is brief and useless.","cn":"表现得顺从、谦卑、感恩而且毫无要求；即使医生来你的病房只是短暂逗留且毫无用处，也要表现出极大的喜悦。"},{"sp":"Q16","en":"Don't challenge anyone with authority unless you are famous or very rich.","cn":"除非你名声显赫或非常富有，否则不要挑战任何有权威的人。"},{"sp":"Q16","en":"Those are a few strategies for dealing with today's American medical establishment.","cn":"这些是应对当今美国医疗机构的几种策略。"},{"sp":"Q16","en":"What patients want is to be treated with respect and consideration.","cn":"患者想要的是受到尊重和体贴的对待。"},{"sp":"Q16","en":"But in my experience, too few hospitals and doctors are ready to do that.","cn":"但依我的经验，愿意这样做的医院和医生太少了。"},{"sp":"Q16","en":"In his book, A Whole New Life, novelist Reynolds Price recalls that his doctors chose a crowded hallway as the place to tell him he might have a tumor on his spinal cord.","cn":"小说家雷诺兹·普莱斯在其著作《全新的生活》中回忆说，他的医生选择了一条拥挤的走廊作为告诉他脊髓上可能长有肿瘤的地点。"},{"sp":"Q16","en":"It did not occur to the two physicians that a hallway was not the most appropriate place for that particular piece of news.","cn":"两位医生都没有想到，走廊并不是传达这一特殊消息最恰当的地方。"},{"sp":"Q16","en":"My surgeon, who is in his mid-thirties, looks tired.","cn":"我的外科医生三十多岁，看起来很疲惫。"},{"sp":"Q16","en":"He has been overwhelmed with patients who have fallen on the winter ice.","cn":"他一直被那些在冬季结冰路面上摔倒的患者弄得应接不暇。"},{"sp":"Q16","en":"He is a witty man, but sometimes his wit is unwelcome.","cn":"他是个风趣的人，但有时他的幽默并不受欢迎。"},{"sp":"Q16","en":"\"The health insurance company Blue Cross wants me to put you out in the snow tomorrow afternoon,\" he tells me after I have been in the hospital for more than a week.","cn":"“医疗保险公司蓝十字希望我明天下午把你赶到雪地里去，”我住院一个多星期后，他对我说。"},{"sp":"Q16","en":"I'm terrified because I have no idea where to go.","cn":"我吓坏了，因为我完全不知道该去哪里。"},{"sp":"Q16","en":"I cannot walk or even lift my leg a few inches.","cn":"我无法行走，甚至连腿抬高几英寸都做不到。"},{"sp":"Q16","en":"The hospital social worker strikes me as an idiot.","cn":"医院的社会工作者让我觉得她是个笨蛋。"},{"sp":"Q16","en":"But my complaints about her only annoy my surgeon.","cn":"但我对她的抱怨只让我的外科医生感到恼火。"},{"sp":"Q16","en":"\"I have to work with these people,\" he tells my friend, Dr. Karen Brudney, when she mercifully intervenes on my behalf and arranges for me to be transferred to another hospital.","cn":"“我还得和这些人共事，”当我的朋友凯伦·布鲁德尼医生出面替我求情，并安排把我转到另一家医院时，他对她说道。"},{"sp":"Q16","en":"\"If you say one negative thing, they get defensive,\" she tells me later.","cn":"“只要你说一句负面的话，他们就会采取防御姿态，”她后来对我说。“他们有一种机构忠诚感。"},{"sp":"Q16","en":"\"They have this kind of institutional loyalty.","cn":"一定要带一位代言人，也就是说，带另一个人和你一起去医院，并把每一个问题及其答案、每一位医生和护士的姓名全都记下来。"},{"sp":"Q16","en":"Always bring an advocate, that is, any other person with you to the hospital, and write down every single question and the answer, the name of every doctor and nurse.","cn":"当人们知道你记住了他们的名字时，他们的表现会好一些。"},{"sp":"Q16","en":"When people know you have their names, they behave better.","cn":"而且，”布鲁德尼补充道，“如果作为患者，你表示希望对哪怕一部分情况进行掌控，或者希望被征求意见、被告知情况，那么你就会被视为难相处的人。"},{"sp":"Q16","en":"And,\" Brudney adds, \"if you, as a patient, suggest that you might like to control even part of the situation or be consulted or informed, then you are considered difficult.","cn":"他们希望你完全被动。"},{"sp":"Q16","en":"They want you to be totally passive.","cn":"整个医疗保健体系，尤其是医院和养老院的存在，都是出于与照料患者毫无关系的原因。"},{"sp":"Q16","en":"The entire health care system, particularly hospitals and nursing homes, exists for reasons that have nothing to do with taking care of patients.","cn":"患者只是附带的存在。"},{"sp":"Q16","en":"Patients are incidental.\"","cn":"”"},{"sp":"Q19","en":"There are probably teams you've worked with but you never want to work with again.","cn":"你可能曾与一些团队共事过，但再也不想与他们合作。"},{"sp":"Q19","en":"But there must have also been other teams that you would prize reuniting with professionally.","cn":"然而，肯定也有一些其他团队，是你非常珍视能在职业上与之重聚的。"},{"sp":"Q19","en":"In other words, your team had vitality.","cn":"换句话说，你的团队具有活力。"},{"sp":"Q19","en":"Vitality comes about when the ties people form with their fellow team members are such that they stay connected even after the team breaks up.","cn":"当人们与团队同事建立的联系使他们即使在团队解散后仍保持联系时，团队就会产生这种活力。"},{"sp":"Q19","en":"What characteristics of a team make its members more likely to stay in contact despite no longer working together?","cn":"团队具有什么样的特征，才能使其成员即使不再一起工作，也更有可能保持联系？"},{"sp":"Q19","en":"This question has been answered recently in a study published in a business journal.","cn":"最近，一项发表于商业期刊的研究回答了这个问题。"},{"sp":"Q19","en":"One of the two key factors the research team discovered is sameness.","cn":"研究团队发现的两个关键因素之一是相似性，具体来说，就是拥有相同的性别或族裔背景。"},{"sp":"Q19","en":"Specifically, sharing the same gender or ethnic origin.","cn":"一个团队成员的人口统计特征越相似，他们就越倾向于在团队完成使命很久之后仍保持同事关系。"},{"sp":"Q19","en":"The more members of a team share similar demographics, the more inclined they will be to remain associates long after the team has served its purpose.","cn":"联系建立之后，相似性会进一步巩固这种联系。"},{"sp":"Q19","en":"After ties are established, similarity strengthens them.","cn":"因此，他们会更加信任并相互理解这些人，这促使他们寻求进一步合作的机会。"},{"sp":"Q19","en":"As a result, they regard these individuals with greater trust and mutual understanding, which motivates them to seek further opportunities for collaboration.","cn":"实际上，人们往往会与相似的人建立更牢固、更持久的联系。"},{"sp":"Q19","en":"In effect, people tend to create stronger and longer-lasting connections with similar others.","cn":"与我们外貌和声音不同的人，或许拥有帮助我们取得更大成功所需的资源。"},{"sp":"Q19","en":"Someone who looks and sounds different from us may have the resources we need to be more successful.","cn":"然而，仅仅因为他们与众不同，我们就会发现自己明显不那么信任他们。"},{"sp":"Q19","en":"Yet, we find them to be significantly less credible simply because they are different.","cn":"如果你是职场多元化的坚定倡导者，毫无疑问会对这样的发现感到震惊。"},{"sp":"Q19","en":"If you are a fierce advocate of workplace diversity, you'll no doubt be horrified by such a revelation.","cn":""},{"sp":"Q19","en":"The second factor identified by the researchers is the quality of the relationships among the team members.","cn":"研究人员确定的第二个因素是团队成员之间关系的质量。他们彼此越信任，目标越一致，并且越依赖彼此来实现这些目标，即使不再作为一个团队工作，他们维持彼此联系的可能性就越大。"},{"sp":"Q19","en":"The more they trust one another, share the same goals and depend on each other for the achievement of those goals, the stronger their chances of maintaining their connections, despite no longer working as one team.","cn":"关系良好的团队拥有一种共同信念，即彼此合作承担风险是安全的；"},{"sp":"Q19","en":"Teams with quality relationships have a shared belief that it's safe to take risks with each other, and their members are obliged to share the workload and help out.","cn":"其成员也有义务分担工作量并互相提供帮助。"},{"sp":"Q19","en":"From personal experience, I can see both the truth and the inconsistency of such studies.","cn":"根据个人经历，我既能看出这类研究的真实性，也能看出其中的不一致之处。"},{"sp":"Q19","en":"The truth is some of my closest friendships were formed as a result of having worked together on teams, and I actively seek opportunities to work with them again.","cn":"真实之处在于，我最亲密的一些友谊源于我们曾一起在团队中工作，而我也会主动寻找再次与他们合作的机会。"},{"sp":"Q19","en":"The inconsistency, though, is that I've never worked for a team more successful and cohesive than the one of which I am a member right now.","cn":"然而，不一致之处在于，我从未在一个比我目前所在团队更加成功、更加团结的团队中工作过。"},{"sp":"Q19","en":"And yet, the four of us have very little in common and are completely different demographically.","cn":"可是，我们四个人几乎没有共同之处，在人口统计特征上也完全不同。"},{"sp":"Q19","en":"So I am unlikely to question the value of a diverse workforce.","cn":"因此，我不太可能质疑多元化劳动力的价值。"},{"sp":"Q22","en":"An American researcher who studied 600 millionaires found how rich you can get comes down to six wealth factors.","cn":"一位研究了6亿名百万富翁的美国研究人员发现，一个人能够变得多么富有，归根结底取决于六个财富因素。"},{"sp":"Q22","en":"She found that six behaviors are related to net worth potential, regardless of age or income.","cn":"她发现，无论年龄或收入如何，六种行为都与净资产潜力有关。"},{"sp":"Q22","en":"These were thriftiness, confidence, responsibility, planning, focus and social indifference.","cn":"这些行为分别是节俭、自信、责任感、规划、专注以及不在意社会评价。"},{"sp":"Q22","en":"Being thrifty comes as no great surprise.","cn":"节俭并不令人感到意外。入不敷出地消费、不为退休储蓄而消费、预想着自己会变得富有而消费，都会使你沦为薪水的奴隶。"},{"sp":"Q22","en":"Spending above your means, spending instead of saving for retirement, spending in anticipation of becoming wealthy, makes you a slave to the paycheck.","cn":"她写道：“即使收入达到天文数字，要想合理地积累财富，专家也建议将收入的20%存起来，靠剩下的80%生活。"},{"sp":"Q22","en":"\"Even with an astronomical level of income,\" she wrote, \"to properly build wealth, experts recommend saving 20% of your income and living off the remaining 80%.\"","cn":"”"},{"sp":"Q22","en":"Having confidence is another key characteristic, as it helps people to be thrifty.","cn":"拥有自信是另一个关键特征，因为这能帮助人们保持节俭。量入为出需要自信。"},{"sp":"Q22","en":"It takes confidence to live within your means.","cn":"正确地进行投资同样需要自信。"},{"sp":"Q22","en":"It also takes confidence to invest properly.","cn":"财务规划师建议，不要凭情绪做出投资决定，而应放任投资自行运作，并专注于长期投资计划。"},{"sp":"Q22","en":"Instead of making investing decisions with your emotions, financial planners advise that you should leave your investments alone and focus on a long-term investment plan.","cn":"但如果不对结果承担责任，人们就无法投资或管理自己的资金。"},{"sp":"Q22","en":"But people can't invest or manage their own money without accepting responsibility for the outcomes.","cn":"许多百万富翁都承担个人责任，而且大多数人还碰巧是白手起家，这意味着他们并非靠运气获得财富。"},{"sp":"Q22","en":"Many millionaires take on personal responsibility, and most also happen to be self-made, meaning they didn't acquire their wealth through luck.","cn":"百万富翁不会指望别人让自己变得富有，如果没有达到目标，他们也不会责怪别人。"},{"sp":"Q22","en":"Millionaires don't count on anyone else to make them rich, and they don't blame anyone else if they fall short.","cn":"他们专注于自己能够控制的事情，并使日常习惯与自己设定的目标保持一致。"},{"sp":"Q22","en":"They focus on things they can control and align their daily habits to the goals they have set for themselves.","cn":"他们往往以目标为导向且勤奋努力，这使他们能够进行财务规划，并专注于贯彻落实这些计划。"},{"sp":"Q22","en":"They tend to be goal-oriented and hard workers, which enables them to plan financially and focus on seeing those plans through. 92% of the millionaires surveyed developed a long term plan for their money and 97% almost always achieved the goals they set for themselves.","cn":"接受调查的百万富翁中，有92%为自己的资金制定了长期计划，97%几乎总能实现自己设定的目标。"},{"sp":"Q22","en":"And it is these behaviors that make it easy for them to be socially indifferent.","cn":"正是这些行为，使他们很容易做到不在意社会评价。"},{"sp":"Q22","en":"They resist lifestyle creep, the tendency to spend more whenever one earns more.","cn":"他们抵制生活方式膨胀，也就是一个人收入增加后便倾向于增加消费。"},{"sp":"Q22","en":"Essentially, they don't yield to pressure to buy the latest thing or to keep up with others or what they have acquired.","cn":"他们基本不会屈服于购买最新产品的压力，也不会为了与他人保持一致或追赶他人已经拥有的东西而消费。"},{"sp":"Q22","en":"Instead of being focused on what might make them happy today, they're focused on their long-term wealth-building plan.","cn":"他们关注的不是今天可能让自己感到快乐的事物，而是长期积累财富的计划。"}],"questions":[{"q":"What do nearly sixty percent of the firms allow?","options":["Working from home at least two days a week","A four day working week","Unlimited holidays","Free commuting buses"],"answer":0,"explain":"原文说 allow employees to work from home at least two days a week。"},{"q":"What problem did managers report?","options":["Fewer online meetings","More time spent in online meetings","A fall in productivity","A loss of office space"],"answer":1,"explain":"原文说 managers reported a rise in the time spent in online meetings。"},{"q":"What does the report suggest about teams?","options":["They should never meet in person","They should come to the office on the same days","They should work only from home","They should hire more junior staff"],"answer":1,"explain":"最后一句说 teams come to the office on the same days rather than on days of their own choosing。"}],"cloze":[{"text":"Remote work has become a ______ part of office life.","answers":["permanent"],"hint":"永久的"},{"text":"Staff save an average of forty minutes a day on ______.","answers":["commuting"],"hint":"通勤"},{"text":"Several companies have responded by setting ______ hours, during which no internal meetings may be scheduled.","answers":["quiet"],"hint":"安静的"}]},{"id":"cet4-2022-09-1","level":"CET4","exam":"2022_09_1","year":2022,"month":9,"set":1,"type":"整卷听力","title":"2022年9月 四级第1套 · 听力真题","source":"2022年9月 CET-4 第1套 · 听力（本地原音 + 逐句原文）","audio":"assets/audio/2022/cet4-2022-09-set1.mp3","intro":"听力原文按录音篇目逐句拆分，中文译文仅供参考；音频为本地真题原音，整卷原音无法定位单句，逐句请用下方播放器。","questions":[],"lines":[{"sp":"短篇新闻 1","en":"White meat, such as chicken, may raise blood cholesterol levels as much as red meat does.","cn":"白肉，如鸡肉，可能会像红肉一样升高血液胆固醇水平。"},{"sp":"短篇新闻 1","en":"This finding surprised researchers, who admitted they didn't expect that eating white meat would lead to higher blood cholesterol levels.","cn":"这一发现令研究人员感到意外，他们承认没有预料到食用白肉会导致血液胆固醇水平升高。"},{"sp":"短篇新闻 1","en":"In the study, researchers looked at 113 healthy people.","cn":"在这项研究中,研究人员观察了113名健康人。"},{"sp":"短篇新闻 1","en":"The participants ate three different diets.","cn":"参与者食用了三种不同的饮食。"},{"sp":"短篇新闻 1","en":"These were a red meat diet which is primarily beef, a white meat diet which is mostly chicken and turkey, and a vegetarian protein diet.","cn":"这些饮食分别是主要以牛肉为主的红肉饮食、主要以鸡肉和火鸡肉为主的白肉饮食，以及素食蛋白饮食。"},{"sp":"短篇新闻 1","en":"Each diet period was four weeks.","cn":"每个饮食周期为四周。"},{"sp":"短篇新闻 1","en":"Between the diet periods, participants had a break, during which they ate their regular foods.","cn":"在饮食周期之间，参与者有一个休息期，期间他们食用常规食物。"},{"sp":"短篇新闻 1","en":"In addition, participants had blood tests at the start and finish of each new diet.","cn":"此外，参与者在每个新饮食开始和结束时都进行了血液检测。"},{"sp":"短篇新闻 1","en":"The results showed that white and red meat diets had the same effects on blood cholesterol levels.","cn":"结果显示，白肉和红肉饮食对血液胆固醇水平有相同的影响。"},{"sp":"短篇新闻 1","en":"Further, both diets increased blood cholesterol levels compared with the diet built on vegetarian protein sources.","cn":"此外，与基于素食蛋白来源的饮食相比，这两种饮食都增加了血液胆固醇水平。"},{"sp":"短篇新闻 1","en":"The team acknowledged that it is possible that white meat is better for our health than red meat despite their findings.","cn":"该团队承认，尽管有他们的研究结果，白肉对我们的健康可能比红肉更好。"},{"sp":"短篇新闻 1","en":"This is because other effects of red meat consumption could contribute to heart disease independent of cholesterol.","cn":"这是因为食用红肉的其他影响可能会独立于胆固醇而导致心脏病。"},{"sp":"短篇新闻 1","en":"Their main recommendations are that people eat less of both kinds of meat and more vegetarian protein.","cn":"他们的主要建议是人们减少食用这两种肉类，多摄入素食蛋白。"},{"sp":"短篇新闻 2","en":"At around half past nine this morning, a trailer attached to a lorry turned over at the crossing of High Street in Milton.","cn":"今天上午九点半左右,一辆卡车拖挂的拖车在Milton的High Street十字路口发生侧翻。"},{"sp":"短篇新闻 2","en":"Hundreds of frozen turkeys were spilled all over the road.","cn":"数百只冷冻火鸡散落在路面上。"},{"sp":"短篇新闻 2","en":"It is reported that nobody was hurt in the incident, but police said it may affect traffic and Christmas dinners.","cn":"据报道,此次事故中无人受伤,但警方表示这可能会影响交通和圣诞晚餐。"},{"sp":"短篇新闻 2","en":"With just one week to go before Christmas, there are worries that local supermarket supplies of this holiday favorite may be affected.","cn":"距离圣诞节仅剩一周时间,人们担心当地超市这一节日热门食品的供应可能会受到影响。"},{"sp":"短篇新闻 2","en":"A police spokeswoman said that officers were currently in attendance at the scene.","cn":"一名警方女发言人表示,警员目前正在现场处置。"},{"sp":"短篇新闻 2","en":"She stated that the driver of the lorry had been arrested on suspicion of dangerous driving.","cn":"她说,卡车司机已因涉嫌危险驾驶被逮捕。"},{"sp":"短篇新闻 2","en":"The crossing on High Street is a well-known accident blackspot.","cn":"High Street的这个十字路口是一个众所周知的交通事故多发点。"},{"sp":"短篇新闻 2","en":"This year alone, there have been seven traffic accidents at this location.","cn":"仅今年一年,该路口就发生了七起交通事故。"},{"sp":"短篇新闻 2","en":"Thankfully, none of these accidents have resulted in serious injury.","cn":"幸运的是,这些事故均未造成重伤。"},{"sp":"短篇新闻 3","en":"India launched its helicopter taxi service on Monday, promising to ferry customers the 40 miles between Bangalore's Electronic City tech hub and the International Airport terminal in 15 minutes.","cn":"印度于周一推出了直升机出租车服务,承诺在15分钟内将客户从班加罗尔的Electronic City科技中心送至国际机场航站楼,全程40英里。"},{"sp":"短篇新闻 3","en":"Customers can book their helicopter ride through a mobile app.","cn":"客户可以通过移动应用程序预订直升机行程。"},{"sp":"短篇新闻 3","en":"The service, which claims to be the first of its kind in India, offers only one route, but Bangalore airport will add more once it gets approval.","cn":"该服务自称是印度首创,目前仅提供一条航线,但班加罗尔机场表示一旦获得批准将增加更多航线。"},{"sp":"短篇新闻 3","en":"Helicopter taxi is not an affordable option for many travelers. A car ride for the same journey costs less than half as much. But Bangalore airport says it is a competitive alternative to a car ride for tech executives in a hurry. \"A large number of high-class travelers, including CEOs, have to spend more than three hours by road to get there and that is a loss of time,\" a Bangalore airport spokesperson said. \"This is not a low cost option, but it is an option,\" she added.","cn":"直升机出租车对许多旅客来说并非经济实惠的选择。同样行程的汽车费用还不到一半。但班加罗尔机场表示,对于赶时间的科技公司高管来说,这是汽车出行的有竞争力的替代方案。班加罗尔机场发言人说:\"包括CEO在内的大量高端旅客不得不花费三个多小时的车程才能到达那里,这是时间的损失。\"她补充道:\"这不是低成本选择,但它是一个选择。\""},{"sp":"短篇新闻 3","en":"The helicopters ferried around eight customers to the airport on their first day. The company that owns and operates the service is called Thumby Aviation. It previously specialized in private charter flights for government officials.","cn":"直升机在首日将约八名客户送往机场。拥有并运营该服务的公司名为Thumby Aviation,此前专门为政府官员提供私人包机服务。"},{"sp":"长对话 1","en":"W: Hi, I wish to buy some cheese for a barbecue this weekend.","cn":"W: 你好,我想买些奶酪,这周末烧烤用。"},{"sp":"长对话 1","en":"M: What kind would you like?","cn":"M: 您想要什么种类的?"},{"sp":"长对话 1","en":"W: Sorry, I don't know much about cheese.","cn":"W: 不好意思,我对奶酪不太了解。"},{"sp":"长对话 1","en":"What type do you think would be suitable for a barbecue?","cn":"您觉得哪种适合烧烤呢?"},{"sp":"长对话 1","en":"M: That's easy! For a barbecue, you could have any cheese you want. I imagine there will be different foods and people will just help themselves and eat at their own pace, right?","cn":"M: 这简单!烧烤的话,您想要什么奶酪都行。我想应该会有各种不同的食物,大家自己取用,按自己的节奏吃,对吧?"},{"sp":"长对话 1","en":"W: Yes, exactly.","cn":"W: 对,没错。"},{"sp":"长对话 1","en":"It will be very casual.","cn":"会很随意的。"},{"sp":"长对话 1","en":"We will just be a small group of friends gathering together at Washington Park.","cn":"就是一小群朋友在Washington Park聚一聚。"},{"sp":"长对话 1","en":"There will be around 20 of us, including children.","cn":"大概20个人左右,包括孩子。"},{"sp":"长对话 1","en":"M: Great! So you could have different types of cheese. How much would you like to spend?","cn":"M: 太好了!那您可以买几种不同类型的奶酪。您打算花多少钱?"},{"sp":"长对话 1","en":"W: Not very much.","cn":"W: 不想花太多。"},{"sp":"长对话 1","en":"Let's say $30.","cn":"就算30美元吧。"},{"sp":"长对话 1","en":"M: I would suggest having at least one soft cheese and one hard cheese.","cn":"M: 我建议至少买一种软奶酪和一种硬奶酪。"},{"sp":"长对话 1","en":"That will offer you a good variety to suit different people's tastes.","cn":"这样品种丰富,能满足不同人的口味。"},{"sp":"长对话 1","en":"W: That sounds good.","cn":"W: 听起来不错。"},{"sp":"长对话 1","en":"What's the difference between a soft cheese and a hard cheese?","cn":"软奶酪和硬奶酪有什么区别呢?"},{"sp":"长对话 1","en":"M: Well, it depends.","cn":"M: 嗯,这要看情况。"},{"sp":"长对话 1","en":"But generally speaking, soft cheeses are creamy and go well with sweet things like honey and jam.","cn":"但一般来说,软奶酪是奶油状的,跟蜂蜜、果酱这些甜食很配。"},{"sp":"长对话 1","en":"I would suggest something like this Spanish goat cheese.","cn":"我建议买这种西班牙山羊奶酪。"},{"sp":"长对话 1","en":"It's only $15, a very good price.","cn":"只要15美元,价格很实惠。"},{"sp":"长对话 1","en":"You can spread it on bread with a knife, and then add a tiny bit of honey on top.","cn":"您可以用刀把它抹在面包上,然后在上面加一点点蜂蜜。"},{"sp":"长对话 1","en":"It's delicious.","cn":"非常好吃。"},{"sp":"长对话 1","en":"Children love it.","cn":"孩子们都爱吃。"},{"sp":"长对话 1","en":"W: Okay, great.","cn":"W: 好的,很棒。"},{"sp":"长对话 1","en":"What about a hard cheese?","cn":"那硬奶酪呢?"},{"sp":"长对话 1","en":"M: Yes, for hard cheese, I would recommend this Italian one here.","cn":"M: 对,硬奶酪的话,我推荐这款意大利的。"},{"sp":"长对话 1","en":"It has a very strong smell and a dry flavor.","cn":"它味道很浓,口感偏干。"},{"sp":"长对话 1","en":"You can cut it into thin slices and eat it on its own.","cn":"您可以把它切成薄片直接吃。"},{"sp":"长对话 1","en":"It's $16.","cn":"16美元。"},{"sp":"长对话 1","en":"W: Okay, I'll take both.","cn":"W: 好的,两种我都要了。"},{"sp":"长对话 1","en":"Thank you for your help.","cn":"谢谢您的帮助。"},{"sp":"长对话 2","en":"M: Our school is replacing printed textbooks with e-textbooks next semester.","cn":"M: 我们学校下学期要用电子教材取代纸质教材了。"},{"sp":"长对话 2","en":"I can't wait.","cn":"我等不及了。"},{"sp":"长对话 2","en":"W: Really? What about the cost, not only buying all those tablets, but the software and electronic infrastructure that goes with it, not to mention retraining all the teachers and administration staff?","cn":"W: 真的吗?那成本呢,不仅要购买所有那些平板电脑,还有配套的软件和电子基础设施,更不用说还要重新培训所有的教师和行政人员?"},{"sp":"长对话 2","en":"M: Sure, the initial expenditure will be high, but much lower afterwards.","cn":"M: 当然,初期支出会很高,但之后就低多了。"},{"sp":"长对话 2","en":"Besides that, tablet prices continue to drop and are becoming increasingly affordable.","cn":"而且,平板电脑价格持续下降,越来越实惠了。"},{"sp":"长对话 2","en":"Anyway, tablets help students learn up to 80% faster.","cn":"不管怎样,平板电脑能帮助学生的学习速度提高80%。"},{"sp":"长对话 2","en":"W: Not necessarily.","cn":"W: 不一定。"},{"sp":"长对话 2","en":"Tablets have too many distractions.","cn":"平板电脑有太多干扰因素。"},{"sp":"长对话 2","en":"Students may pay attention to apps, games and websites instead of their teachers.","cn":"学生可能会把注意力放在应用程序、游戏和网站上,而不是听老师讲课。"},{"sp":"长对话 2","en":"In fact, research suggests that people who read printed text comprehend more, remember more and learn 30% more than those who read digital text.","cn":"事实上,研究表明,阅读纸质文本的人比阅读电子文本的人理解得更多,记住得更多,学到的东西多30%。"},{"sp":"长对话 2","en":"M: Yes.","cn":"M: 是的。"},{"sp":"长对话 2","en":"But tablets contain many technological features that are not found in printed textbooks.","cn":"但平板电脑包含许多纸质教材没有的技术功能。"},{"sp":"长对话 2","en":"Think about it.","cn":"想想看。"},{"sp":"长对话 2","en":"Students are able to highlight and edit text, write notes and search for information much more quickly than they can with printed textbooks.","cn":"学生能够高亮和编辑文本,写笔记,搜索信息,这些都比用纸质教材快得多。"},{"sp":"长对话 2","en":"And what about all those trees that are cut down to make printed books?","cn":"还有那些为了制作纸质书而被砍伐的树木呢?"},{"sp":"长对话 2","en":"W: Actually, manufacturing tablets is environmentally destructive and dangerous to human health.","cn":"W: 实际上,制造平板电脑对环境的破坏性很大,而且对人类健康有危害。"},{"sp":"长对话 2","en":"The health impacts from making one electronic reader are 70 times greater than those from making a single printed book.","cn":"制造一台电子阅读器对健康的影响是制造一本纸质书的70倍。"},{"sp":"长对话 2","en":"A lot of minerals are extracted from the earth to make electronic readers.","cn":"制造电子阅读器需要从地球上开采大量矿物。"},{"sp":"长对话 2","en":"It does far more damage to the environment.","cn":"对环境的破坏要大得多。"},{"sp":"长对话 2","en":"M: Yes.","cn":"M: 是的。"},{"sp":"长对话 2","en":"But the software for electronic readers can be updated instantly without the need for buying a whole lot of new books.","cn":"但是电子阅读器的软件可以即时更新,不需要购买一大堆新书。"},{"sp":"长对话 2","en":"That's better for the environment.","cn":"这样对环境更好。"},{"sp":"长对话 2","en":"W: But the core curriculum doesn't change that much.","cn":"W: 但核心课程变化并不大。"},{"sp":"长对话 2","en":"Printed textbooks that are not brand new, still contain the basic relevant information of core subjects.","cn":"不是全新的纸质教材仍然包含核心科目的基本相关信息。"},{"sp":"长对话 2","en":"M: Well, I'm looking forward to the change.","cn":"M: 嗯,我很期待这个改变。"},{"sp":"长对话 2","en":"W: I'll stick with my printed books.","cn":"W: 我还是坚持用我的纸质书。"},{"sp":"听力篇章 1","en":"In social psychology, the term \"person perception\" refers to the mental processes that we use to form impressions of other people.","cn":"在社会心理学中，\"人物知觉\"这一术语指的是我们用来形成对他人印象的心理过程。"},{"sp":"听力篇章 1","en":"It includes not just how we form these impressions, but the conclusions we make about other people based on our impressions.","cn":"它不仅包括我们如何形成这些印象，还包括我们基于印象对他人做出的结论。"},{"sp":"听力篇章 1","en":"Consider how often you make this kind of judgment every day.","cn":"想想你每天做出这种判断的频率有多高。"},{"sp":"听力篇章 1","en":"When you meet with a new coworker, you immediately begin to develop an initial impression of this person.","cn":"当你遇到一位新同事时，你会立即开始对这个人形成初步印象。"},{"sp":"听力篇章 1","en":"When you visit the grocery store, you might draw conclusions about the cashier who checks you out.","cn":"当你去杂货店时，你可能会对为你结账的收银员得出一些结论。"},{"sp":"听力篇章 1","en":"Obviously, person perception is a very subjective process that can be affected by a number of variables, including the characteristics of the person you are observing, the context of the situation, your own personal traits, and your past experiences.","cn":"显然，人物知觉是一个非常主观的过程，可能会受到许多变量的影响，包括你所观察的人的特征、情境的背景、你自己的个人特质以及你过去的经历。"},{"sp":"听力篇章 1","en":"One of the techniques we use in person perception is social categorization.","cn":"我们在人物知觉中使用的技巧之一是社会分类。"},{"sp":"听力篇章 1","en":"In this process, we mentally categorize people into different groups based on common characteristics.","cn":"在这个过程中，我们根据共同特征在心理上将人们归入不同的群体。"},{"sp":"听力篇章 1","en":"Problems with this technique include the fact that it can lead to errors and prejudice.","cn":"这种技巧的问题包括它可能导致错误和偏见。"},{"sp":"听力篇章 1","en":"Imagine that you are getting on a bus.","cn":"想象一下你正在上公交车。"},{"sp":"听力篇章 1","en":"There are only two seats available.","cn":"只有两个座位可用。"},{"sp":"听力篇章 1","en":"One is next to a small, elderly woman; the other is next to a muscular, fierce-looking man.","cn":"一个挨着一位身材矮小的老年妇女；另一个挨着一位肌肉发达、面容凶狠的男子。"},{"sp":"听力篇章 1","en":"You sit next to the elderly woman, who unfortunately turns out to be quite skilled at picking pockets.","cn":"你坐在老年妇女旁边，不幸的是她原来非常擅长扒窃。"},{"sp":"听力篇章 1","en":"Because of social categorization, you immediately judge the woman as harmless, and the man as threatening, leading to the loss of your wallet.","cn":"由于社会分类，你立即判断这位妇女是无害的，而那位男子是有威胁的，这导致了你钱包的丢失。"},{"sp":"听力篇章 2","en":"Despite smartphones and social media, young people today are as socially competent as those from the previous generation.","cn":"尽管有智能手机和社交媒体,今天的年轻人在社交能力方面与上一代人一样出色。"},{"sp":"听力篇章 2","en":"At least this is what a new study suggests.","cn":"至少这是一项新研究所表明的。"},{"sp":"听力篇章 2","en":"For the study, researchers compared teacher and parent evaluations of American children who started kindergarten in 1998, with those who began school in 2010.","cn":"在这项研究中,研究人员比较了教师和家长对1998年开始上幼儿园的美国儿童与2010年入学儿童的评价。"},{"sp":"听力篇章 2","en":"The former group entered kindergarten when mobile phones were luxuries.","cn":"前一组儿童入园时,移动电话还是奢侈品。"},{"sp":"听力篇章 2","en":"The latter group started school when mobile devices were widespread.","cn":"后一组儿童入学时,移动设备已经普及。"},{"sp":"听力篇章 2","en":"Results showed both groups of children were rated similarly on important social skills.","cn":"结果显示,两组儿童在重要社交技能方面的评分相似。"},{"sp":"听力篇章 2","en":"These included their ability to form and maintain friendships and get along with people who are different.","cn":"这些技能包括建立和维持友谊的能力,以及与不同的人相处的能力。"},{"sp":"听力篇章 2","en":"They were also rated similarly on self-control, such as the ability to regulate their temper.","cn":"他们在自我控制方面的评分也相似,比如控制脾气的能力。"},{"sp":"听力篇章 2","en":"In virtually every comparison made, ratings of social skills either remain constant or improved for the children born later.","cn":"在几乎所有的比较中,晚出生儿童的社交技能评分要么保持不变,要么有所提高。"},{"sp":"听力篇章 2","en":"There was one exception: Social skills were slightly lower for children who accessed online games and social networking sites many times a day.","cn":"有一个例外:每天多次访问网络游戏和社交网站的儿童,其社交技能略低。"},{"sp":"听力篇章 2","en":"Adults are worried when technological change starts to undermine traditional relationships, particularly the parent-child relationship.","cn":"当技术变革开始削弱传统关系,特别是亲子关系时,成年人会感到担忧。"},{"sp":"听力篇章 2","en":"The introduction of telephones, automobiles and radio all led to moral panic among adults of the time, because the technology allowed children to enjoy more freedom.","cn":"电话、汽车和广播的引入都曾在当时的成年人中引发道德恐慌,因为这些技术让儿童享有更多自由。"},{"sp":"听力篇章 2","en":"Fears over screen-based technology represent the most recent panic in response to technological change.","cn":"对屏幕技术的恐惧是对技术变革做出反应的最新恐慌。"},{"sp":"听力篇章 2","en":"But overall, the study found little evidence that time spent on screens was hurting social skills for most children.","cn":"但总体而言,该研究发现几乎没有证据表明,对大多数儿童来说,花在屏幕上的时间损害了社交技能。"},{"sp":"听力篇章 3","en":"It's easy to spend all day searching for inspiration.","cn":"人们很容易花一整天时间寻找灵感。"},{"sp":"听力篇章 3","en":"You can find incredible videos, articles and news stories about the success of others.","cn":"你可以找到关于他人成功的精彩视频、文章和新闻报道。"},{"sp":"听力篇章 3","en":"The problem is that consuming the success and ideas of others is passive inspiration.","cn":"问题在于,消费他人的成功和想法是被动的灵感。"},{"sp":"听力篇章 3","en":"Every time you read an article or listen to an interview, you're practicing passive inspiration.","cn":"每次你阅读一篇文章或收听一次采访,你都在实践被动灵感。"},{"sp":"听力篇章 3","en":"You might learn something, but you don't actually have to do anything.","cn":"你可能会学到一些东西,但你实际上不必做任何事情。"},{"sp":"听力篇章 3","en":"Hearing about other people's success isn't the same as creating your own.","cn":"听说他人的成功并不等同于创造你自己的成功。"},{"sp":"听力篇章 3","en":"Instead, it is through the process of active inspiration—the act of creating things, applying new ideas to our goals, and making mistakes that we discover who we are and what is important to us.","cn":"相反,正是通过主动灵感的过程——创造事物、将新想法应用于我们的目标、犯错误的行动——我们才发现自己是谁以及什么对我们重要。"},{"sp":"听力篇章 3","en":"Furthermore, active inspiration is what results in long-term passion and enthusiasm.","cn":"此外,主动灵感会带来长期的热情和激情。"},{"sp":"听力篇章 3","en":"Watching someone else's success might leave you feeling excited for a few minutes.","cn":"观看他人的成功可能会让你兴奋几分钟。"},{"sp":"听力篇章 3","en":"However, taking action and applying a new idea to your life will inspire you more than anything someone else can say.","cn":"然而,采取行动并将新想法应用到你的生活中,会比他人所说的任何话都更能激励你。"},{"sp":"听力篇章 3","en":"Learning and listening can help you think about things in a different way.","cn":"学习和倾听可以帮助你以不同的方式思考问题。"},{"sp":"听力篇章 3","en":"But creating, producing, and experimenting is what drives you forward.","cn":"但创造、生产和实验才是推动你前进的动力。"},{"sp":"听力篇章 3","en":"Passive inspiration can give you ideas, but active inspiration will give you power.","cn":"被动灵感可以给你想法,但主动灵感会给你力量。"},{"sp":"听力篇章 3","en":"Too often we spend our lives consuming the world around us instead of creating it.","cn":"我们常常把生活花在消费周围的世界而不是创造它上面。"},{"sp":"听力篇章 3","en":"And what matters is the power your actions have to inspire you.","cn":"而重要的是你的行动激励你的力量。"},{"sp":"听力篇章 3","en":"The best inspiration comes from the application of ideas, not the consumption of them.","cn":"最好的灵感来自想法的应用,而非对它们的消费。"}]},{"id":"cet4-2022-12-1","level":"CET4","exam":"2022_12_1","year":2022,"month":12,"set":1,"type":"整卷听力","title":"2022年12月 四级第1套 · 听力真题","source":"2022年12月 CET-4 第1套 · 听力（本地原音 + 逐句原文）","audio":"assets/audio/2022/cet4-2022-12-set1.mp3","intro":"听力原文按录音篇目逐句拆分，中文译文仅供参考；音频为本地真题原音，整卷原音无法定位单句，逐句请用下方播放器。","questions":[],"lines":[{"sp":"短篇新闻 1","en":"Operations at one of Australia's largest gold mines had to be temporarily suspended on Friday after a partial wall collapse at one of the mine's dams.","cn":"周五,澳大利亚最大的金矿之一因其中一座尾矿坝发生部分坝体垮塌而不得不暂时停止运营。"},{"sp":"短篇新闻 1","en":"The wall collapse at the Cadia mine came just a few days after two earthquakes hit the area.","cn":"Cadia矿区的坝体垮塌发生在该地区遭受两次地震袭击后仅数天。"},{"sp":"短篇新闻 1","en":"The damage to the dam wall was noticed in the late afternoon on Friday when workers found a section of the northern dam wall had collapsed into the southern dam.","cn":"周五傍晚,工作人员发现北坝的一段坝体已坍塌至南坝中,从而注意到坝体受损。"},{"sp":"短篇新闻 1","en":"The dams contain waste products of mining and can contain materials which are harmful to the environment and human health.","cn":"这些尾矿坝容纳采矿废弃物,可能含有对环境和人类健康有害的物质。"},{"sp":"短篇新闻 1","en":"The dams are generally constructed using earth-fill and are gradually raised over time.","cn":"这些尾矿坝通常采用土石填筑建造,并随时间逐步加高。"},{"sp":"短篇新闻 1","en":"The company was unable to confirm whether the recent earthquakes had contributed to the dam's wall collapse, but said it was conducting a thorough investigation.","cn":"该公司无法确认近期地震是否导致了坝体垮塌,但表示正在进行彻底调查。"},{"sp":"短篇新闻 1","en":"A company spokesperson said the operations at the site had been halted while the investigation is ongoing and that the break had posed no safety threat to workers.","cn":"公司发言人表示,在调查期间该矿区的运营已被暂停,且此次坝体坍塌未对工作人员构成安全威胁。"},{"sp":"短篇新闻 2","en":"Two boys and four girls were born on Monday to the surprise of a young couple and doctors who had expected five babies.","cn":"周一,一对年轻夫妇和原本预期会有五个婴儿的医生们惊讶地迎来了两个男孩和四个女孩的诞生。"},{"sp":"短篇新闻 2","en":"This was the first record of six babies being born at the same time in that region.","cn":"这是该地区首次有六个婴儿同时出生的记录。"},{"sp":"短篇新闻 2","en":"The doctors prepared from early in the morning to help deliver five tiny citizens.","cn":"医生们从清晨就开始准备协助接生五个小公民。"},{"sp":"短篇新闻 2","en":"They were in the operating room with five teams of doctors, one for each baby.","cn":"他们在手术室里准备了五组医生团队,每个婴儿配备一组。"},{"sp":"短篇新闻 2","en":"The first five babies were delivered successfully, and all baby beds were occupied.","cn":"前五个婴儿成功分娩,所有婴儿床都被占用了。"},{"sp":"短篇新闻 2","en":"And then all of a sudden, it turned out there was another waiting to come out.","cn":"然后突然之间,发现还有另一个婴儿等待出生。"},{"sp":"短篇新闻 2","en":"The doctor said the babies were in healthy condition, but could not go home immediately.","cn":"医生表示婴儿们健康状况良好,但不能立即回家。"},{"sp":"短篇新闻 2","en":"They needed to stay in the hospital for two to three months for medical supervision.","cn":"他们需要在医院接受两到三个月的医学监护。"},{"sp":"短篇新闻 2","en":"The mother who is in stable condition could return home a day later if all physical tests came back normal.","cn":"状况稳定的母亲如果所有体检结果正常,一天后就可以回家。"},{"sp":"短篇新闻 2","en":"The babies' mother commented that they had already prepared room for five babies at home, so they will have to rearrange things for their happy surprise.","cn":"婴儿的母亲表示他们已经在家里为五个婴儿准备了房间,所以他们必须为这个惊喜重新安排。"},{"sp":"短篇新闻 2","en":"The new parents have yet to name the sixth baby but are considering either Lily or Rose.","cn":"这对新父母尚未给第六个婴儿取名,但正在考虑Lily或Rose。"},{"sp":"短篇新闻 3","en":"A Spanish island called Palmador has been bought by a family from Europe for 18 million euros.","cn":"一座名为Palmador的西班牙岛屿已被一个欧洲家族以1800万欧元购得。"},{"sp":"短篇新闻 3","en":"The island is often described as heaven on earth by holidaymakers.","cn":"这座岛屿常被度假者形容为人间天堂。"},{"sp":"短篇新闻 3","en":"For decades tourists have been flocking to Palmador, which is located off the southeast coast of Spain.","cn":"数十年来，游客纷纷涌向位于西班牙东南海岸外的Palmador岛。"},{"sp":"短篇新闻 3","en":"They come to enjoy its unspoiled beaches and crystal clear waters.","cn":"他们来此享受未受破坏的海滩和清澈见底的海水。"},{"sp":"短篇新闻 3","en":"Its natural beauty is protected as it lies inside a natural park.","cn":"由于该岛位于自然公园内,其自然美景受到保护。"},{"sp":"短篇新闻 3","en":"Although Palmador is one of the most famous private islands in the world, its seafront is public land and is a favorite destination for famous people.","cn":"尽管Palmador是世界上最著名的私人岛屿之一,但其海滨属于公共土地,是名人最喜爱的目的地。"},{"sp":"短篇新闻 3","en":"When the island was put up for sale, it was offered to the local government but proved too expensive for the local authorities.","cn":"当该岛挂牌出售时,曾提供给当地政府,但对当地政府来说价格过于昂贵。"},{"sp":"短篇新闻 3","en":"It is unclear whether the new owners have the power to ban tourists from the island.","cn":"目前尚不清楚新业主是否有权禁止游客登岛。"},{"sp":"短篇新闻 3","en":"But with their newfound luxury comes the responsibility for its protection and maintenance.","cn":"但随着新获得的奢华享受,他们也肩负着保护和维护该岛的责任。"},{"sp":"短篇新闻 3","en":"The island is less than two miles long and half a mile wide.","cn":"该岛长度不到两英里,宽度半英里。"},{"sp":"短篇新闻 3","en":"It is said to have a remarkable location that few other private islands of this size can match, according to estate agents.","cn":"据房地产经纪人称,该岛拥有卓越的地理位置,少有其他同等规模的私人岛屿能与之媲美。"},{"sp":"短篇新闻 3","en":"Palmador is the perfect place to retreat to, somewhere to get away from the city noise and relax in beautiful surroundings with zero stress.","cn":"Palmador是完美的隐居之地,可以远离城市喧嚣,在美丽的环境中放松身心,毫无压力。"},{"sp":"长对话 1","en":"M: Hi, Christie's Gym Center.","cn":"M: 你好,Christie's健身中心。"},{"sp":"长对话 1","en":"How can I help you?","cn":"有什么可以帮您的?"},{"sp":"长对话 1","en":"W: Hi, I'm calling to ask about the newly scheduled gym classes.","cn":"W: 你好,我打电话是想问一下新安排的健身课程。"},{"sp":"长对话 1","en":"I'm just wondering if I can get a discount on them.","cn":"我想知道能不能打折。"},{"sp":"长对话 1","en":"M: Are you already a member?","cn":"M: 您已经是会员了吗?"},{"sp":"长对话 1","en":"W: Yes, I signed up two months ago, but I haven't been to any of the group classes yet.","cn":"W: 是的,我两个月前注册的,但还没参加过任何团体课程。"},{"sp":"长对话 1","en":"M: Can I take your name please?","cn":"M: 能告诉我您的名字吗?"},{"sp":"长对话 1","en":"W: Yes.","cn":"W: 可以。"},{"sp":"长对话 1","en":"My name is Carol Friedman.","cn":"我叫Carol Friedman。"},{"sp":"长对话 1","en":"M: Carol Friedman.","cn":"M: Carol Friedman。"},{"sp":"长对话 1","en":"That's right.","cn":"没错。"},{"sp":"长对话 1","en":"And you signed up two months ago.","cn":"您两个月前注册的。"},{"sp":"长对话 1","en":"Currently we are offering existing members discounts off two of our brand new classes, hot yoga, and advanced spinning, but the discount doesn't apply to any of our regular classes I'm afraid.","cn":"目前我们给现有会员提供两门全新课程的折扣,高温瑜伽和高级动感单车,但折扣恐怕不适用于我们的常规课程。"},{"sp":"长对话 1","en":"W: I'm only interested in the new classes.","cn":"W: 我只对新课程感兴趣。"},{"sp":"长对话 1","en":"So how much of a discount is there on these two new classes?","cn":"那这两门新课程有多少折扣?"},{"sp":"长对话 1","en":"M: The same discount of 20% is being offered to everyone at the door on a \"first come, first served\" basis for the first month.","cn":"M: 第一个月所有人在门口都能享受同样的8折优惠,先到先得。"},{"sp":"长对话 1","en":"It's a shame you missed out on the general discount.","cn":"很遗憾您错过了普遍折扣。"},{"sp":"长对话 1","en":"W: I see.","cn":"W: 我明白了。"},{"sp":"长对话 1","en":"M: But you can get 25% off if you sign up in advance.","cn":"M: 不过如果您提前报名可以享受75折。"},{"sp":"长对话 1","en":"Which of the two classes are you thinking about?","cn":"您考虑这两门课程中的哪一门?"},{"sp":"长对话 1","en":"W: Well, I guess I am only really interested in hot yoga.","cn":"W: 嗯,我想我只对高温瑜伽真正感兴趣。"},{"sp":"长对话 1","en":"Can you sign me up for the 10-week course on Thursday evenings?","cn":"能帮我报名周四晚上的10周课程吗?"},{"sp":"长对话 1","en":"M: Sure.","cn":"M: 当然可以。"},{"sp":"长对话 1","en":"Would you prefer to pay in advance?","cn":"您愿意提前付款吗?"},{"sp":"长对话 1","en":"W: No, I don't like giving my card details over the phone anyway.","cn":"W: 不,反正我不喜欢在电话里提供银行卡信息。"},{"sp":"长对话 1","en":"M: Okay, then.","cn":"M: 好的。"},{"sp":"长对话 1","en":"As you are already a member, the fee of the class will just be added to your monthly bill.","cn":"因为您已经是会员了,课程费用会直接加到您的月账单上。"},{"sp":"长对话 1","en":"W: That's perfect.","cn":"W: 太好了。"},{"sp":"长对话 1","en":"Thanks for your help.","cn":"谢谢你的帮助。"},{"sp":"长对话 1","en":"M: See you Thursday.","cn":"M: 周四见。"},{"sp":"长对话 2","en":"M: Well, I think that was quite a successful trip in the end.","cn":"M: 嗯，我觉得这次出差最后还是挺成功的。"},{"sp":"长对话 2","en":"Don't you think, Jenny?","cn":"你觉得呢，Jenny？"},{"sp":"长对话 2","en":"W: Absolutely.","cn":"W: 当然了。"},{"sp":"长对话 2","en":"There are lots of great potential markets here in China.","cn":"中国这边有很多很好的潜在市场。"},{"sp":"长对话 2","en":"So I'm sure that the head office in London will be pleased once we get back and present our research.","cn":"所以我相信我们回去向伦敦总部汇报研究结果时，他们会很满意的。"},{"sp":"长对话 2","en":"M: Okay.","cn":"M: 好的。"},{"sp":"长对话 2","en":"We've got a bit of spare time now.","cn":"我们现在还有点空闲时间。"},{"sp":"长对话 2","en":"Can we discuss the return trip to the head office?","cn":"能讨论一下回总部的行程吗？"},{"sp":"长对话 2","en":"W: Sure.","cn":"W: 当然。"},{"sp":"长对话 2","en":"I've checked the availability of flights from Beijing to London on the 22nd and you have a choice.","cn":"我查了22号从北京到伦敦的航班，你有两个选择。"},{"sp":"长对话 2","en":"There's a flight arriving the following morning, with a two-hour stopover in Dubai, or a flight arriving at 11:30 in the evening, with a five-hour stopover in Amsterdam.","cn":"一个是第二天早上到达的航班，在Dubai转机两小时；另一个是晚上11点半到达的航班，在Amsterdam转机五小时。"},{"sp":"长对话 2","en":"M: Right.","cn":"M: 好的。"},{"sp":"长对话 2","en":"Well, that's obvious then, isn't it?","cn":"那很明显了，不是吗？"},{"sp":"长对话 2","en":"W: okay, so that's Dubai.","cn":"W: 好的，那就是Dubai那班。"},{"sp":"长对话 2","en":"I've booked a room in a hotel about a mile from the office.","cn":"我在离办公室大约一英里的酒店订了房间。"},{"sp":"长对话 2","en":"The nearest metro station is Earl's Court.","cn":"最近的地铁站是Earl's Court。"},{"sp":"长对话 2","en":"M: Great.","cn":"M: 太好了。"},{"sp":"长对话 2","en":"Can you find a map that shows where the hotel is and send it to me online?","cn":"你能找张显示酒店位置的地图发给我吗？"},{"sp":"长对话 2","en":"I've never been to the head office, you know.","cn":"你知道的，我从没去过总部。"},{"sp":"长对话 2","en":"I want to see if I can get one of those rental bicycles and ride to the office just for fun.","cn":"我想看看能不能租一辆自行车骑到办公室，就当娱乐一下。"},{"sp":"长对话 2","en":"For the presentation, I'll bring my own laptop and hook it up to their projector.","cn":"演示的话，我会带自己的笔记本电脑，接到他们的投影仪上。"},{"sp":"长对话 2","en":"Do you remember the capacity of their meeting room?","cn":"你记得他们会议室能容纳多少人吗？"},{"sp":"长对话 2","en":"W: No, but I'll check.","cn":"W: 不记得了，但我会查一下。"},{"sp":"长对话 2","en":"M: Just one more thing.","cn":"M: 还有一件事。"},{"sp":"长对话 2","en":"I'll pay everything with my own card, right?","cn":"所有费用我都用自己的卡付，对吧？"},{"sp":"长对话 2","en":"And I'll submit my claims form afterwards.","cn":"然后之后再提交报销单。"},{"sp":"长对话 2","en":"W: No problem.","cn":"W: 没问题。"},{"sp":"长对话 2","en":"Just remember to keep all your receipts.","cn":"只要记得保留所有收据就行。"},{"sp":"长对话 2","en":"You remember the trouble you had last time.","cn":"你还记得上次遇到的麻烦吧。"},{"sp":"长对话 2","en":"M: Oh, don't remind me.","cn":"M: 哦，别提醒我了。"},{"sp":"听力篇章 1","en":"A new study has demonstrated the importance of women's rights.","cn":"一项新研究证明了女性权利的重要性。"},{"sp":"听力篇章 1","en":"The researchers behind the study state that many parts of the world have made good economic progress, but women's rights are often overlooked.","cn":"该研究的研究人员指出,世界许多地区取得了良好的经济进步,但女性权利往往被忽视。"},{"sp":"听力篇章 1","en":"Thus, they wanted to determine if there was a link between protection of women's rights and public health.","cn":"因此,他们想确定女性权利保护与公共健康之间是否存在联系。"},{"sp":"听力篇章 1","en":"The researchers analyzed databases which held information from 162 countries for the period 2004 to 2010.","cn":"研究人员分析了包含162个国家2004年至2010年期间信息的数据库。"},{"sp":"听力篇章 1","en":"Countries were classified according to the respect they gave to women's economic and social rights. There were three categories. They were high, moderate, and poor.","cn":"各国根据其对女性经济和社会权利的尊重程度进行分类。分为三个类别:高、中等和低。"},{"sp":"听力篇章 1","en":"Analysis of the data showed that countries with strong women's rights had better health than those where women's rights were not as respected.","cn":"数据分析显示,女性权利保障强的国家比那些不太尊重女性权利的国家拥有更好的健康状况。"},{"sp":"听力篇章 1","en":"The health indicators studied included disease prevention, reproductive health, death rates, and life expectancy.","cn":"研究的健康指标包括疾病预防、生殖健康、死亡率和预期寿命。"},{"sp":"听力篇章 1","en":"Furthermore, in countries where women's rights were most respected, but where access to hospitals and doctors was below average, health outcomes were still better than in countries rated as moderate or poor.","cn":"此外,在最尊重女性权利但医院和医生资源低于平均水平的国家,健康结果仍然优于被评为中等或低的国家。"},{"sp":"听力篇章 1","en":"This confirms that even with a lack of resources, if a country has strong women's rights, the health outcomes are better.","cn":"这证实了即使在资源匮乏的情况下,如果一个国家拥有强有力的女性权利保障,健康结果也会更好。"},{"sp":"听力篇章 1","en":"Thus, the researchers argued that gender equality is not just a women's rights issue. It is also a development issue. This is because better health aids economic development. They note that the value of women's rights has often been questioned from an economic standpoint. Some have argued that ensuring those rights would limit progress, but this study indicates the opposite.","cn":"因此,研究人员认为性别平等不仅仅是女性权利问题,也是发展问题。这是因为更好的健康状况有助于经济发展。他们指出,女性权利的价值常常从经济角度受到质疑。有些人认为确保这些权利会限制进步,但这项研究表明情况恰恰相反。"},{"sp":"听力篇章 2","en":"Sunshine and high temperatures can mean picnics and parks and trips to beaches, but they can make your body react in some strange ways.","cn":"阳光和高温可能意味着野餐、公园和海滩之旅,但它们也会让你的身体产生一些奇怪的反应。"},{"sp":"听力篇章 2","en":"First, sunshine can actually affect your breath.","cn":"首先,阳光实际上会影响你的口气。"},{"sp":"听力篇章 2","en":"You may think that summer is the perfect time to go on a date or chat with an attractive boy or girl.","cn":"你可能认为夏天是约会或与有魅力的男孩或女孩聊天的完美时机。"},{"sp":"听力篇章 2","en":"But excessive heat can cause you to lose water, which has been proven to have a pretty unattractive side effect—bad breath.","cn":"但过度的高温会导致你失水,而这已被证明会产生一个相当不讨人喜欢的副作用——口臭。"},{"sp":"听力篇章 2","en":"When you are lacking water, your mouth becomes dry. Bacteria accumulate because there isn't enough water in your mouth to wash it away, Sunshine can stop you from sweating, too. The body's normal temperature is 36 to 37 degrees centigrade. But if it heats up to 40 to 41 degrees, you may find yourself getting heatstroke. At that point, your heat regulatory system can essentially quit, which stops you from sweating as your body tries to keep water around your vital organs.","cn":"当你缺水时,你的口腔会变得干燥。细菌会积聚,因为口腔中没有足够的水分来冲走它们。阳光也会阻止你出汗。身体的正常温度是36到37摄氏度。但如果温度升高到40到41度,你可能会发现自己中暑。在那时,你的体温调节系统基本上会停止工作,这会阻止你出汗,因为你的身体试图在重要器官周围保留水分。"},{"sp":"听力篇章 2","en":"However, the sun can have a positive influence on your body by raising your energy levels.","cn":"然而,阳光可以通过提高你的能量水平对你的身体产生积极影响。"},{"sp":"听力篇章 2","en":"You might feel like the sun is giving you extra energy for your day, which is actually happening.","cn":"你可能会觉得阳光给你的一天带来了额外的能量,而这确实正在发生。"},{"sp":"听力篇章 2","en":"And vitamin D from sunshine can help your body to absorb certain minerals, which are linked to building stronger bones.","cn":"而且来自阳光的维生素D可以帮助你的身体吸收某些矿物质,这些矿物质与增强骨骼有关。"},{"sp":"听力篇章 2","en":"Therefore, I suggest you spend more time in the park with your friends, but make sure you apply lots of skin protection and fill up those water bottles, too.","cn":"因此,我建议你多花时间和朋友在公园里,但一定要涂抹大量的防晒保护,也要把水瓶装满。"},{"sp":"听力篇章 3","en":"Left-handed people can find it inconvenient to do certain things, writing in a notebook for example, but there are a number of advantages of being left-handed.","cn":"左撇子在做某些事情时可能会感到不便,比如在笔记本上写字,但左撇子也有许多优势。"},{"sp":"听力篇章 3","en":"Research found that they were overrepresented among fighters in combat sports.","cn":"研究发现,在格斗运动中,左撇子的比例过高。"},{"sp":"听力篇章 3","en":"Left-handed fighters also had higher chances to win.","cn":"左撇子选手获胜的机会也更高。"},{"sp":"听力篇章 3","en":"This confirms the fighter theory.","cn":"这证实了战斗理论。"},{"sp":"听力篇章 3","en":"Left-handers may also be better at remembering events.","cn":"左撇子在记忆事件方面可能也更出色。"},{"sp":"听力篇章 3","en":"The explanation is that the two brain spheres of left-handers are more strongly connected.","cn":"解释是左撇子的两个大脑半球联系更紧密。"},{"sp":"听力篇章 3","en":"Being left-handed might be a factor in mathematical ability.","cn":"左撇子可能是数学能力的一个影响因素。"},{"sp":"听力篇章 3","en":"An Italian study found that for simple arithmetic there was little difference between right- and left-handed performance, but for more difficult problem-solving, left-handers won out.","cn":"一项意大利研究发现,在简单算术方面,左撇子和右撇子的表现差异不大,但在更困难的问题解决方面,左撇子胜出。"},{"sp":"听力篇章 3","en":"No one understands the reason for this.","cn":"没有人理解其中的原因。"},{"sp":"听力篇章 3","en":"Left-handed people may think differently.","cn":"左撇子的思维方式可能有所不同。"},{"sp":"听力篇章 3","en":"In one study, researchers showed the participants columns of abstract illustrations and asked them which ones they would prefer.","cn":"在一项研究中,研究人员向参与者展示了几列抽象插图,并询问他们更喜欢哪些。"},{"sp":"听力篇章 3","en":"Left-handed people were more likely to prefer the images on the left.","cn":"左撇子更可能喜欢左边的图像。"},{"sp":"听力篇章 3","en":"Right-handed people preferred the ones on the right.","cn":"右撇子更喜欢右边的图像。"},{"sp":"听力篇章 3","en":"Both groups disliked stuff on their opposite side.","cn":"两组人都不喜欢相反一侧的东西。"},{"sp":"听力篇章 3","en":"Left-handers are also overrepresented in professional, interactive sports.","cn":"左撇子在职业互动性运动中也占比过高。"},{"sp":"听力篇章 3","en":"Researchers have looked at the influence of being left-handed on performance and interactive sports.","cn":"研究人员研究了左撇子对互动性运动表现的影响。"},{"sp":"听力篇章 3","en":"Those that require the fastest reaction give left-handers the biggest advantage.","cn":"那些需要最快反应的运动给左撇子带来最大优势。"},{"sp":"听力篇章 3","en":"So if you have a left-handed child, you should encourage them to play table tennis, baseball and tennis.","cn":"因此,如果你有一个左撇子孩子,你应该鼓励他们打乒乓球、棒球和网球。"},{"sp":"听力篇章 3","en":"Being left-handed maximizes their chances of success in these sports.","cn":"左撇子最大化了他们在这些运动中的成功机会。"}]},{"id":"cet4-2022-12-2","level":"CET4","exam":"2022_12_2","year":2022,"month":12,"set":2,"type":"整卷听力","title":"2022年12月 四级第2套 · 听力真题","source":"2022年12月 CET-4 第2套 · 听力（本地原音 + 逐句原文）","audio":"assets/audio/2022/cet4-2022-12-set2.mp3","intro":"听力原文按录音篇目逐句拆分，中文译文仅供参考；音频为本地真题原音，整卷原音无法定位单句，逐句请用下方播放器。","questions":[],"lines":[{"sp":"短篇新闻 1","en":"The World Pipe Band Championships will take place in Glasgow on Saturday.","cn":"世界风笛乐队锦标赛将于周六在格拉斯哥举行。"},{"sp":"短篇新闻 1","en":"Over 120 of the world's best pipe bands will compete at the championships.","cn":"超过120支世界顶尖风笛乐队将参加锦标赛。"},{"sp":"短篇新闻 1","en":"Over 4,000 pipers and drummers are expected to descend on the city for the annual event.","cn":"预计超过4000名风笛手和鼓手将涌入该市参加这一年度盛事。"},{"sp":"短篇新闻 1","en":"It will take place at the St. James Playing Fields in Glasgow on Saturday, 18 May from 10:00 am until 7:00 pm.","cn":"比赛将于5月18日周六上午10点至晚上7点在格拉斯哥的St. James运动场举行。"},{"sp":"短篇新闻 1","en":"The event is free.","cn":"该活动免费入场。"},{"sp":"短篇新闻 1","en":"Also, a free shuttle bus will run between the event car parks and the competition site.","cn":"此外,将有免费班车往返于活动停车场和比赛场地之间。"},{"sp":"短篇新闻 1","en":"Shuttle buses will run every 15 minutes from 8:00 am until 8:00 pm.","cn":"班车从上午8点至晚上8点每15分钟一班。"},{"sp":"短篇新闻 1","en":"Glasgow City Council says it is estimated to bring £300,000 to the local economy.","cn":"格拉斯哥市议会表示,预计该活动将为当地经济带来30万英镑的收益。"},{"sp":"短篇新闻 1","en":"The first World Pipe Band Championships were held in Edinburgh in 1947.","cn":"首届世界风笛乐队锦标赛于1947年在爱丁堡举行。"},{"sp":"短篇新闻 1","en":"The event first took place in Glasgow in 1948.","cn":"该活动于1948年首次在格拉斯哥举办。"},{"sp":"短篇新闻 1","en":"It has been held regularly in Glasgow since 1986.","cn":"自1986年以来一直定期在格拉斯哥举行。"},{"sp":"短篇新闻 2","en":"Summer doesn't begin for two more days, but scientists are already sounding the alarm about dangerous ice melts going on right now in Greenland.","cn":"距离夏季开始还有两天,但科学家们已经对格陵兰岛目前正在发生的危险冰层融化发出警报。"},{"sp":"短篇新闻 2","en":"The vast island usually locks away enough fresh water in its ice sheet, which if melted can raise global sea levels by six meters.","cn":"这座广袤的岛屿通常将足够多的淡水锁在其冰盖中,如果融化可使全球海平面上升六米。"},{"sp":"短篇新闻 2","en":"And research shows that in recent years its ice has melted faster than ever before.","cn":"研究表明,近年来其冰层融化速度比以往任何时候都快。"},{"sp":"短篇新闻 2","en":"This month, as temperatures in northwestern Greenland approach all-time highs, researchers are encountering unusual, surprising levels of melting ice in the region.","cn":"本月,随着格陵兰岛西北部气温接近历史最高值,研究人员在该地区遇到了异常且令人惊讶的冰层融化水平。"},{"sp":"短篇新闻 2","en":"The most significant concern here is how early this is all happening.","cn":"这里最重大的担忧是这一切发生得如此之早。"},{"sp":"短篇新闻 2","en":"Greenland experiences annual ice melt and growth cycles.","cn":"格陵兰岛经历着年度冰层融化和增长周期。"},{"sp":"短篇新闻 2","en":"But this year, the melting season began in early May.","cn":"但今年,融化季节始于五月初。"},{"sp":"短篇新闻 2","en":"That's a month earlier than normal and something that's happened only once before in the historical record in 2016.","cn":"这比正常情况提前了一个月,而且在历史记录中只在2016年发生过一次。"},{"sp":"短篇新闻 2","en":"That means that not only is the ice melting very fast, it has more time to melt this summer than it would in a normal climate system.","cn":"这意味着冰层不仅融化得非常快,而且今年夏天它有比正常气候系统中更多的时间融化。"},{"sp":"短篇新闻 2","en":"Longer melt seasons like this one seem to lead to much greater contributions to sea-level rise than in previous decades.","cn":"像这样更长的融化季节似乎会导致对海平面上升的贡献远大于前几十年。"},{"sp":"短篇新闻 3","en":"Bundles containing thousands of pounds in cash keep turning up on the streets of Blackhall Colliery in northern England, according to police.","cn":"据警方称,在英格兰北部的Blackhall Colliery街道上不断出现装有数千英镑现金的捆包。"},{"sp":"短篇新闻 3","en":"Residents of the village have been coming across bundles of £20 notes—usually worth £2,000—in the former mining village in County Durham.","cn":"这个村庄的居民一直在Durham郡这个前矿业村发现成捆的20英镑纸币——通常价值2000英镑。"},{"sp":"短篇新闻 3","en":"The latest discovery was on Monday, meaning four of these cash bundles have been handed in this year and 13 since 2014.","cn":"最近一次发现是在周一,这意味着今年已有四个这样的现金捆包被上交,自2014年以来共有13个。"},{"sp":"短篇新闻 3","en":"The bundles are usually left in plain sight and have been scattered across the small coastal village.","cn":"这些捆包通常被放置在显眼位置,散布在这个沿海小村庄各处。"},{"sp":"短篇新闻 3","en":"The owner has two weeks to collect the cash, which is then returned to the finder if not claimed, according to Peterlee Police.","cn":"据Peterlee警方称,失主有两周时间来认领现金,如果无人认领,现金将归还给发现者。"},{"sp":"短篇新闻 3","en":"A Durham Police spokesperson said the money has been returned to the lucky finders in all cases except yesterday.","cn":"Durham警方发言人表示,除了昨天的情况外,所有案例中的钱款都已归还给幸运的发现者。"},{"sp":"短篇新闻 3","en":"Policeman John Forster said in a statement: \"The circumstances remain a mystery so we would welcome any information that will help us get to the bottom of these random incidents.\"","cn":"警察John Forster在一份声明中说:\"具体情况仍是一个谜,因此我们欢迎任何能帮助我们查明这些随机事件真相的信息。\""},{"sp":"短篇新闻 3","en":"He told The Northern Echo: \"It isn't an affluent part of the world, so for them to find cash of that amount and instantly think about taking it to the police stations shows the community spirit there is.\"","cn":"他告诉The Northern Echo:\"这里并不是一个富裕的地方,所以他们发现那么多现金后立即想到送到警察局,这显示了当地的社区精神。\""},{"sp":"长对话 1","en":"W: It's your birthday next week.","cn":"W: 下周就是你的生日了。"},{"sp":"长对话 1","en":"What have you got planned?","cn":"你有什么计划吗？"},{"sp":"长对话 1","en":"M: I'm not sure.","cn":"M: 我还不确定。"},{"sp":"长对话 1","en":"I often feel strange on my birthday.","cn":"我在生日的时候经常感觉怪怪的。"},{"sp":"长对话 1","en":"It's like my brain decides to have a crisis.","cn":"就好像我的大脑决定要来一场危机。"},{"sp":"长对话 1","en":"W: It's not entirely unusual to feel anxious or sad around your birthday.","cn":"W: 在生日前后感到焦虑或悲伤并不完全罕见。"},{"sp":"长对话 1","en":"Birthdays can tap into a lot of things people worry about, including their achievements in life in the past decade, or their accomplishments of the past year.","cn":"生日会触及人们担心的很多事情，包括他们过去十年的人生成就，或者过去一年的成绩。"},{"sp":"长对话 1","en":"Many begin to search for the meaning of their existence, leading to behaviors such as ending or starting a relationship, or plans, like starting a vigorous diet or fitness program.","cn":"许多人开始寻找自己存在的意义，导致一些行为，比如结束或开始一段关系，或者制定计划，比如开始严格的饮食或健身计划。"},{"sp":"长对话 1","en":"M: I have wonderful friends and I love celebrating their birthdays.","cn":"M: 我有很棒的朋友，我也喜欢庆祝他们的生日。"},{"sp":"长对话 1","en":"But I don't like being the center of attention, receiving gifts and having a fuss made.","cn":"但我不喜欢成为关注的焦点，收礼物，被大家围着忙活。"},{"sp":"长对话 1","en":"It seems to trigger a type of social anxiety.","cn":"这似乎会引发一种社交焦虑。"},{"sp":"长对话 1","en":"I think social media too can intensify things as birthdays now play out more publicly.","cn":"我觉得社交媒体也会让事情更严重，因为现在生日更多是公开展示的。"},{"sp":"长对话 1","en":"Birthday reminders can be helpful, but I kind of worry I won't be able to drum up my own day and show it to look as exciting as it is supposed to be.","cn":"生日提醒可能有帮助,但我有点担心我没法把自己的生日搞得看起来像应该的那么激动人心。"},{"sp":"长对话 1","en":"W: Well, to deal with the birthday blues, you should not isolate yourself.","cn":"W: 嗯，要应对生日忧郁，你不应该把自己孤立起来。"},{"sp":"长对话 1","en":"It's best to gradually face your birthday with people you trust.","cn":"最好是和你信任的人一起逐渐面对你的生日。"},{"sp":"长对话 1","en":"That would help you learn self-acceptance, or that it's okay to be the focus.","cn":"这会帮助你学会自我接纳，或者说成为焦点也没关系。"},{"sp":"长对话 1","en":"M: Perhaps.","cn":"M: 也许吧。"},{"sp":"长对话 1","en":"Or I could perceive my birthday as an opportunity to do something for others like asking people to make a donation instead of buying a gift.","cn":"或者我可以把生日看作是为别人做点什么的机会，比如请人们捐款而不是买礼物。"},{"sp":"长对话 1","en":"W: Exactly.","cn":"W: 没错。"},{"sp":"长对话 1","en":"Or even simply see your birthday as an opportunity to bring people together for them to have fun.","cn":"或者甚至可以简单地把你的生日看作是把大家聚在一起让他们开心的机会。"},{"sp":"长对话 2","en":"W: The metro was absolutely terrible this morning.","cn":"W: 今天早上地铁真是糟糕透了。"},{"sp":"长对话 2","en":"M: Oh, was there a delay?","cn":"M: 哦,是晚点了吗?"},{"sp":"长对话 2","en":"W: No, but the train was so packed that I could barely move, and it was difficult to breathe too.","cn":"W: 不是,但是车厢挤得我几乎动弹不得,连呼吸都困难。"},{"sp":"长对话 2","en":"At every station, more people squeezed in and I got pushed further and further inside.","cn":"每到一站,就有更多人挤进来,我被越挤越往里面。"},{"sp":"长对话 2","en":"When I got to my station, I could hardly get out.","cn":"到我那站的时候,我几乎下不了车。"},{"sp":"长对话 2","en":"Once I did get out, I was totally exhausted.","cn":"好不容易出来了,整个人都累瘫了。"},{"sp":"长对话 2","en":"M: That sounds like a nightmare.","cn":"M: 听起来像噩梦一样。"},{"sp":"长对话 2","en":"Why didn't you take the bus?","cn":"你为什么不坐公交车呢?"},{"sp":"长对话 2","en":"W: The bus takes twice as long and it's just as crowded.","cn":"W: 公交车要花两倍的时间,而且一样挤。"},{"sp":"长对话 2","en":"M: Well, what's the alternative? Haven't you got a car?","cn":"M: 那还有什么办法?你没有车吗?"},{"sp":"长对话 2","en":"W: I've got a driver's license, but that's all.","cn":"W: 我有驾照,但也就仅此而已。"},{"sp":"长对话 2","en":"I'm saving up to buy something reasonably small and cute, but it's still a bit expensive for me, and it'll take a while before I have enough money.","cn":"我在攒钱买辆比较小巧可爱的车,但对我来说还是有点贵,还得攒一阵子才够。"},{"sp":"长对话 2","en":"M: Have you thought about getting an electric motorbike?","cn":"M: 你考虑过买电动摩托车吗?"},{"sp":"长对话 2","en":"W: I consider that for maybe a minute.","cn":"W: 我可能考虑了一分钟吧。"},{"sp":"长对话 2","en":"But honestly, I've just seen too many horrible accidents involving those dangerous monsters.","cn":"但说实话,我见过太多涉及那些危险怪物的可怕事故了。"},{"sp":"长对话 2","en":"M: What about those popular shared bikes? You could register to use one.","cn":"M: 那些流行的共享单车怎么样?你可以注册用一辆。"},{"sp":"长对话 2","en":"W: Yeah, that's a possibility.","cn":"W: 嗯,这倒是个可能。"},{"sp":"长对话 2","en":"There are always several of those bikes out in front of our apartment complex.","cn":"我们小区门口总有好几辆那种车。"},{"sp":"长对话 2","en":"M: Or you could just walk to work.","cn":"M: 或者你可以走路去上班。"},{"sp":"长对话 2","en":"W: Well, it's five kilometers from home to the office.","cn":"W: 嗯,从家到办公室有五公里。"},{"sp":"长对话 2","en":"But you've given me a thought.","cn":"不过你倒是给了我一个想法。"},{"sp":"长对话 2","en":"I could take a change of clothes and jog to work.","cn":"我可以带套换洗衣服,跑步去上班。"},{"sp":"长对话 2","en":"But at this time of year, the air pollution is a real problem.","cn":"但这个时节,空气污染真的是个问题。"},{"sp":"长对话 2","en":"M: Oh, yeah.","cn":"M: 哦,对。"},{"sp":"长对话 2","en":"I didn't think of that.","cn":"我没想到这个。"},{"sp":"长对话 2","en":"You take a taxi if you really have to.","cn":"实在不行你可以打车。"},{"sp":"长对话 2","en":"W: Well, that's an expensive way to get to work.","cn":"W: 嗯,那上班成本太高了。"},{"sp":"长对话 2","en":"M: Not if you use a ride sharing app.","cn":"M: 如果用拼车软件就不贵了。"},{"sp":"长对话 2","en":"W: Good idea.","cn":"W: 好主意。"},{"sp":"长对话 2","en":"I'll download one immediately.","cn":"我马上下载一个。"},{"sp":"长对话 2","en":"Thank you.","cn":"谢谢你。"},{"sp":"听力篇章 1","en":"Steve Miller began his career in IT back in the late 1980s.","cn":"Steve Miller 在 20 世纪 80 年代末开始了他的 IT 职业生涯。"},{"sp":"听力篇章 1","en":"Being a deaf person in tech required a huge amount of effort in organization.","cn":"作为一名科技行业的失聪人士,需要在组织协调方面付出巨大努力。"},{"sp":"听力篇章 1","en":"Because there was no email or text message service, everything had to be done face to face, or by telephone.","cn":"因为那时没有电子邮件或短信服务,一切都必须面对面进行,或者通过电话完成。"},{"sp":"听力篇章 1","en":"Communicating in meetings was very difficult.","cn":"在会议中交流非常困难。"},{"sp":"听力篇章 1","en":"He needed a sign language interpreter for every meeting, but it was a huge effort to coordinate.","cn":"他每次会议都需要一名手语翻译,但协调这件事需要付出巨大努力。"},{"sp":"听力篇章 1","en":"These days, although challenges still remain, it's a good time to be a deaf person in tech, says Miller.","cn":"Miller 说,如今尽管挑战依然存在,但对于科技行业的失聪人士来说是个好时代。"},{"sp":"听力篇章 1","en":"Big advances in speech recognition technology have enabled communication tools to turn live speech into text in real time on your smartphone or laptop, and sign language into text as well.","cn":"语音识别技术的重大进步使得通信工具能够在智能手机或笔记本电脑上实时将现场语音转换为文本,也能将手语转换为文本。"},{"sp":"听力篇章 1","en":"New Tech coupled with improvements in hearing aid technology and medical advances means that Miller is able to focus far more on his work.","cn":"新技术加上助听器技术的改进和医学进步,意味着 Miller 能够更加专注于他的工作。"},{"sp":"听力篇章 1","en":"He has benefited to a great extent from a tiny hearing device in his ear.","cn":"他从耳中的一个微型助听设备中获益匪浅。"},{"sp":"听力篇章 1","en":"It gives him a degree of hearing, and he can use a variety of communication methods depending on the situation.","cn":"它给了他一定程度的听力,他可以根据情况使用各种交流方式。"},{"sp":"听力篇章 1","en":"He can employ lip-reading and have meetings via video instead of on the phone.","cn":"他可以使用唇读,通过视频而不是电话进行会议。"},{"sp":"听力篇章 1","en":"These things have made a huge difference.","cn":"这些事情带来了巨大的改变。"},{"sp":"听力篇章 1","en":"He no longer has to worry about whether or not he can understand.","cn":"他不再需要担心自己能否理解。"},{"sp":"听力篇章 1","en":"He can just concentrate on how interesting the meeting might be and what he needs to get out of it in order to progress.","cn":"他可以只专注于会议可能有多有趣,以及他需要从中获得什么才能取得进展。"},{"sp":"听力篇章 2","en":"Colour is now spreading through our homes, up staircases, across wood frames and ceilings, filling in neutral spaces.","cn":"色彩正在我们的家中蔓延，爬上楼梯，延伸至木框架和天花板，填充着中性色空间。"},{"sp":"听力篇章 2","en":"According to one interior designer, when people return home, they want to see colours that cheer them up and give them a hug.","cn":"据一位室内设计师说,当人们回到家时,他们想看到能让他们振奋精神、给予他们拥抱的色彩。"},{"sp":"听力篇章 2","en":"Pure white walls simply don't do that.","cn":"纯白色的墙壁根本做不到这一点。"},{"sp":"听力篇章 2","en":"They don't look after you.","cn":"它们不会照顾你。"},{"sp":"听力篇章 2","en":"Another interior designer commented that certain combinations can key into something on a deeper level, transporting you to a different moment in time.","cn":"另一位室内设计师评论说,某些色彩组合可以触及更深层次的东西,将你带到不同的时刻。"},{"sp":"听力篇章 2","en":"That's the power of colour.","cn":"这就是色彩的力量。"},{"sp":"听力篇章 2","en":"If you are thinking to try colour on some of your neutral walls, the advice is refreshingly simple: Choose a colour you actually like.","cn":"如果你正在考虑在一些中性色墙面上尝试色彩,建议非常简单:选择一个你真正喜欢的颜色。"},{"sp":"听力篇章 2","en":"Don't go for a colour because it's in fashion, or you've seen it in a magazine.","cn":"不要因为某种颜色流行或你在杂志上看到过就选择它。"},{"sp":"听力篇章 2","en":"If you're weary of full colour, test your tolerance with smaller spaces, such as the inside of a cupboard or a bright window frame.","cn":"如果你对全彩色心存疑虑,可以用较小的空间测试你的接受度,比如橱柜内部或明亮的窗框。"},{"sp":"听力篇章 2","en":"If it gives you joy every time you open the cupboard, you can start to take it further.","cn":"如果每次打开橱柜它都能给你带来快乐,你就可以开始进一步尝试。"},{"sp":"听力篇章 2","en":"One can also paint the wooden frameworks the same colour as the walls, helping the rooms look bigger.","cn":"人们还可以将木框架漆成与墙壁相同的颜色,帮助房间看起来更大。"},{"sp":"听力篇章 2","en":"In the kitchen, painting the overhead cupboards and the walls in the same colour can make it feel more spacious.","cn":"在厨房里,将吊柜和墙壁漆成相同的颜色可以让空间感觉更宽敞。"},{"sp":"听力篇章 2","en":"While painting the kitchen counters, a bold colour can make everything feel more open and lighter.","cn":"在粉刷厨房台面时,大胆的色彩可以让一切感觉更开阔、更轻盈。"},{"sp":"听力篇章 2","en":"Additionally, a painted ceiling is a magical thing without being too obvious and can affect how the space feels as well.","cn":"此外,粉刷天花板是一件神奇的事情,既不会太明显,也能影响空间的感觉。"},{"sp":"听力篇章 3","en":"Parents often hear that reading to their children is critical for supporting development, and the message is getting through to them.","cn":"家长们经常听说给孩子读书对支持其发展至关重要，而且这一信息正在被他们接受。"},{"sp":"听力篇章 3","en":"In fact, in the United States, a little over half of children between the ages of three and five were read to every day in 2007, and 83% of children in that age group in the same country were read to three or more times per week in 2012.","cn":"事实上，在美国，2007年有略高于一半的三至五岁儿童每天被朗读，而2012年同一国家该年龄段83%的儿童每周被朗读三次或更多次。"},{"sp":"听力篇章 3","en":"This is good news, because reading to young children helps their language and brain development.","cn":"这是个好消息,因为给幼儿读书有助于他们的语言和大脑发育。"},{"sp":"听力篇章 3","en":"In fact, recent research has found that both the quality and quantity of shared book reading in infancy predicted later childhood vocabulary and reading skills.","cn":"事实上,最近的研究发现,婴儿期共享读书的质量和数量都能预测儿童后期的词汇量和阅读技能。"},{"sp":"听力篇章 3","en":"In other words, the more time parents spend reading, the greater the developmental benefits in their four-year-old children.","cn":"换句话说,父母花在阅读上的时间越多,他们四岁孩子的发育益处就越大。"},{"sp":"听力篇章 3","en":"This is an important finding. But does it matter what books parents read? A new study has investigated this question. It followed infants across the second six months of life and found that when parents showed babies books that had faces or objects with specific labels, they learned more. This is in contrast to books that did not name images, or books that had the same label under each image. Books that named different characters also promoted greater learning. So what does this mean for parents? Not all books are created equal, so parents need to choose the books they share with their children with great care.","cn":"这是一个重要的发现。但父母读什么书重要吗?一项新研究调查了这个问题。该研究跟踪了婴儿生命中第二个六个月的情况,发现当父母给婴儿展示有面孔或带有特定标签的物体的书籍时,他们学到的更多。这与那些不标注图像名称的书籍或每张图像下都有相同标签的书籍形成对比。标注不同角色名称的书籍也促进了更多的学习。那么这对父母意味着什么呢?并非所有书籍都是一样的,因此父母需要非常谨慎地选择与孩子分享的书籍。"}]},{"id":"cet6-2022-09-1","level":"CET6","exam":"2022_09_1","year":2022,"month":9,"set":1,"type":"整卷听力","title":"2022年9月 六级第1套 · 听力真题","source":"2022年9月 CET-6 第1套 · 听力（本地原音 + 逐句原文）","audio":"assets/audio/2022/cet6-2022-09-set1.mp3","intro":"听力原文按录音篇目逐句拆分，中文译文仅供参考；音频为本地真题原音，整卷原音无法定位单句，逐句请用下方播放器。","questions":[],"lines":[{"sp":"长对话 1","en":"W: Welcome to Money Matters, a weekly program that helps you manage your money.","cn":"W: 欢迎收听《金钱 matters》，这是一档每周播出的、帮助你管理资金的节目。"},{"sp":"长对话 1","en":"Tonight, I'll be talking to Mary Johnson about budgeting.","cn":"今晚，我将和玛丽·约翰逊聊聊如何制定预算。"},{"sp":"长对话 1","en":"M: Hello, everyone.","cn":"M: 大家好。"},{"sp":"长对话 1","en":"W: There's a magic about money.","cn":"W: 钱有一种魔力。"},{"sp":"长对话 1","en":"When it's not planned for, tracked and kept a record of, it literally disappears.","cn":"如果事先不做规划、不进行追踪，也不留存记录，它真的会凭空消失。"},{"sp":"长对话 1","en":"What are some of the steps we can take to prevent this from happening?","cn":"我们可以采取哪些措施来防止这种情况发生呢？"},{"sp":"长对话 1","en":"M: Well, it's all about keeping track of your money.","cn":"M: 嗯，关键就是要记录你的资金收支。"},{"sp":"长对话 1","en":"If you don't do that, you'll never be able to set any goals for your budget or have the discipline to stick to them.","cn":"如果你不这么做，就永远无法为预算设定目标，也没有自律坚持下去。"},{"sp":"长对话 1","en":"W: That's easier said than done.","cn":"W: 说起来容易做起来难。"},{"sp":"长对话 1","en":"I read recently that only 41% of Americans adhere to a budget.","cn":"我最近读到一份资料，说只有41%的美国人会遵守预算。"},{"sp":"长对话 1","en":"M: Yes, but knowing what you earn and what you spend can give you reassurance that you won't get into debt in the first place.","cn":"M: 是的，但了解自己的收入和支出，可以让你放心，至少一开始不会陷入债务。"},{"sp":"长对话 1","en":"You can do this by adding up all of your sources of income you have and writing them all down on a piece of paper.","cn":"你可以把所有收入来源加起来，并全部写在一张纸上。"},{"sp":"长对话 1","en":"On the same page, write down all of your monthly expenses.","cn":"在同一页上，写下每月的所有开支。"},{"sp":"长对话 1","en":"W: I'm always amazed at how much my expenses add up.","cn":"W: 我总是惊讶于自己的开支加起来竟然那么多。"},{"sp":"长对话 1","en":"But designating each item as an income or an expense really helps me have a much better sense of all my spending.","cn":"但把每一项分别标记为收入或支出，确实能让我更清楚地了解自己的全部花费。"},{"sp":"长对话 1","en":"M: Right, most people have no idea how much they spend each day, let alone each week or month, no matter how careful they are.","cn":"M: 没错，大多数人根本不知道自己每天花了多少钱，更不用说每周或每月了，不管他们自认为多么谨慎。"},{"sp":"长对话 1","en":"Next, subtract your monthly expenses from income.","cn":"接下来，用收入减去每月的开支。"},{"sp":"长对话 1","en":"If the result is positive, you are living within your means.","cn":"如果结果是正数，说明你的生活没有超出自己的经济能力。"},{"sp":"长对话 1","en":"If the result is a negative number, you're going to have to cut back on your spending.","cn":"如果结果是负数，你就得减少开支了。"},{"sp":"长对话 1","en":"W: I'm usually a negative number.","cn":"W: 我通常都是负数。"},{"sp":"长对话 1","en":"I just can't resist the allure of all those prestigious goods.","cn":"我就是抵挡不住那些名牌商品的诱惑。"},{"sp":"长对话 1","en":"M: Well, it's not a catastrophe.","cn":"M: 嗯，这还不至于造成灾难。"},{"sp":"长对话 1","en":"But you do have to make some changes.","cn":"但你确实得做出一些改变。"},{"sp":"长对话 1","en":"Try cutting back on those non-essential items, sell some stuff in your attic, or shop online to avoid unnecessary temptations like chocolate.","cn":"试着减少购买那些非必需品，卖掉阁楼里的一些东西，或者在网上购物，以避免巧克力之类不必要的诱惑。"},{"sp":"长对话 1","en":"Failing that you can always find yourself a part-time job.","cn":"如果这些办法都不奏效，你还可以找一份兼职。"},{"sp":"长对话 2","en":"M: Hi there, I've come to see the flat.","cn":"M: 你好，我是来看这套公寓的。"},{"sp":"长对话 2","en":"My name is Mark Adams.","cn":"我叫马克·亚当斯。"},{"sp":"长对话 2","en":"We spoke on the phone on Wednesday.","cn":"我们周三通过电话。"},{"sp":"长对话 2","en":"W: Hi, Mark, come on up.","cn":"W: 你好，马克，上来吧。"},{"sp":"长对话 2","en":"I'll buzz you in.","cn":"我给你开门。"},{"sp":"长对话 2","en":"Green door on the second floor on the right side.","cn":"二楼右手边的绿门。"},{"sp":"长对话 2","en":"Nice to meet you, I spoke to all your references and they all checked out okay.","cn":"很高兴见到你，我联系过你提供的所有推荐人，他们的情况都没有问题。"},{"sp":"长对话 2","en":"So let me show you around.","cn":"我带你四处看看吧。"},{"sp":"长对话 2","en":"The place actually belongs to my mother, but her health isn't great, so we finally managed to persuade her to move in with us and rent this old place out.","cn":"这套房子其实属于我母亲，但她的身体状况不太好，所以我们终于说服她搬来和我们一起住，把这套老房子租出去。"},{"sp":"长对话 2","en":"M: It's a great size. Plenty of space. Very versatile. I think it's a winner for us.","cn":"M: 面积很大。空间充足，用途也很灵活。我觉得这套房子很适合我们。"},{"sp":"长对话 2","en":"W: Yes, all the appliances are brand-new.","cn":"W: 是的，所有家电都是全新的。"},{"sp":"长对话 2","en":"There's a washing machine and a tumble dryer in the utility room next to the kitchen.","cn":"厨房旁边的杂物间里有一台洗衣机和一台烘干机。"},{"sp":"长对话 2","en":"M: Lots of closet space too, which is fabulous.","cn":"M: 衣柜空间也很大，这太棒了。"},{"sp":"长对话 2","en":"My wife has a ridiculous number of shoes.","cn":"我妻子的鞋子多得离谱。"},{"sp":"长对话 2","en":"Now, the big question: What about noise and the neighbours?","cn":"现在，最关键的问题是：噪音和邻居怎么样？"},{"sp":"长对话 2","en":"W: Well, all the neighbours are elderly, so no noisy kids.","cn":"W: 嗯，所有邻居都是老年人，所以没有吵闹的孩子。"},{"sp":"长对话 2","en":"And the back of the house overlooks a clear and peaceful pond, so it's perfect if tranquility is what you are looking for.","cn":"而且房子的后面俯瞰着一个宁静清澈的池塘，如果你们追求安静，这里就再合适不过了。"},{"sp":"长对话 2","en":"M: That's good news.","cn":"M: 那真是个好消息。"},{"sp":"长对话 2","en":"We've been living in a less than glamorous part of Aberdeen, constantly harassed day and night by noisy neighbours.","cn":"我们一直住在阿伯丁一个不太体面的地方，日夜不停地被吵闹的邻居骚扰。"},{"sp":"长对话 2","en":"Getting to work was a nightmare too, as we only have one car and my wife has to use it as she works nights at the hospital.","cn":"上下班也像是一场噩梦，因为我们只有一辆车，而我妻子在医院上夜班，必须用那辆车。"},{"sp":"长对话 2","en":"W: Well, if you like the place, it's yours, as soon as I get a contract drawn up with the solicitor.","cn":"W: 好吧，只要你喜欢这里，这套房子就是你的，等我让律师拟好合同就可以了。"},{"sp":"长对话 2","en":"The first month's rent and a deposit are mandatory on signing the contract.","cn":"签合同的时候必须支付第一个月的房租和押金。"},{"sp":"长对话 2","en":"Then we can work out when is the best day for you to pay rent each month.","cn":"然后我们可以商量一个最适合你每月交房租的日子。"},{"sp":"长对话 2","en":"M: We'll be incredibly happy to be your new tenants. Thank you so much, My wife will be thrilled to get out of the shabby place we are now in, and start filling those wardrobes with all those shoes.","cn":"M: 我们会非常高兴成为你的新房客。太谢谢你了。我妻子一定会很开心能离开我们现在住的那个破旧地方，开始把那些衣柜塞满鞋子。"},{"sp":"听力篇章 1","en":"A new study has found a positive correlation between how much television children watch and their parents' stress levels.","cn":"一项新研究发现，儿童看电视的时间长短与其父母的压力水平呈正相关。"},{"sp":"听力篇章 1","en":"Why?","cn":"为什么？"},{"sp":"听力篇章 1","en":"Because the more television kids watch, the more they're exposed to advertising.","cn":"因为孩子看电视越多，接触到的广告就越多。"},{"sp":"听力篇章 1","en":"The more advertising they see, the more likely they are to insist on purchasing items when they go with their parents to the store.","cn":"他们看到的广告越多，和父母一起去商店时，就越有可能坚持要求购买某些商品。"},{"sp":"听力篇章 1","en":"This could generate conflict if the parents refuse.","cn":"如果父母拒绝，这可能会引发冲突。"},{"sp":"听力篇章 1","en":"All that, researchers say, can contribute to parents' overall stress levels.","cn":"研究人员表示，所有这些因素都可能导致父母的整体压力水平上升。"},{"sp":"听力篇章 1","en":"What's the solution?","cn":"解决办法是什么？"},{"sp":"听力篇章 1","en":"Perhaps the most obvious is curtailing screen time.","cn":"也许最明显的办法是限制屏幕使用时间。"},{"sp":"听力篇章 1","en":"Commercial content is there for a reason: to elicit purchasing behavior.","cn":"商业内容之所以存在，是有其原因的：诱导人们进行购买。"},{"sp":"听力篇章 1","en":"So parents might want to shut off the TV.","cn":"因此，家长可能会想关掉电视。"},{"sp":"听力篇章 1","en":"Researchers concede that this is easier said than done.","cn":"研究人员承认，这说起来容易做起来难。"},{"sp":"听力篇章 1","en":"So they suggest another option.","cn":"因此，他们提出了另一种选择。"},{"sp":"听力篇章 1","en":"Parents can change how they talk to their kids about purchases.","cn":"家长可以改变与孩子谈论购买行为的方式。"},{"sp":"听力篇章 1","en":"The researchers suggest that parents seek input from their children on family purchasing decisions. They shouldn't try to control all purchases. Instead, parents might tell their children things like \"I will listen to your advice on certain products or brands.\" This type of communication, the researchers assert, can lead to children making fewer purchasing demands. That means less parents' stress.","cn":"研究人员建议，家长在家庭购买决策中征求孩子的意见。他们不应试图控制所有购买行为。相反，家长可以对孩子说：“我会听取你对某些产品或品牌的建议。”研究人员断言，这种沟通方式可以减少孩子提出购买要求的次数。这意味着父母的压力会减轻。"},{"sp":"听力篇章 1","en":"However, the protective effect of this kind of communication diminishes with greater exposure to television.","cn":"然而，随着接触电视的增多，这种沟通方式的保护作用会减弱。"},{"sp":"听力篇章 1","en":"This is because advertising aimed at children is especially persuasive.","cn":"这是因为针对儿童的广告尤其具有说服力。"},{"sp":"听力篇章 1","en":"Advertisers use an assortment of tactics, such as bright colors, happy music and celebrity endorsements to appeal to children.","cn":"广告商会运用各种策略吸引儿童，例如鲜艳的色彩、欢快的音乐和名人代言。"},{"sp":"听力篇章 1","en":"Plus, children don't have the cognitive ability to fully understand advertising's intent.","cn":"此外，儿童还不具备充分理解广告意图的认知能力。"},{"sp":"听力篇章 1","en":"That makes them particularly vulnerable to advertisements.","cn":"这使他们特别容易受到广告的影响。"},{"sp":"听力篇章 2","en":"Everyone is supposed to cheer for good guys, and we should only punish the bad guys.","cn":"人人都应该为好人喝彩，而我们也只应该惩罚坏人。"},{"sp":"听力篇章 2","en":"But that's not what we always do.","cn":"但我们并不总是这样做。"},{"sp":"听力篇章 2","en":"Most of the time, we do indeed reward good people.","cn":"大多数时候，我们确实会奖励好人。"},{"sp":"听力篇章 2","en":"We also often punish people who harm others, or who aren't good team players.","cn":"我们也经常惩罚那些伤害他人或不善于团队合作的人。"},{"sp":"听力篇章 2","en":"But sometimes, the good guys also get punished or criticized, specifically because they are so good.","cn":"但有时，好人也会受到惩罚或批评，正是因为他们太优秀了。"},{"sp":"听力篇章 2","en":"This seems baffling, because it's detrimental to group cooperation.","cn":"这似乎令人费解，因为这种做法不利于群体合作。"},{"sp":"听力篇章 2","en":"However, the phenomenon has been discovered in multiple fields, and it has been found in every society.","cn":"然而，这一现象已在多个领域被发现，并且存在于每一个社会中。"},{"sp":"听力篇章 2","en":"Why does this happen?","cn":"为什么会发生这种情况？"},{"sp":"听力篇章 2","en":"Research suggests a simple reason.","cn":"研究表明，原因很简单。"},{"sp":"听力篇章 2","en":"When one person looks really good, others look bad by comparison.","cn":"当一个人表现得非常出色时，相比之下，其他人就显得很差。"},{"sp":"听力篇章 2","en":"Those others then have an incentive in stopping that person from looking good, especially if they can't or won't compete.","cn":"于是，那些人便有动机阻止这个人继续显得优秀，尤其是在他们无法或不愿与之竞争的情况下。"},{"sp":"听力篇章 2","en":"After all, we're all judged in comparison with others.","cn":"毕竟，我们都会在与他人的比较中受到评判。"},{"sp":"听力篇章 2","en":"When faced with someone better, what can a normal person do?","cn":"面对一个比自己优秀的人，一个普通人能做什么？"},{"sp":"听力篇章 2","en":"One option is to actively compete.","cn":"一种选择是积极竞争。"},{"sp":"听力篇章 2","en":"A second option is to bring that person down; that is, to suppress their cooperation or work ethic, infer selfish motives for their actions, or imply real or imagined hypocrisy.","cn":"第二种选择是拉低那个人，也就是说，压制其合作意愿或工作积极性，把他们的行为推断为出于自私动机，或者暗示他们存在真实或想象中的虚伪。"},{"sp":"听力篇章 2","en":"Other tactics include attacking them on unrelated dimensions, or punishing them outright.","cn":"其他策略还包括在无关的方面攻击他们，或者干脆惩罚他们。"},{"sp":"听力篇章 2","en":"Why does this matter?","cn":"为什么这很重要？"},{"sp":"听力篇章 2","en":"Critics often attack the motives of people who protect the environment, donate money, or work too hard.","cn":"批评者经常攻击那些保护环境、捐款或工作过于努力的人的动机。"},{"sp":"听力篇章 2","en":"Such good deeds are dismissed as naive or hypocritical by those who do not perform those deeds.","cn":"那些不做这些事情的人，会把这些善举斥为天真或虚伪。"},{"sp":"听力篇章 2","en":"This criticism may ultimately discourage people from doing good deeds.","cn":"这种批评最终可能会打击人们行善的积极性。"},{"sp":"听力篇章 2","en":"So it's important to recognize these attacks for what they are.","cn":"因此，认清这些攻击的本质非常重要。"},{"sp":"讲座 1","en":"In America, most researchers concede that boys and girls are brought up in different ways, taught different skills and rewarded for different acts.","cn":"在美国，大多数研究者承认，男孩和女孩以不同的方式被抚养长大，被教导不同的技能，并因不同的行为而受到奖励。"},{"sp":"讲座 1","en":"Women, it is agreed, excel at certain tasks, men at others.","cn":"人们一致认为，女性擅长某些任务，男性则擅长另一些任务。"},{"sp":"讲座 1","en":"There's little argument that some personality traits appear more dominant in one sex than in the other.","cn":"几乎没有人争辩说，某些人格特征在一个性别中比在另一个性别中表现得更为突出。"},{"sp":"讲座 1","en":"All of this notwithstanding, gender differences are very much in the media these days.","cn":"尽管如此，性别差异如今在媒体上仍是一个热门话题。"},{"sp":"讲座 1","en":"Since the rise of the women's movement, gender role behavior has come under closer scrutiny.","cn":"自妇女运动兴起以来，性别角色行为受到了更加密切的审视。"},{"sp":"讲座 1","en":"How has this affected friendship?","cn":"这对友谊产生了怎样的影响？"},{"sp":"讲座 1","en":"How do the sexes differ in their friendship relations?","cn":"两性在友谊关系方面有何不同？"},{"sp":"讲座 1","en":"Most preteen children have a best friend who is usually someone of the same sex and similar age.","cn":"大多数青春期前的儿童都有一个最要好的朋友，这个朋友通常与自己同性别且年龄相仿。"},{"sp":"讲座 1","en":"Both sexes share an essentially positive recollection of these childhood friendships; they do not differ in this respect.","cn":"两性对这些童年友谊都抱有基本上积极的回忆；在这一点上，他们并无不同。"},{"sp":"讲座 1","en":"However, the type of play engaged in during these early friendships is telling of the difference to come.","cn":"然而，在这些早期友谊中所进行的游戏类型，显示出日后差异的端倪。"},{"sp":"讲座 1","en":"Boys tend to form play groups that are competitive in nature; girls' groups more frequently revolve around cooperative enterprises.","cn":"男孩往往组成具有竞争性质的游戏群体；女孩的群体则更经常围绕合作性活动展开。"},{"sp":"讲座 1","en":"Thus, at an early age, boys become concerned with trying hard and winning while girls, by contrast, play house and school, engaging in roles that require complementary support.","cn":"因此，在很小的年纪，男孩就开始关注努力争取和获胜，而女孩则相反，她们玩过家家和学校游戏，扮演需要彼此配合支持的角色。"},{"sp":"讲座 1","en":"Speaking of their childhood, men recall being highly responsive to and aware of the gender-role opinions of other boys.","cn":"男性回忆童年时说，他们对其他男孩关于性别角色的看法高度敏感，也十分在意。"},{"sp":"讲座 1","en":"Girls in preteen years appear to be less susceptible to gender-role pressure.","cn":"青春期前的女孩似乎较少受到性别角色压力的影响。"},{"sp":"讲座 1","en":"It is not until the dating years that women report being concerned with feminine behavior.","cn":"直到开始约会的年龄，女性才会表示自己开始关注女性化的行为。"},{"sp":"讲座 1","en":"Males, for the most part, are responsive to the suggestion that their behavior is unmanly at almost any age.","cn":"在几乎任何年龄，男性大多都会对他人暗示其行为不够男子气概作出反应。"},{"sp":"讲座 1","en":"These early attitudes, reinforced by social conditioning, continue to play an active part in the friendships of both sexes during adolescence.","cn":"这些早期态度在社会环境塑造的强化下，在青春期继续积极影响着两性的友谊。"},{"sp":"讲座 1","en":"This is a period when the majority of males once again report a close alliance with same-sex friends.","cn":"这一时期，大多数男性再次表示自己与同性朋友结成了亲密联盟。"},{"sp":"讲座 1","en":"Now, however, with heightened intensity, considerable energy is devoted to competing for position and a definite undercurrent of competition permeates the relationship.","cn":"然而此时，竞争的强度已经提高，大量精力被投入到争夺地位之中，竞争的明确暗流也渗透在这种关系里。"},{"sp":"讲座 1","en":"Although in dissimilar fashion, females share equally fragile relationships at this age.","cn":"尽管表现形式不同，女性在这个年龄段也同样拥有脆弱的关系。"},{"sp":"讲座 1","en":"For them, the bond of loyalty extends only to the line of romantic involvement.","cn":"对她们而言，忠诚纽带只延伸到涉及恋爱的界限。"},{"sp":"讲座 1","en":"This is most apt to be the case in late adolescence, when dating and relationships with boys take sharp precedence over sisterhood.","cn":"青春期后期尤其容易出现这种情况，因为这时与男孩的约会和关系明显优先于女性之间的情谊。"},{"sp":"讲座 1","en":"Actually, dating dilutes the intensity of same sex friendships for men also.","cn":"事实上，约会也会削弱男性同性友谊的亲密程度。"},{"sp":"讲座 1","en":"For the majority of us, the moment we begin to date seriously, there's a competition between romance and friendship.","cn":"对我们大多数人来说，一旦开始认真约会，浪漫关系与友谊之间就会形成竞争。"},{"sp":"讲座 2","en":"Good afternoon.","cn":"下午好。"},{"sp":"讲座 2","en":"In today's lecture, we'll be talking about how and when to disclose a disability when applying for a job.","cn":"在今天的讲座中，我们将讨论求职时何时以及如何披露残疾状况。"},{"sp":"讲座 2","en":"On average, about 20% of the population has some form of disability.","cn":"平均而言，大约20%的人口患有某种形式的残疾。"},{"sp":"讲座 2","en":"Most countries these days have equal opportunity and non-discrimination laws.","cn":"如今，大多数国家都制定了平等机会和反歧视法律。"},{"sp":"讲座 2","en":"Yet, disabled people often find it hard to decide when, how, and if at all to raise their disability problem with the potential employer.","cn":"然而，残疾人往往觉得很难决定何时、如何向潜在雇主提出自己的残疾问题，甚至难以决定是否要提出。"},{"sp":"讲座 2","en":"There is uncertainty about how a recruiter will perceive their disability.","cn":"关于招聘人员会如何看待他们的残疾，存在着不确定性。"},{"sp":"讲座 2","en":"As such, many candidates fear they wouldn't be considered for a position, as a result of disclosing this personal information.","cn":"正因如此，许多应聘者担心透露这一个人信息会导致自己不被职位考虑。"},{"sp":"讲座 2","en":"And research has validated this as a genuine concern for many job applicants.","cn":"研究证实，这确实是许多求职者真实存在的顾虑。"},{"sp":"讲座 2","en":"It's a natural reaction, but it shouldn't be a reason to stay quiet.","cn":"这是一种自然反应，但不应成为保持沉默的理由。"},{"sp":"讲座 2","en":"People need to remember that they are applying for a position they have the skills and experience to excel in.","cn":"人们需要记住，他们申请的是一个自己具备胜任所需技能和经验的职位。"},{"sp":"讲座 2","en":"Discussing a disability with the potential employer may help them make reasonable workplace adjustments in their favor.","cn":"与潜在雇主讨论残疾状况，可能有助于他们做出有利于求职者的合理工作场所调整。"},{"sp":"讲座 2","en":"It's most appropriate to discuss a disability when they reply to confirm an interview.","cn":"在回复确认面试时讨论残疾状况是最合适的。"},{"sp":"讲座 2","en":"This information needn't be put up front in their cover letter or resumé, because it's probably not relevant to the position itself.","cn":"这项信息无需事先写在求职信或简历中，因为它可能与职位本身无关。"},{"sp":"讲座 2","en":"Candidates with disabilities should feel they have the power to make their own decisions around sharing this information free from prejudice.","cn":"残疾应聘者应当感到自己有能力不受偏见影响，自行决定是否分享这一信息。"},{"sp":"讲座 2","en":"If they find an organization that doesn't celebrate diversity and inclusion, it could say a lot about the company's culture.","cn":"如果他们发现某家机构不支持多元与包容，这能在很大程度上反映出该公司的文化。"},{"sp":"讲座 2","en":"Perhaps the organization isn't the right fit.","cn":"也许这家机构并不适合他们。"},{"sp":"讲座 2","en":"It's important for them to remember that they are seeking a manager and employer that's going to be supportive and continue to give them a great employment experience.","cn":"对他们来说，重要的是要记住，他们寻找的是一位给予支持并能持续为他们提供良好工作体验的管理者和雇主。"},{"sp":"讲座 2","en":"Companies sometimes offer candidates the chance to disclose disabilities on their application form, but people shouldn't feel restricted by this method or timing.","cn":"公司有时会在申请表上为应聘者提供披露残疾状况的机会，但人们不应感到受制于这种方式或时间。"},{"sp":"讲座 2","en":"People should avoid sharing the name of their disability or condition.","cn":"人们应当避免透露其残疾或病情的具体名称。"},{"sp":"讲座 2","en":"There is always the risk that the recruiter will research information that is inaccurate or irrelevant.","cn":"招聘人员始终存在去查阅不准确或无关信息的风险。"},{"sp":"讲座 2","en":"If people don't think their disability will impact their ability to perform in the advertised position, then it's entirely their entitlement to choose when, and whether to share this information.","cn":"如果人们认为自己的残疾不会影响其在招聘岗位上的履职能力，那么选择何时以及是否分享这一信息完全是他们的权利。"},{"sp":"讲座 3","en":"Smartphones distract attention and reduce learning because of their potential to offer activities more inviting than study.","cn":"智能手机可能提供比学习更具吸引力的活动，因此会分散注意力并降低学习效果。"},{"sp":"讲座 3","en":"But what about background sound alone?","cn":"但仅有背景声音会怎样呢？"},{"sp":"讲座 3","en":"A group of American researchers compared students' comprehension of verbal material when reading in the presence of background speech, instrumental music or general noise.","cn":"一组美国研究人员比较了学生在有背景语音、器乐或一般噪声的环境中阅读时对文字材料的理解情况。"},{"sp":"讲座 3","en":"General noise is neutral, such as that from the sound of an air conditioner or fan.","cn":"一般噪声是中性的，例如空调或风扇发出的声音。"},{"sp":"讲座 3","en":"Students' scores were most depressed in the presence of background speech.","cn":"在有背景语音的情况下，学生的得分下降幅度最大。"},{"sp":"讲座 3","en":"Comprehension was slightly better with the presence of music than with speech.","cn":"有音乐时的理解效果略好于有语音时。"},{"sp":"讲座 3","en":"However, when they were asked to identify melodies rather than understand text, background music interfered more.","cn":"然而，当要求学生辨认旋律而不是理解文字时，背景音乐的干扰更大。"},{"sp":"讲座 3","en":"When the background speech was in a language unfamiliar to participants, there was little if any hindrance of reading comprehension.","cn":"当背景语音使用参与者不熟悉的语言时，对阅读理解几乎没有妨碍，或者说妨碍很小。"},{"sp":"讲座 3","en":"British researchers compared the effects of background speech, vocal music, instrumental music, general background noise and silence on short-term memory.","cn":"英国研究人员比较了背景语音、声乐、器乐、一般背景噪声和安静环境对短时记忆的影响。"},{"sp":"讲座 3","en":"Background speech had the biggest negative effect; vocal music was slightly more disruptive than instrumental; and general background noise and silence were least disruptive.","cn":"背景语音的负面影响最大；声乐的干扰略大于器乐；一般背景噪声和安静环境的干扰最小。"},{"sp":"讲座 3","en":"It seems the degree of interference from background noise depends on the overlap between the processing required on the task and the processing required to screen out the background noise.","cn":"背景噪声造成的干扰程度似乎取决于任务所需的加工过程与排除背景噪声所需的加工过程之间的重叠程度。"},{"sp":"讲座 3","en":"The studies suggest that when people read and when they try to remember any verbal material, background speech will inhibit their ability.","cn":"这些研究表明，当人们阅读或试图记忆任何文字材料时，背景语音会抑制他们的能力。"},{"sp":"讲座 3","en":"Instrumental music will have at worst a slight effect.","cn":"器乐充其量只会产生轻微影响。"},{"sp":"讲座 3","en":"When students write essays, however, other research has found it is best to reduce all background noise as much as possible.","cn":"然而，其他研究发现，学生写文章时，最好尽可能减少所有背景噪声。"},{"sp":"讲座 3","en":"Not everyone reacts in the same way to distractions.","cn":"并非每个人对干扰的反应都相同。"},{"sp":"讲座 3","en":"Other studies suggest some aspects of personality may make a difference.","cn":"其他研究表明，个性中的某些方面可能会产生影响。"},{"sp":"讲座 3","en":"The researchers subjected shy quiet people and confident outgoing ones to high arousal or low arousal background music, general noise or silence while asking them to remember words.","cn":"研究人员让害羞安静的人和自信外向的人在高唤醒或低唤醒的背景音乐、一般噪声或安静环境中记忆词语。"},{"sp":"讲座 3","en":"Everyone performed best in the silent condition, but less sociable people were more negatively affected by each of the distractions.","cn":"每个人在安静环境中的表现都最好，但不太合群的人受到每种干扰的负面影响都更大。"},{"sp":"讲座 3","en":"So when children are reading and trying to incorporate new material, parents could consider allowing some background music, particularly if it's instrumental and their child is the outgoing type.","cn":"因此，当孩子阅读并试图吸收新材料时，父母可以考虑允许播放一些背景音乐，尤其是在音乐为器乐且孩子性格外向的情况下。"}]},{"id":"cet6-2022-12-1","level":"CET6","exam":"2022_12_1","year":2022,"month":12,"set":1,"type":"整卷听力","title":"2022年12月 六级第1套 · 听力真题","source":"2022年12月 CET-6 第1套 · 听力（本地原音 + 逐句原文）","audio":"assets/audio/2022/cet6-2022-12-set1.mp3","intro":"听力原文按录音篇目逐句拆分，中文译文仅供参考；音频为本地真题原音，整卷原音无法定位单句，逐句请用下方播放器。","questions":[],"lines":[{"sp":"长对话 1","en":"M: How's your dissertation going?","cn":"M: 你的学位论文写得怎么样了？"},{"sp":"长对话 1","en":"I'm proofreading my first draft and will submit it to my professor tomorrow.","cn":"我正在校对初稿，明天准备提交给教授。"},{"sp":"长对话 1","en":"W: Oh, I haven't even started writing mine yet, so I'm really worried about finishing by the end of next semester.","cn":"W: 哦，我连写都还没开始写呢，所以我真的很担心下学期末能不能写完。"},{"sp":"长对话 1","en":"M: You mean you haven't even begun yours yet?","cn":"M: 你是说你连动笔都还没动？"},{"sp":"长对话 1","en":"The final draft is due in five months.","cn":"终稿还有五个月就要交了。"},{"sp":"长对话 1","en":"W: Of course I've started it, but I can't get to the writing yet as I haven't found enough resources to use, so I'm still researching the topic.","cn":"W: 我当然已经开始了，但我还没找到足够的资料可用，所以还没法开始写，目前还在研究这个课题。"},{"sp":"长对话 1","en":"M: Maybe the problem is the way you're doing your research.","cn":"M: 也许问题出在你做研究的方式上。"},{"sp":"长对话 1","en":"I started by talking to my professor about where to look for information, and based on that, I found books in the library and a lot of reputable journal articles on the Internet.","cn":"我是先找教授聊了聊去哪里查找资料，然后根据建议在图书馆找到了书，还在网上找到了许多权威期刊的文章。"},{"sp":"长对话 1","en":"W: I've tried all that, but don't have enough to write the dissertation as my department's minimum length is 70 pages. I think the problem is that my topic isn't viable. And honestly, my professor did warn me at the beginning that I might not be able to find enough material. But I was so interested in the topic that I didn't let his advice turn me.","cn":"W: 这些我都试过了，但资料还是不够写论文，因为我们系要求的最低篇幅是70页。我觉得问题在于我的选题不可行。说实话，我教授刚开始确实警告过我可能找不到足够的材料，但当时我对这个课题太感兴趣了，所以没听他的劝告。"},{"sp":"长对话 1","en":"M: Well, I suggest you find a new topic.","cn":"M: 嗯，我建议你换个新选题。"},{"sp":"长对话 1","en":"After all, our professors are here to guide us, so it's best to listen to them.","cn":"毕竟教授是来指导我们的，最好还是听他们的建议。"},{"sp":"长对话 1","en":"W: In retrospect, I wish I had listened to him, but I didn't.","cn":"W: 回想起来，我真希望当时听了他的话，但我没听。"},{"sp":"长对话 1","en":"And now I don't want to give up my topic as I've already invested so much time and energy.","cn":"而且现在我已经投入了这么多时间和精力，不想放弃我的选题。"},{"sp":"长对话 1","en":"M: If you're committed to your current topic, maybe you could make some adjustments rather than abandon it completely.","cn":"M: 如果你坚持用现在的选题，也许你可以做些调整，而不是彻底放弃它。"},{"sp":"长对话 1","en":"What is your topic?","cn":"你的课题是什么？"},{"sp":"长对话 1","en":"W: It's \"Depictions of Femininity in Folklore from the South of the Country\".","cn":"W: 是《国内南方民间传说中对女性形象的刻画》。"},{"sp":"长对话 1","en":"M: That's pretty narrow.","cn":"M: 那范围确实挺窄的。"},{"sp":"长对话 1","en":"You could find more material if you made the topic broader, maybe by including other kinds of depictions.","cn":"如果你把选题范围放宽一点，比如把其他类型的刻画也包含进来，应该能找到更多资料。"},{"sp":"长对话 1","en":"W: Broadening the topic is a great idea, I'll start by including folklore from other regions of the country.","cn":"W: 放宽选题范围是个好主意，我就从纳入国内其他地区的民间传说开始吧。"},{"sp":"长对话 2","en":"W: Today, on Book Talk, we are lucky enough to host John Robbins and discuss his new book, Why Americans Are Fat and How We Can Lose Weight.","cn":"W: 今天，在《图书访谈》节目中，我们非常荣幸地邀请到约翰·罗宾斯，和我们一起讨论他的新书《为什么美国人肥胖以及我们如何减肥》。"},{"sp":"长对话 2","en":"John isn't just a respected writer; he's also one of the rare celebrity authors writing about science today.","cn":"约翰不仅是一位受人尊敬的作家，也是如今少数几位撰写科学类书籍的知名作家之一。"},{"sp":"长对话 2","en":"M: Thanks for having me, Rebecca, but I'm hardly a celebrity.","cn":"M: 谢谢你的邀请，丽贝卡，不过我实在算不上什么名人。"},{"sp":"长对话 2","en":"W: That's very modest of you to say, considering that your four books have sold a total of seven million copies worldwide, and they've been translated into 12 different languages.","cn":"W: 考虑到你的四本书在全球总共售出了七百万册，而且被翻译成了十二种不同的语言，你这么说可真谦虚。"},{"sp":"长对话 2","en":"What makes people so fascinated with your work?","cn":"是什么让人们对你的作品如此着迷呢？"},{"sp":"长对话 2","en":"M: Well, people read my books because more than 60% of Americans are overweight, or obese.","cn":"M: 嗯，人们读我的书，是因为超过百分之六十的美国人超重或肥胖。"},{"sp":"长对话 2","en":"And other countries are facing similar problems.","cn":"其他国家也面临着类似的问题。"},{"sp":"长对话 2","en":"Basically, we all want to know how to fix things.","cn":"基本上，我们都想知道该如何解决这些问题。"},{"sp":"长对话 2","en":"W: We certainly do.","cn":"W: 我们当然想知道。"},{"sp":"长对话 2","en":"I've read your new book, and it's fabulous, especially when it comes to the way you make difficult science easy for laymen to understand.","cn":"我读过你的新书，觉得非常精彩，尤其是你把艰深的科学知识讲得通俗易懂这一点。"},{"sp":"长对话 2","en":"That's no small achievement.","cn":"这可不是一件容易做到的事。"},{"sp":"长对话 2","en":"M: I'm glad to hear you find my work accessible, because I was worried when I wrote it that discussing the science might make the book more suited for a specialist audience.","cn":"M: 听到你觉得我的作品通俗易懂，我很高兴，因为写这本书时，我担心讨论科学内容会让它更适合专业读者阅读。"},{"sp":"长对话 2","en":"My last book was written primarily for the medical community.","cn":"我的上一本书主要是写给医学界人士看的。"},{"sp":"长对话 2","en":"But this time, I want to help ordinary people take control of their weight.","cn":"但这一次，我想帮助普通人掌控自己的体重。"},{"sp":"长对话 2","en":"W: And how do you suggest they do that?","cn":"W: 那你建议他们怎么做呢？"},{"sp":"长对话 2","en":"Can you give us the basics of your advice for people who want to lose weight?","cn":"能不能简单介绍一下你对想减肥的人所提出的建议？"},{"sp":"长对话 2","en":"M: Briefly, I argue that every person needs to consider their metabolism and eat what suits their body's needs.","cn":"M: 简单地说，我认为每个人都需要考虑自己的新陈代谢，吃适合自己身体需要的食物。"},{"sp":"长对话 2","en":"I don't advocate one single diet.","cn":"我不主张所有人都采用同一种饮食方式。"},{"sp":"长对话 2","en":"Some people should eat more carbohydrates than others.","cn":"有些人应该比其他人摄入更多碳水化合物。"},{"sp":"长对话 2","en":"And different people need different amounts of protein and fat.","cn":"而且，不同的人对蛋白质和脂肪的需求量也各不相同。"},{"sp":"长对话 2","en":"W: But you do have some recommendations for everyone, including eating ten servings of vegetables and three of fruit a day.","cn":"W: 不过，你确实也给所有人提出了一些建议，包括每天吃十份蔬菜和三份水果。"},{"sp":"长对话 2","en":"We'll talk about those recommendations next, but now we need to take a short break for a message from our sponsor.","cn":"接下来我们会谈谈这些建议，不过现在我们要暂时休息一下，听一段赞助商提供的信息。"},{"sp":"听力篇章 1","en":"Stress is often depicted as negative, but research shows that moderate amounts of it can be beneficial for your brain and your body.","cn":"压力通常被描绘成负面的事物，但研究表明，适度的压力有益于大脑和身体。"},{"sp":"听力篇章 1","en":"First, the benefits for the brain.","cn":"首先来看压力对大脑的益处。"},{"sp":"听力篇章 1","en":"Studies have shown that short periods of stress can actually bolster cognitive functioning.","cn":"研究表明，短时间的压力实际上能够增强认知功能。"},{"sp":"听力篇章 1","en":"Researchers discovered that placing rats in a stressful situation for just a few hours doubled the growth of new brain cells.","cn":"研究人员发现，让大鼠处于有压力的环境中仅几个小时，就能使新脑细胞的增长速度提高一倍。"},{"sp":"听力篇章 1","en":"The rats also did better on a memory test later on.","cn":"之后，这些大鼠在记忆测试中的表现也更好。"},{"sp":"听力篇章 1","en":"Scientists think the same thing happens in humans.","cn":"科学家认为，人类身上也会发生同样的情况。"},{"sp":"听力篇章 1","en":"But how does stress improve memory?","cn":"但是，压力是如何改善记忆力的呢？"},{"sp":"听力篇章 1","en":"It's simple.","cn":"原因很简单。"},{"sp":"听力篇章 1","en":"When your brain cells multiply, your memory can improve.","cn":"当你的脑细胞增多时，你的记忆力可能会得到改善。"},{"sp":"听力篇章 1","en":"Viewed from a biological perspective, this makes sense, because animals that are better at remembering dangerous situations can avoid them in the future.","cn":"从生物学角度来看，这是合理的，因为更善于记住危险情境的动物能够在未来避开这些情境。"},{"sp":"听力篇章 1","en":"If an animal encounters a predator and escapes, for example, it's important to remember where and when that encounter happened.","cn":"例如，如果一只动物遇到捕食者并成功逃脱，那么记住这次遭遇发生的地点和时间就十分重要。"},{"sp":"听力篇章 1","en":"Experts assert that the same principle applies to humans.","cn":"专家断言，同样的原理也适用于人类。"},{"sp":"听力篇章 1","en":"Now, let's turn to how stress benefits the body.","cn":"现在，我们来看看压力如何有益于身体。"},{"sp":"听力篇章 1","en":"This may come as a surprise to laymen.","cn":"这对普通人来说可能令人意外。"},{"sp":"听力篇章 1","en":"But experts say that stress can keep you from getting sick.","cn":"但专家表示，压力可以使你不易生病。"},{"sp":"听力篇章 1","en":"Scientists concede that chronic stress can make you more prone to illness.","cn":"科学家承认，长期压力会使人更容易患病。"},{"sp":"听力篇章 1","en":"But research shows that short periods of stress can actually provide some protection against getting sick, because it increases your immune functioning.","cn":"但研究表明，短时间的压力实际上能够提供一定的防病保护，因为它会增强免疫功能。"},{"sp":"听力篇章 1","en":"One study shows that rats that experienced brief stress had a surge of immune cell response, which makes the immune system better prepared to fight illness.","cn":"一项研究显示，经历短暂压力的大鼠，其免疫细胞反应会激增，从而使免疫系统更好地准备对抗疾病。"},{"sp":"听力篇章 1","en":"For humans, there's even evidence that experiencing stress before getting vaccinated could help make vaccines more effective.","cn":"对于人类，甚至有证据表明，在接种疫苗前经历压力可能有助于提高疫苗的有效性。"},{"sp":"听力篇章 2","en":"For many managers and people who work in leadership positions, dealing with emails is a dilemma.","cn":"对于许多管理者和担任领导职务的人来说，处理电子邮件是一个两难困境。"},{"sp":"听力篇章 2","en":"It's likely the \"unpredictable, uncontrollable and ongoing nature of day-to-day email in terms of volume, importance and urgency\" contributes to their levels of anxiety and to diminished leadership skills.","cn":"日常电子邮件在数量、重要性和紧迫性方面“不可预测、不可控制且持续不断”的特性，很可能会加剧他们的焦虑程度并削弱其领导能力。"},{"sp":"听力篇章 2","en":"That's because it's not unusual for many leaders to prioritize email management over people management.","cn":"这是因为许多领导者将电子邮件管理置于人员管理之上并不罕见。"},{"sp":"听力篇章 2","en":"An obsession with managing their inbox prevents them from dealing with their employees.","cn":"对管理收件箱的痴迷使他们无法顾及员工。"},{"sp":"听力篇章 2","en":"As a result, they ignore the issues that might only be mild problems at first, until unfortunately, they inevitably transform into a major problem or crisis by virtue of neglect.","cn":"结果，他们忽视了最初可能只是轻微的问题，直到不幸的是，由于疏忽，这些问题不可避免地演变成了重大问题或危机。"},{"sp":"听力篇章 2","en":"As leaders, they are expected to motivate and inspire their team in pursuit of longer-term strategic goals and also, less ambitiously but more practically, to monitor their daily output, to set clear expectations and to give regular feedback.","cn":"作为领导者，人们期望他们能够激励和鼓舞团队去追求更长期的战略目标；同时，虽然抱负没那么远大但更为实际的是，监督团队的日常工作产出、设定明确的期望并提供定期反馈。"},{"sp":"听力篇章 2","en":"When presented with a choice between the appeal of their inbox and other more important activities, many sacrifice the latter.","cn":"当面临收件箱的吸引力与其他更为重要的活动之间的选择时，许多人牺牲了后者。"},{"sp":"听力篇章 2","en":"Daily email demands have a negative impact on their goal progress.","cn":"日常电子邮件需求对他们的目标推进产生了负面影响。"},{"sp":"听力篇章 2","en":"This is because leaders must divert resources from other tasks to check, filter and respond to emails.","cn":"这是因为领导者必须从其他任务中抽调资源来检查、过滤和回复电子邮件。"},{"sp":"听力篇章 2","en":"The solution is cultivating self-control which is like a muscle—it can be strengthened or improved over time through exercise.","cn":"解决方案是培养自控力，自控力就像肌肉一样——随着时间的推移，可以通过锻炼得到加强或改善。"},{"sp":"听力篇章 2","en":"Some suggestions include making space in your diary for the only periods during which you'll be checking emails, setting a timer for yourself so you don't become distracted by your inbox for too long, turning off email alerts so you're not interrupted by them.","cn":"一些建议包括：在日程表中预留出专门用于检查电子邮件的时间段；给自己设置定时器，以免长时间被收件箱分散注意力；关闭电子邮件提醒，以免被其打扰。"},{"sp":"讲座 1","en":"In last week's lecture, we talked about the problems caused by poor eating habits, focusing on how medical professionals are trying to solve these problems.","cn":"在上周的讲座中，我们讨论了不良饮食习惯所造成的问题，重点关注医疗专业人员如何努力解决这些问题。"},{"sp":"讲座 1","en":"Today, we'll continue with the topic, but focus on research from a different field—marketing.","cn":"今天，我们将继续这一主题，但把重点放在另一个领域的研究上——市场营销。"},{"sp":"讲座 1","en":"Now, what can marketing tell us about improving nutrition?","cn":"那么，关于改善营养状况，市场营销能告诉我们什么呢？"},{"sp":"讲座 1","en":"Well, a team of marketing professors has studied the importance of the visual aspect of food and how that influences food choices.","cn":"一组市场营销学教授研究了食物视觉形象的重要性，以及这种视觉形象如何影响人们对食物的选择。"},{"sp":"讲座 1","en":"Those marketing experts assert that the impact of the appearance of food is greater than we might presume, and might hold the key to encouraging better eating.","cn":"这些市场营销专家断言，食物外观的影响比我们可能设想的更大，而且可能是鼓励人们改善饮食的关键。"},{"sp":"讲座 1","en":"So how important is the appearance of food?","cn":"那么，食物的外观究竟有多重要呢？"},{"sp":"讲座 1","en":"Research shows that just seeing an appealing photograph of a hamburger in an advertisement, for example, can cause individuals to imagine the taste or smell of that hamburger.","cn":"研究表明，例如，仅仅看到广告中一张诱人的汉堡包照片，就可能使人们联想到汉堡包的味道或气味。"},{"sp":"讲座 1","en":"This can make them more likely to purchase and consume it.","cn":"这会让他们更有可能购买并食用它。"},{"sp":"讲座 1","en":"Of course, that's the point of advertisements.","cn":"当然，这正是广告的目的。"},{"sp":"讲座 1","en":"So isn't that a good thing?","cn":"那么，这难道不是一件好事吗？"},{"sp":"讲座 1","en":"Well, the marketing professors argue that this is actually a problem, because the combination of pleasing aesthetics of and easy access to unhealthy foods, such as hamburgers and pizza, may be contributing to a worldwide health crisis.","cn":"市场营销学教授们认为，实际上这恰恰是一个问题，因为汉堡包和披萨等不健康食品令人愉悦的外观与其易于获得相结合，可能正在助长一场全球性的健康危机。"},{"sp":"讲座 1","en":"In fact, statistics show that 39% of all adults in the world weigh too much and another 13% are obese.","cn":"事实上，统计数据显示，全世界有39%的成年人超重，另有13%的人肥胖。"},{"sp":"讲座 1","en":"Now, as we discussed last time, medical professionals have tried to fight the obesity epidemic by focusing on the nutrients found in different foods, emphasizing things like carbohydrate, fat, sugar and calorie content.","cn":"正如我们上次讨论的那样，医疗专业人员曾试图通过关注不同食物所含的营养成分来应对肥胖症流行，强调碳水化合物、脂肪、糖和卡路里含量等因素。"},{"sp":"讲座 1","en":"But they've had limited success.","cn":"但他们取得的成效有限。"},{"sp":"讲座 1","en":"The marketing professors believe that the real solution to obesity is making food look appealing and focusing on the pleasure of both looking at and eating that food.","cn":"市场营销学教授们认为，解决肥胖问题的真正办法，是让食物看起来更有吸引力，并关注人们观看和食用这些食物时所获得的愉悦感。"},{"sp":"讲座 1","en":"That pleasure can be used as a tool to promote healthy food choices.","cn":"这种愉悦感可以被用作促进健康食品选择的工具。"},{"sp":"讲座 1","en":"In fact, the research done by the team showed that associating healthy food with pleasant images, experiences and emotions led to greater interest in purchasing or eating it.","cn":"事实上，该团队开展的研究表明，将健康食品与令人愉悦的图像、体验和情感联系起来，会使人们对购买或食用这种食品产生更大的兴趣。"},{"sp":"讲座 1","en":"\"This is a better strategy,\" they claim, than reminding consumers that a certain food is good for them.","cn":"他们声称，与提醒消费者某种食物对身体有益相比，“这是一种更好的策略”。"},{"sp":"讲座 1","en":"But are they right?","cn":"但他们说得对吗？"},{"sp":"讲座 1","en":"Well, the researchers cited a marketing campaign designed to reverse the sales decline of carrots.","cn":"研究人员举例介绍了一项旨在扭转胡萝卜销量下滑的市场营销活动。"},{"sp":"讲座 1","en":"The campaign didn't emphasize the carrots' healthy qualities, but embraced their beauty and the pleasure derived from eating them.","cn":"该活动没有强调胡萝卜的健康特性，而是展现了它们的美感以及食用它们所带来的愉悦感。"},{"sp":"讲座 1","en":"For example, the ads focused on the bright, beautiful orange color and crisp texture of the carrots.","cn":"例如，广告重点突出胡萝卜明亮美丽的橙色和爽脆的口感。"},{"sp":"讲座 1","en":"The campaign led to an impressive increase in product sales of more than 10%.","cn":"这项活动使产品销量大幅增加了10%以上。"},{"sp":"讲座 1","en":"The researchers believe that other companies could bolster sales of healthy foods with similar ads, depicting their products as attractive and a source of pleasure.","cn":"研究人员认为，其他公司也可以通过类似的广告来促进健康食品的销售，将其产品描绘成具有吸引力且能带来愉悦的食品。"},{"sp":"讲座 2","en":"The household cleaning products industry really began to take off in the 1950s.","cn":"家居清洁用品行业真正开始蓬勃发展是在20世纪50年代。"},{"sp":"讲座 2","en":"Prior to that, resourceful housewives who had grown up in a less prosperous era relied on substances that they used in their kitchens such as vinegar used to clean windows.","cn":"在此之前，那些成长于经济不太繁荣时代、富有创造力的家庭主妇，依靠厨房里使用的物质，例如用醋清洁窗户。"},{"sp":"讲座 2","en":"Today, the household cleaning products industry is worth billions of dollars a year and is dominated by large global companies.","cn":"如今，家居清洁用品行业每年的产值达数十亿美元，并由大型跨国公司主导。"},{"sp":"讲座 2","en":"In recent years, however, many countries have witnessed a surge in the number of small businesses and companies offering more environment-friendly cleaning products, and they're doing good business too.","cn":"然而，近年来，许多国家都见证了提供更环保清洁产品的小型企业和公司的数量激增，而且它们的生意也做得很好。"},{"sp":"讲座 2","en":"One reason for this is that consumers are becoming more aware of environment and sustainability issues.","cn":"其中一个原因是消费者越来越意识到环境和可持续性问题。"},{"sp":"讲座 2","en":"They also want to make their home a safe place, free from toxic chemicals.","cn":"他们还希望把家变成一个没有有毒化学物质的安全场所。"},{"sp":"讲座 2","en":"The third reason is people's awareness of and knowledge about technology has never been greater.","cn":"第三个原因是，人们对技术的认识和了解从未像现在这样深入。"},{"sp":"讲座 2","en":"In the past, people might have been skeptical of a new product claimed to be able to achieve amazing cleaning results, but they now have faith in technology's ability to do what was once thought impossible.","cn":"过去，人们可能会对一种声称能够取得惊人清洁效果的新产品持怀疑态度，但如今，他们相信技术有能力做到那些曾经被认为不可能的事情。"},{"sp":"讲座 2","en":"There is perhaps no better example of this than a patented cloth sold by one company, which remarkably uses only water rather than traditional cleaning products. The company claims its cloth lifts, traps and removes dirt and bacteria. And considering that people don't see these products in shops, or advertised on TV or in the press, it has been a pretty steep rise.","cn":"或许没有什么比某家公司销售的一种获得专利的抹布更能说明这一点了。这种抹布非常特别，只使用水，而不是传统的清洁产品。该公司声称，这种抹布能够提起、吸附并清除污垢和细菌。考虑到人们既不会在商店里看到这些产品，也不会在电视、报刊或杂志上看到它们的广告，它们的增长速度着实非常快。"},{"sp":"讲座 2","en":"Many of the people behind these companies began testing the viability of their products by selling them at local markets.","cn":"这些公司背后的许多人都是通过在当地市场销售产品，开始测试产品是否具有可行性的。"},{"sp":"讲座 2","en":"Then, in many cases, customers are doing the marketing for these products by leaving threads of comments on social media, praising their virtues.","cn":"随后，在许多情况下，顾客通过在社交媒体上留下大量评论、称赞这些产品的优点，为它们进行营销。"},{"sp":"讲座 2","en":"There are also TV shows and books dedicated to maintaining home tidiness and cleanliness and the benefits of having a clean home.","cn":"此外，还有专门介绍保持家庭整洁、清洁以及拥有一个干净家庭的益处的电视节目和书籍。"},{"sp":"讲座 2","en":"Having a safe and clean home might be one thing people feel they can control in an increasingly out-of-control world.","cn":"在一个越来越失控的世界里，拥有一个安全而干净的家，可能是人们觉得自己能够掌控的一件事。"},{"sp":"讲座 2","en":"And there are social media celebrities.","cn":"而且，还有社交媒体名人。"},{"sp":"讲座 2","en":"One woman in Britain has become a social media sensation with more than two million followers for her cleaning tips page.","cn":"英国有一名女性凭借她的清洁技巧页面成为社交媒体红人，粉丝数量超过两百万。"},{"sp":"讲座 3","en":"Throwing spare change into a fountain is a time-honored ritual: throw a penny into the water, and your wish might come true.","cn":"把多余的零钱扔进喷泉是一种历史悠久的仪式：把一枚硬币扔进水里，你的愿望就可能实现。"},{"sp":"讲座 3","en":"But all that money has to go somewhere.","cn":"但所有这些钱都必须有去处。"},{"sp":"讲座 3","en":"Otherwise, the growing piles of pennies, quarters and euros could clog up the fountains' works.","cn":"否则，越积越多的便士、25美分硬币和欧元硬币可能会堵塞喷泉的内部装置。"},{"sp":"讲座 3","en":"Today, I'm going to talk about where all the coins go.","cn":"今天，我要讲讲这些硬币最终都去了哪里。"},{"sp":"讲座 3","en":"Well, the coins collected can go to all sorts of different places—from fountain maintenance to charity or public service.","cn":"收集到的硬币可以被用于各种不同的地方，例如喷泉维护、慈善事业或公共服务。"},{"sp":"讲座 3","en":"In New York City, for example, coins collected from fountains in public parks often go towards the fountains' maintenance itself, though entrepreneurs who don't mind getting their hands wet often get to it first.","cn":"以纽约市为例，从公共公园喷泉中收集的硬币通常会用于喷泉本身的维护，不过那些不介意把手弄湿的投机者往往会先下手。"},{"sp":"讲座 3","en":"There are over 50 beautiful decorative display fountains in New York City parks.","cn":"纽约市的公园里有50多座漂亮的装饰性展示喷泉。"},{"sp":"讲座 3","en":"They are cleaned by the parks' staff every few weeks.","cn":"公园工作人员每隔几周会对它们进行清洁。"},{"sp":"讲座 3","en":"But most of the coins have already been removed by entrepreneurial New Yorkers and there is not a significant amount left to be collected.","cn":"但大多数硬币早已被纽约的投机者取走，剩下可收集的数量并不多。"},{"sp":"讲座 3","en":"Other cities, though, can pull in a much more serious haul.","cn":"不过，其他城市的喷泉可能会带来多得多的收入。"},{"sp":"讲座 3","en":"Take for example, Rome's famous Trevi fountain: for hundreds of years, visitors have thrown coins over their shoulder into the fountain to ensure that they will return.","cn":"以罗马著名的特莱维喷泉为例：数百年来，游客一直将硬币从肩后抛入喷泉，以确保自己将来还会回来。"},{"sp":"讲座 3","en":"So many tourists toss in coins that Roman officials have the fountain cleaned every night, reportedly getting as much as $4,000 in loose change from around the world each day.","cn":"如此多的游客往里投硬币，以至于罗马官员每天晚上都会安排清理喷泉，据报道，每天能从中获得多达4,000美元的世界各地零钱。"},{"sp":"讲座 3","en":"Most of the money collected each night goes towards running a supermarket for the needy.","cn":"每晚收集到的大部分钱都用于运营一家为贫困者服务的超市。"},{"sp":"讲座 3","en":"And collecting that cash is serious business.","cn":"而收集这些现金是一项严肃的工作。"},{"sp":"讲座 3","en":"Roman officials have been known to be tough on anyone caught skimming coins from the fountain.","cn":"众所周知，罗马官员会严厉对待任何被发现从喷泉中偷取硬币的人。"},{"sp":"讲座 3","en":"In one case in 2005, police arrested four fountain cleaners after they were spotted slipping coins into their own pockets after collecting them.","cn":"2005年就发生过一起案件：警方发现四名喷泉清洁工在收集硬币后把硬币偷偷塞进自己的口袋，随后将他们逮捕。"},{"sp":"讲座 3","en":"Authorities finally caught one notorious thief named Thomas Morgan and banned him from the fountain after he fished out thousands of dollars in change over 34 years using a magnetic stick.","cn":"最终，当局抓住了一名臭名昭著的小偷Thomas Morgan，并禁止他进入喷泉区域；在34年间，他曾用一根磁力棒从喷泉中捞出数千美元的零钱。"},{"sp":"讲座 3","en":"For the most part, money collected from privately-owned fountains in the United States also goes to charity.","cn":"在美国，从私人拥有的喷泉中收集到的钱大多也会捐给慈善机构。"},{"sp":"讲座 3","en":"The fountain in New York City's Bryant Park is owned and operated by a not-for-profit corporation, which puts the cash collected by cleaners towards the fountain's own maintenance.","cn":"纽约市布莱恩特公园的喷泉由一家非营利公司所有并运营，清洁工收集到的现金会被用于喷泉本身的维护。"},{"sp":"讲座 3","en":"Tens of thousands of dollars in coins removed from wishing wells, fountains and ponds in Florida's Walt Disney World are donated each year to support foster children living in the state.","cn":"佛罗里达州华特迪士尼世界的许愿井、喷泉和池塘中每年取出的数万美元硬币，都会被捐出，用于帮助生活在该州的寄养儿童。"},{"sp":"讲座 3","en":"Whether or not your wish comes true after tossing a coin into a fountain, you can rest assured knowing that the change is likely going to someone who needs it.","cn":"无论你把硬币扔进喷泉后愿望是否实现，你都可以放心，因为这些零钱很可能会流向需要帮助的人。"}]},{"id":"cet6-2022-12-2","level":"CET6","exam":"2022_12_2","year":2022,"month":12,"set":2,"type":"整卷听力","title":"2022年12月 六级第2套 · 听力真题","source":"2022年12月 CET-6 第2套 · 听力（本地原音 + 逐句原文）","audio":"assets/audio/2022/cet6-2022-12-set2.mp3","intro":"听力原文按录音篇目逐句拆分，中文译文仅供参考；音频为本地真题原音，整卷原音无法定位单句，逐句请用下方播放器。","questions":[],"lines":[{"sp":"长对话 1","en":"M: Welcome to the Book Club.","cn":"M: 欢迎收听《读书俱乐部》。"},{"sp":"长对话 1","en":"Today's guest is Susan Lane, the author of a new book on personal finances that has already sold half a million copies.","cn":"今天的嘉宾是苏珊·莱恩，她是一本关于个人理财的新书作者，这本书已经卖出了五十万册。"},{"sp":"长对话 1","en":"Hi, Susan, your book is extremely successful.","cn":"你好，苏珊，你的书取得了巨大的成功。"},{"sp":"长对话 1","en":"Why do you think that is?","cn":"你觉得这是为什么？"},{"sp":"长对话 1","en":"W: I think that's because of my message, which is making happiness a priority over money.","cn":"W: 我认为这是因为我传达的理念，那就是把幸福置于金钱之上。"},{"sp":"长对话 1","en":"So many of us in my generation have spent decades trying to earn more money, just to consume more, but it made us more miserable.","cn":"我们这一代有太多人花了几十年努力赚更多的钱，只是为了消费更多，但这反而让我们更加痛苦。"},{"sp":"长对话 1","en":"M: You yourself were once caught in that cycle, working for two decades as an executive and earning a high salary, but still accumulating debt.","cn":"M: 你自己也曾陷入过那种循环，做了二十年的高管，拿着很高的薪水，却还是不断积累债务。"},{"sp":"长对话 1","en":"W: I most certainly was.","cn":"W: 的确如此。"},{"sp":"长对话 1","en":"I earned millions, but by the time I quit my job four years ago to become a writer, I owed over $30,000.","cn":"我赚了几百万美元，但四年前辞职成为作家时，我还欠着三万多美元。"},{"sp":"长对话 1","en":"M: So how did you escape that pattern?","cn":"M: 那么，你是如何摆脱这种模式的？"},{"sp":"长对话 1","en":"And what would you advise other people to do?","cn":"你又会建议其他人怎么做？"},{"sp":"长对话 1","en":"W: The first change is in what we value.","cn":"W: 首先要改变的是我们的价值观。"},{"sp":"长对话 1","en":"We need to emphasize things that actually make us happy, like relationships, the environment or even our hobbies.","cn":"我们需要重视那些真正能让我们快乐的事情，比如人际关系、环境，甚至是我们的爱好。"},{"sp":"长对话 1","en":"Once we make the right things our priority, our goals will change and so will our financial behavior.","cn":"一旦我们把真正重要的事情放在首位，我们的目标就会改变，财务行为也会随之改变。"},{"sp":"长对话 1","en":"M: How does that translate into practical action?","cn":"M: 这要如何落实到实际行动上？"},{"sp":"长对话 1","en":"Can you give our audience examples of what you are talking about on an everyday basis?","cn":"你能不能举些例子，说明你所说的这些在日常生活中具体是怎样的？"},{"sp":"长对话 1","en":"W: The major areas for action are usually housing, food and transportation.","cn":"W: 通常需要采取行动的主要方面是住房、饮食和交通。"},{"sp":"长对话 1","en":"So people might share a home with friends instead of living on their own, bring lunch from home instead of going to restaurants, and use public transport instead of owning a car.","cn":"比如，人们可以和朋友合住，而不是独自居住；从家里带午餐，而不是去餐馆吃饭；乘坐公共交通，而不是自己买车。"},{"sp":"长对话 1","en":"M: Those sound like major sacrifices, I could never share my home, I need my own space.","cn":"M: 听起来这都是很大的牺牲，我绝不可能和别人合住，我需要自己的空间。"},{"sp":"长对话 1","en":"W: But they aren't sacrifices.","cn":"W: 但这并不是牺牲。"},{"sp":"长对话 1","en":"When people change their values, their desires change.","cn":"当人们改变了自己的价值观，欲望也会随之改变。"},{"sp":"长对话 1","en":"So in the example of housing, if we value relationships, sharing a home isn't depriving ourselves of space, but giving us an opportunity to spend more time with our loved ones.","cn":"就住房这个例子来说，如果我们重视人际关系，那么合住并不是剥夺自己的空间，而是给我们更多时间与所爱的人相处的机会。"},{"sp":"长对话 1","en":"M: Indeed it is.","cn":"M: 的确如此。"},{"sp":"长对话 2","en":"W: Thank you for inviting me to the gallery, Christopher.","cn":"W: 谢谢你邀请我来画廊，克里斯托弗。"},{"sp":"长对话 2","en":"I haven't visited here since your predecessor's retirement function.","cn":"自从你前任的退休活动以来，我就没来过这里。"},{"sp":"长对话 2","en":"M: Would you like to see the newest additions to our collection first, Catherine?","cn":"M: 凯瑟琳，你想先看看我们收藏中最新增加的作品吗？"},{"sp":"长对话 2","en":"W: Are those the landscapes by Danielle Gregory?","cn":"W: 那些是丹妮尔·格雷戈里的风景画吗？"},{"sp":"长对话 2","en":"I absolutely adore her work.","cn":"我特别喜欢她的作品。"},{"sp":"长对话 2","en":"M: This first piece was a gift to the gallery from the artist herself, and it's quite exquisite.","cn":"M: 这第一幅作品是艺术家本人赠送给画廊的，确实非常精美。"},{"sp":"长对话 2","en":"W: I love how she depicts the barren landscape.","cn":"W: 我喜欢她描绘这片荒芜景观的方式。"},{"sp":"长对话 2","en":"The colors complement each other perfectly.","cn":"这些色彩搭配得恰到好处。"},{"sp":"长对话 2","en":"M: You can sense the desolation in the picture.","cn":"M: 你能从画中感受到那种荒凉。"},{"sp":"长对话 2","en":"This piece was inspired by Gregory's recent trek in the Gobi Desert.","cn":"这幅作品的灵感来自格雷戈里最近在戈壁沙漠的徒步旅行。"},{"sp":"长对话 2","en":"W: And how did you obtain her other piece over here?","cn":"W: 那你们旁边这幅作品是怎么得到的？"},{"sp":"长对话 2","en":"M: It was purchased at auction by an anonymous collector who lent it to the gallery for display.","cn":"M: 这幅画是一位匿名收藏家在拍卖会上买下的，后来借给画廊展出。"},{"sp":"长对话 2","en":"This composition is one of her most acclaimed paintings.","cn":"这幅构图是她最受好评的画作之一。"},{"sp":"长对话 2","en":"W: It must have cost that collector a small fortune to purchase this.","cn":"W: 那位收藏家买下这幅画一定花了一大笔钱。"},{"sp":"长对话 2","en":"M: Obviously, I can't disclose the exact amount he paid, but it was substantial.","cn":"M: 我当然不能透露他支付的确切金额，但那是一笔相当可观的钱。"},{"sp":"长对话 2","en":"W: There's so much detail in this painting.","cn":"W: 这幅画的细节真丰富。"},{"sp":"长对话 2","en":"I feel like I can really immerse myself in the scene.","cn":"我感觉自己真的能沉浸在这个场景中。"},{"sp":"长对话 2","en":"I particularly like the symmetry created by the reflection of the mountain in the lake.","cn":"我尤其喜欢湖面倒映山峰所形成的对称感。"},{"sp":"长对话 2","en":"M: This particular piece was the one that was nominated for a Gateway Award.","cn":"M: 这幅作品就是那幅获得Gateway奖提名的画。"},{"sp":"长对话 2","en":"I was lucky enough to attend the award ceremony as Gregory's guest.","cn":"我很幸运，曾作为格雷戈里的客人参加颁奖典礼。"},{"sp":"长对话 2","en":"W: So you know her personally.","cn":"W: 所以你认识她本人。"},{"sp":"长对话 2","en":"I assume she's an eccentric artist.","cn":"她应该是个古怪的艺术家吧。"},{"sp":"长对话 2","en":"M: Quite the opposite.","cn":"M: 恰恰相反。"},{"sp":"长对话 2","en":"In fact, she's not at all eccentric.","cn":"事实上，她一点也不古怪。"},{"sp":"长对话 2","en":"I would say she's one of the most easygoing and intelligent people I know.","cn":"我会说她是我认识的最随和、最聪明的人之一。"},{"sp":"长对话 2","en":"W: I'd love to be able to meet her.","cn":"W: 我很想有机会见见她。"},{"sp":"长对话 2","en":"There are so many questions I'd like to ask.","cn":"我有好多问题想问她。"},{"sp":"长对话 2","en":"M: What a coincidence!","cn":"M: 真巧！"},{"sp":"长对话 2","en":"I'm meeting her for dinner tonight.","cn":"我今晚要和她一起吃晚饭。"},{"sp":"长对话 2","en":"Would you like to come along?","cn":"你愿意一起来吗？"},{"sp":"长对话 2","en":"W: I'd love to.","cn":"W: 我很乐意。"},{"sp":"长对话 2","en":"Thank you.","cn":"谢谢。"},{"sp":"听力篇章 1","en":"Forgiveness is the release of resentment or anger.","cn":"宽恕是放下怨恨或愤怒。"},{"sp":"听力篇章 1","en":"Forgiveness doesn't mean reconciliation.","cn":"宽恕并不意味着和解。"},{"sp":"听力篇章 1","en":"We don't have to return to the same relationship, nor do we have to accept the same harmful behaviors from an offender.","cn":"我们不必回到原来的关系中，也不必再接受冒犯者同样的有害行为。"},{"sp":"听力篇章 1","en":"Forgiveness is vitally important for the mental health of certain victims.","cn":"对于某些受害者而言，宽恕对心理健康至关重要。"},{"sp":"听力篇章 1","en":"It propels people forward rather than keeping them emotionally engaged in an injustice or trauma.","cn":"它推动人们继续前进，而不是让他们在情感上持续纠缠于某种不公或创伤之中。"},{"sp":"听力篇章 1","en":"Carrying the hurt or anger of an offense leads the body to release stress chemicals.","cn":"带着遭受冒犯后的伤痛或愤怒生活，会导致身体释放应激化学物质。"},{"sp":"听力篇章 1","en":"Eliminating the perpetual flow of those chemicals may also explain why forgiveness provides physical health benefits.","cn":"消除这些化学物质的持续释放，也可能解释了宽恕为何能带来身体健康方面的益处。"},{"sp":"听力篇章 1","en":"There are scenarios in which forgiveness is not the best course.","cn":"在某些情况下，宽恕并不是最佳选择。"},{"sp":"听力篇章 1","en":"Sometimes the victim becomes more empowered when they give themselves permission not to forgive.","cn":"有时，当受害者允许自己不去宽恕时，他们反而会获得更强的力量。"},{"sp":"听力篇章 1","en":"Forgiveness can be challenging.","cn":"宽恕可能是一件困难的事。"},{"sp":"听力篇章 1","en":"This is especially true when the offending party offers an insincere apology, or maybe they haven't offered anything at all.","cn":"当冒犯者给出虚假的道歉，或者根本没有道歉时，尤其如此。"},{"sp":"听力篇章 1","en":"However, it's often the healthiest path forward.","cn":"然而，宽恕往往是最有利于健康的前进之路。"},{"sp":"听力篇章 1","en":"It's important to cultivate forgiveness by developing compassion for the offender, reflect on whether the act was due to malicious intent, or whether it was caused by challenging circumstances in the offender's life.","cn":"重要的是，要通过对冒犯者培养同情心来促进宽恕，并反思这一行为究竟是出于恶意，还是由冒犯者生活中的艰难处境所导致。"},{"sp":"听力篇章 1","en":"What about forgiving ourselves?","cn":"那么，宽恕自己又如何呢？"},{"sp":"听力篇章 1","en":"We sometimes need to take responsibility for mistakes, but intense guilt and shame aren't a desirable outcome in the long run.","cn":"我们有时需要为自己的错误承担责任，但从长远来看，强烈的内疚和羞耻并不是理想的结果。"},{"sp":"听力篇章 1","en":"Forgiving yourself may seem like an ambiguous process.","cn":"宽恕自己似乎是一个模糊不清的过程。"},{"sp":"听力篇章 1","en":"You can begin by acknowledging that you are at fault, taking responsibility for the hurt you caused, then reflecting on why the event occurred.","cn":"你可以先承认自己有错，为自己造成的伤害承担责任，然后反思这一事件发生的原因。"},{"sp":"听力篇章 1","en":"Draw the lessons you learned and try to avoid committing a similar offense in the future.","cn":"总结你从中吸取的教训，并努力避免今后犯下类似的过错。"},{"sp":"听力篇章 2","en":"The Glasgow subway first opened in 1896 as a cable-hauled system.","cn":"格拉斯哥地铁于1896年首次开通，当时采用缆索牵引系统。"},{"sp":"听力篇章 2","en":"It is generally recognised as the world's third underground railway, after London and Budapest.","cn":"人们普遍认为，它是继伦敦和布达佩斯之后世界上第三条地下铁路。"},{"sp":"听力篇章 2","en":"In its long history, it has never been expanded, remaining as a single loop line with a mere 15 stations.","cn":"在其漫长的历史中，线路从未扩建，始终是一条仅有15个车站的单环线。"},{"sp":"听力篇章 2","en":"At its peak, it served the shipyard workers on the south side of the city.","cn":"它在鼎盛时期为城市南部的造船厂工人提供服务。"},{"sp":"听力篇章 2","en":"In the 1960s, there was a decline in the shipbuilding industry and the popularity of private transport grew.","cn":"20世纪60年代，造船业衰落，私人交通工具日益普及。"},{"sp":"听力篇章 2","en":"As a result, the subway saw a rapid decline in ridership.","cn":"因此，地铁客流量迅速下降。"},{"sp":"听力篇章 2","en":"It ran with little further change until 1977 when its new operators closed it for major modernisation investment.","cn":"此后，地铁基本没有进一步变化，直到1977年，新运营方因进行重大现代化投资而关闭了地铁。"},{"sp":"听力篇章 2","en":"Carriages were replaced, ventilation was improved, and the main depot was also renovated and fitted with connecting tracks to replace the outdated crane transfer mechanism.","cn":"车厢被更换，通风系统得到改善，主车库也进行了翻修，并增设了连接轨道，以取代过时的起重机转运机制。"},{"sp":"听力篇章 2","en":"The subway in its present form reopened for operation in April 1980.","cn":"现有形式的地铁于1980年4月重新投入运营。"},{"sp":"听力篇章 2","en":"Since its relaunch, the subway has seen a revival in its fortunes.","cn":"重新启用以来，地铁的境况有所好转。"},{"sp":"听力篇章 2","en":"It serves as a viable alternative to other forms of transport and has gone a long way to alleviate traffic jams in the city centre.","cn":"它成为其他交通方式的可行替代方案，并在很大程度上缓解了市中心的交通拥堵。"},{"sp":"听力篇章 2","en":"In 1996, the system reached an important milestone—100 years.","cn":"1996年，该系统迎来了一个重要里程碑——建成100周年。"},{"sp":"听力篇章 2","en":"To commemorate this special event, the colour scheme of the train carriages was updated.","cn":"为纪念这一特殊事件，列车车厢的配色方案进行了更新。"},{"sp":"听力篇章 2","en":"Recently, high-tech systems such as smart card ticketing machines and smart gates are used across all subway stations.","cn":"近年来，智能卡售票机和智能闸机等高科技系统已在所有地铁车站投入使用。"},{"sp":"听力篇章 2","en":"The smart card provides more convenient travel, and passengers simply top up their cards and tap them to get in and out the subway.","cn":"智能卡使出行更加便捷，乘客只需为卡充值，然后刷卡即可进出地铁。"},{"sp":"听力篇章 2","en":"Since its launch, the technology has been adopted by more than 100,000 subway customers.","cn":"自推出以来，这项技术已被超过10万名地铁乘客采用。"},{"sp":"讲座 1","en":"If you visit the Great Smoky Mountains National Park, chances are you will remember the roadside or campground bears above all else.","cn":"如果你游览大烟山国家公园，那么最有可能让你始终记忆犹新的，莫过于路边或露营地的熊。"},{"sp":"讲座 1","en":"Bears are the most popular animals in a number of our national parks.","cn":"在我们的一些国家公园里，熊是最受欢迎的动物。"},{"sp":"讲座 1","en":"In these mountains, where the population of bears runs into the hundreds, opportunities to observe these large wild animals are plentiful during the summer.","cn":"在这片熊的数量达到数百只的山地，夏季有许多机会观察这些大型野生动物。"},{"sp":"讲座 1","en":"Since national parks are wildlife sanctuaries where no disturbance of the native animals is allowed, years of protection have served to break down the wild bears' fear of humans.","cn":"由于国家公园是野生动物保护区，不允许干扰当地动物，多年的保护已经逐渐消除了野熊对人类的恐惧。"},{"sp":"讲座 1","en":"Now, instead of depending on their own resources for a living, many bears patrol park roads and campgrounds.","cn":"如今，许多熊不再依靠自身能力谋生，而是在公园道路和露营地巡游。"},{"sp":"讲座 1","en":"They give the garbage cans a frequent going over.","cn":"它们经常翻找垃圾桶。"},{"sp":"讲座 1","en":"An occasional offer of food from a park visitor, an illegal and dangerous practice, makes beggars of them.","cn":"公园游客偶尔提供食物，这种违法且危险的行为使它们变成了乞食者。"},{"sp":"讲座 1","en":"Bears are very often hungry and since they will feed on almost any kind of plant or animal, garbage is quite acceptable.","cn":"熊常常处于饥饿状态，而且几乎什么植物或动物都吃，因此垃圾对它们来说完全可以接受。"},{"sp":"讲座 1","en":"Feeding them, however, represents misguided kindness because the bears come to expect such generosity from everyone and consequently, trouble could lie ahead.","cn":"然而，给它们喂食是一种出于好心却考虑不周的行为，因为熊会开始期待每个人都这样慷慨相待，因而可能引发麻烦。"},{"sp":"讲座 1","en":"Park rules prohibit the feeding of bears.","cn":"公园规定禁止给熊喂食。"},{"sp":"讲座 1","en":"Violators are arrested.","cn":"违反者会被逮捕。"},{"sp":"讲座 1","en":"Every year, doctors who have offices near the park treat a number of cases of bear bites and bear scratches.","cn":"每年，在公园附近设有诊所的医生都会治疗一些被熊咬伤或抓伤的病例。"},{"sp":"讲座 1","en":"Some of the accidents have come about in strange ways.","cn":"有些事故的发生方式十分奇特。"},{"sp":"讲座 1","en":"One man was in the process of feeding two small cubs, when the mother bear appeared and insisted upon having some of the food.","cn":"有一个人在给两只小熊崽喂食时，母熊出现了，并坚持要分得一些食物。"},{"sp":"讲座 1","en":"Shoving the big bear aside with one hand, the man continued feeding the cubs when suddenly he was struck a fierce blow in the face.","cn":"那人用一只手把大熊推到一边，继续给熊崽喂食，突然被熊狠狠地打了一下脸。"},{"sp":"讲座 1","en":"A bear, prompted by the food that a lady kept offering to him, entered the car where the generous person was sitting.","cn":"一头熊受到一位女士不断递给它食物的诱惑，进入了这位热心人所坐的汽车。"},{"sp":"讲座 1","en":"Her efforts to push the bear out of the car resulted in injuries.","cn":"她试图把熊推出车外，结果受了伤。"},{"sp":"讲座 1","en":"A man required medical attention after he applied a lighted cigarette to a bear's nose.","cn":"一名男子把点燃的香烟放到熊的鼻子上，随后需要接受医疗救治。"},{"sp":"讲座 1","en":"Another man tried to boost a bear into the front seat of his car so that he might take a picture of a bear sitting beside his wife who was behind the wheel.","cn":"还有一名男子试图把一头熊抱进自己汽车的前排座位，好给熊拍照，照片中熊将坐在驾驶座后面、与他的妻子并排。"},{"sp":"讲座 1","en":"Because bears prefer roads and campgrounds, the possibility of a hiker meeting up with a bear along park trails is small, but there's always that chance, for a bear seems to know if you are carrying a lunch or a candy bar.","cn":"由于熊更喜欢道路和露营地，徒步者在公园小径上遇到熊的可能性很小，但这种情况始终有可能发生，因为熊似乎知道你是否带着午餐或巧克力棒。"},{"sp":"讲座 1","en":"He may even insist on taking it.","cn":"它甚至可能坚持要把食物拿走。"},{"sp":"讲座 2","en":"Why do we form opinions or attitudes about someone or something without really knowing much about them?","cn":"为什么我们会在并不真正了解某个人或某件事的情况下，就对其形成看法或态度？"},{"sp":"讲座 2","en":"Just hearing something good or bad about a person, a place or thing can influence our opinions positively or negatively.","cn":"仅仅听到一些关于某个人、某个地方或某件事的好或坏的说法，就可能对我们的看法产生积极或消极的影响。"},{"sp":"讲座 2","en":"But letting the opinions of another person determine what our opinions will be is dangerous.","cn":"但是，让他人的看法决定我们自己的看法是危险的。"},{"sp":"讲座 2","en":"Forming opinions about someone or something before really knowing them well is called prejudice.","cn":"在真正充分了解某个人或某件事之前就对其形成看法，这叫作偏见。"},{"sp":"讲座 2","en":"\"Pre-\" means before, and \"judice\" refers to judgment.","cn":"“Pre-”意为“之前”，“judice”指的是判断。"},{"sp":"讲座 2","en":"Hence, prejudice means to judge before having adequate knowledge.","cn":"因此，偏见就是在获得充分了解之前作出判断。"},{"sp":"讲座 2","en":"We can be prejudiced toward or against someone or something. In either case, we are only allowing ourselves to see half of the picture. Very few people or things in this world are all good or all bad. Prejudiced attitudes are usually based on myths, half-truths or incorrect information, and they are dangerous because they can keep us from learning the truth about someone or something. People form prejudices against others for many reasons—differences in their race, religion, gender, or occupation. Prejudices keep people apart. They keep us from really knowing and understanding each other.","cn":"我们可能会对某个人或某件事抱有偏见，也可能持反对态度。无论是哪种情况，我们都只是允许自己看到事情的一半。这个世界上很少有人或事物是全然美好或全然糟糕的。偏见通常建立在神话、半真半假的说法或错误信息之上，而它们之所以危险，是因为可能使我们无法了解某个人或某件事的真相。人们会因为许多原因对他人产生偏见，例如种族、宗教、性别或职业方面的差异。偏见使人彼此隔绝，也使我们无法真正了解和理解彼此。"},{"sp":"讲座 2","en":"We should feel proud of who we are and the group of people we represent.","cn":"我们应当为自己的身份以及所代表的群体感到自豪。"},{"sp":"讲座 2","en":"If feelings of pride begin to turn to feelings of superiority when we think that our group or our beliefs are better than those around us, however, then we begin to develop prejudiced attitudes that can be harmful.","cn":"然而，当我们认为自己的群体或信仰比身边的人更好时，自豪感开始转变为优越感，我们就开始形成可能造成伤害的偏见态度。"},{"sp":"讲座 2","en":"For example, the prejudiced attitudes of one group may keep another group from attending certain schools, from living in any neighborhood they want, or from getting a job or a promotion.","cn":"例如，一个群体的偏见态度可能使另一个群体无法进入某些学校、无法居住在自己想住的任何社区，或者无法获得工作或晋升。"},{"sp":"讲座 2","en":"Extreme feelings of prejudice have caused the deaths of innocent people.","cn":"极端的偏见情绪曾导致无辜者死亡。"},{"sp":"讲座 2","en":"We are responsible for our own thoughts and opinions.","cn":"我们应当为自己的思想和看法负责。"},{"sp":"讲座 2","en":"When we let someone else tell us what to think about someone or something, we are giving up some control of our own lives.","cn":"当我们让别人告诉自己应当如何看待某个人或某件事时，我们就放弃了对自己生活的一部分掌控权。"},{"sp":"讲座 2","en":"Before you form an attitude or opinion, find out for yourself about the person or the thing in question.","cn":"在形成某种态度或看法之前，要亲自了解有关的人或事。"},{"sp":"讲座 2","en":"Sometimes we don't realize that we hold prejudiced attitudes toward or against someone or something.","cn":"有时，我们并没有意识到自己对某个人或某件事抱有偏见。"},{"sp":"讲座 2","en":"We need to carefully examine our lives and our fears, and to ask ourselves whether our attitudes come from our personal knowledge and experience or from rumors and fear of the unknown.","cn":"我们需要认真审视自己的生活和恐惧，并问问自己：我们的态度是源于个人的知识和经历，还是源于传闻以及对未知事物的恐惧。"},{"sp":"讲座 2","en":"The good news about prejudice is that we are not born with it.","cn":"关于偏见，好消息是我们并非天生就有偏见。"},{"sp":"讲座 2","en":"Prejudiced attitudes and opinions develop over time.","cn":"偏见性的态度和看法会随着时间逐渐形成。"},{"sp":"讲座 2","en":"But with education and knowledge, we can replace our prejudices with cooperation and understanding.","cn":"但是，通过教育和知识，我们可以用合作与理解取代偏见。"},{"sp":"讲座 3","en":"When I started high school, it was a shock.","cn":"我刚开始上高中时，受到很大冲击。"},{"sp":"讲座 3","en":"I had spent eight years fighting my way to be the most popular kid in the Catholic school student body.","cn":"我花了八年时间，努力争取成为天主教学校学生群体中最受欢迎的孩子。"},{"sp":"讲座 3","en":"I had been a big, tough 8th grader and suddenly I was a lonely 9th grader bullied by the big, tough 12th grade seniors who ran the high school.","cn":"那时我还是个强壮、坚强的八年级学生，却突然成了一个孤独的九年级学生，受到那些掌控着高中的强壮、强悍的十二年级学长们的欺负。"},{"sp":"讲座 3","en":"I realized then that it's nice to strive for something, but that you also have to enjoy the moment you're in and be happy where you are.","cn":"那时我意识到，为某件事努力奋斗固然很好，但你也必须享受当下，满足于自己所处的位置。"},{"sp":"讲座 3","en":"Rock and roll had always been an important part of my life.","cn":"摇滚乐一直是我生活中重要的一部分。"},{"sp":"讲座 3","en":"I remember my friends and I used to drive around until the late hours of the nights listening to the music of Rock and Roll legends.","cn":"我记得，我和朋友们过去常常开车在外面兜风，直到深夜，同时聆听摇滚乐传奇人物的音乐。"},{"sp":"讲座 3","en":"During those teenage years, I built friendships that I thought would last a lifetime.","cn":"在那些青少年时期，我结交了一些我以为会维持一生的友谊。"},{"sp":"讲座 3","en":"Most people that age think the same thing, but people drift apart.","cn":"那个年纪的大多数人都有同样的想法，但人们会渐行渐远。"},{"sp":"讲座 3","en":"Jobs, families and tragedies separate people from those lasting friendships.","cn":"工作、家庭和悲剧会使人们与那些长久的友谊分离。"},{"sp":"讲座 3","en":"The tragedy that separated me from my friends forever was the Vietnam War.","cn":"使我与朋友们永远分离的悲剧是越南战争。"},{"sp":"讲座 3","en":"A year after I graduated from high school, I left for Vietnam.","cn":"高中毕业一年后，我去了越南。"},{"sp":"讲座 3","en":"I came back, burned out, and tired, as though I had lived 10 lifetimes in the short span of 14 months, the 14 months I was in the war.","cn":"战争持续的14个月里，我仿佛在短短14个月内经历了十辈子的人生；回来时，我身心俱疲，筋疲力尽。"},{"sp":"讲座 3","en":"I couldn't relate to the friends I had had in high school.","cn":"我无法再与高中时的朋友们产生共鸣。"},{"sp":"讲座 3","en":"They still seemed childish, concerned with childish things that weren't important to me.","cn":"他们看起来仍然很幼稚，关心着一些对我来说并不重要的幼稚事情。"},{"sp":"讲座 3","en":"I was still trying to cope with the death, destruction and evil I had seen in Vietnam.","cn":"我仍在努力应对自己在越南见到的死亡、毁灭和邪恶。"},{"sp":"讲座 3","en":"I felt like we had done terrible things to innocent people there and in turn, I had seen terrible things done to my friends.","cn":"我觉得我们在那里对无辜的人做了可怕的事情，而反过来，我也亲眼看到了我的朋友们遭受可怕的伤害。"},{"sp":"讲座 3","en":"I withdrew from my friends and started college.","cn":"我与朋友们疏远了，开始上大学。"},{"sp":"讲座 3","en":"Then I quit college and took many different jobs.","cn":"后来我辍学了，做过许多不同的工作。"},{"sp":"讲座 3","en":"I spent a lot of my time and money on alcohol and other drugs.","cn":"我把大量时间和金钱花在酒精和其他毒品上。"},{"sp":"讲座 3","en":"Finally, in an effort to get my life going in the right direction again, I sold everything and took what little money I had and bought myself an airplane ticket to Israel.","cn":"最后，为了让自己的生活重新走上正轨，我卖掉了所有东西，拿着仅有的一点钱给自己买了一张去以色列的机票。"},{"sp":"讲座 3","en":"I went there to study history.","cn":"我去那里学习历史。"},{"sp":"讲座 3","en":"While studying at Haifa University, I met my wife, who was also an American student.","cn":"在海法大学学习期间，我遇到了我的妻子，她也是一名美国学生。"},{"sp":"讲座 3","en":"I now teach in a high school back in America.","cn":"现在，我在美国的一所高中任教。"},{"sp":"讲座 3","en":"I look at my students and see them struggling with many of the very things I struggled with many years ago.","cn":"我看着我的学生，发现他们正在努力应对许多年前我自己曾经面对过的那些事情。"},{"sp":"讲座 3","en":"As a teacher, I try to help them over the rough spots as best I can.","cn":"作为一名教师，我尽我所能帮助他们渡过那些艰难的阶段。"}]}];
